export const dtlSentences: Sentence[] = [
  {"id":"s_work_dtl_1_1","chapterId":"ch_work_dtl_1","text":"卷一","sortOrder":1},
  {"id":"s_work_dtl_1_2","chapterId":"ch_work_dtl_1","text":"◎本議第一","sortOrder":2},
  {"id":"s_work_dtl_1_3","chapterId":"ch_work_dtl_1","text":"惟始元六年，有詔書使丞相、御史與所舉賢良、文學語。問民間所疾苦。","sortOrder":3},
  {"id":"s_work_dtl_1_4","chapterId":"ch_work_dtl_1","text":"文學對曰：“竊聞治人之道，防淫佚之原，廣道德之端，抑末利而开仁義，毋示以利，然後教化可興，而風俗可移也。今郡國有鹽、鐵、酒榷、均输，與民爭利。散敦厚之朴，成貪鄙之化。是以百姓就本者寡，趨末者眾。夫文繁則质衰，末盛則本虧。末修則民淫，本修則民悫。民悫則财用足，民侈則飢寒生。願罢鹽、鐵、酒榷、均输，所以進本退末，廣利農業，便也。”","sortOrder":4},
  {"id":"s_work_dtl_1_5","chapterId":"ch_work_dtl_1","text":"大夫曰：“匈奴背叛不臣，數為寇暴於邊鄙，備之則勞中國之士，不備則侵盜不止。先帝哀邊人之久患，苦為虜所系獲也，故修障塞，飭烽燧，屯戍以備之。邊用度不足，故興鹽、鐵，設酒榷，置均输，蕃货長财，以佐助邊費。今議者欲罢之，內空府库之藏，外乏執備之用，使備塞乘城之士飢寒於邊，將何以贍之？罢之，不便也。”","sortOrder":5},
  {"id":"s_work_dtl_1_6","chapterId":"ch_work_dtl_1","text":"文學曰：“孔子曰：‘有國有家者，不患貧而患不均，不患寡而患不安。’故天子不言多少，諸侯不言利害，大夫不言得丧。畜仁義以風之，廣德行以懷之。是以近者親附而遠者悅服。故善克者不戰，善戰者不師，善師者不陣。修之於廟堂，而折冲還師。王者行仁政，無敵於天下，惡用費哉？”","sortOrder":6},
  {"id":"s_work_dtl_1_7","chapterId":"ch_work_dtl_1","text":"大夫曰：“匈奴桀黠，擅恣入塞，犯厲中國，殺伐郡、縣、朔方都尉，甚悖逆不軌，宜誅讨之日久矣。陛下垂大惠，哀元元之未贍，不忍暴士大夫於原野；縱難被堅執銳，有北面复匈奴之志，又欲罢鹽、鐵、均输，扰邊用，損武略，無忧邊之心，於其義未便也。”","sortOrder":7},
  {"id":"s_work_dtl_1_8","chapterId":"ch_work_dtl_1","text":"文學曰：“古者，貴以德而賤用兵。孔子曰：‘遠人不服，則修文德以來之。既來之，則安之。’今废道德而任兵革，興師而伐之，屯戍而備之，暴兵露師，以支久長，轉输糧食無已，使邊境之士飢寒於外，百姓勞苦於內。立鹽、鐵，始張利官以給之，非長策也。故以罢之為便也。”","sortOrder":8},
  {"id":"s_work_dtl_1_9","chapterId":"ch_work_dtl_1","text":"大夫曰：“古之立國家者，开本末之途，通有無之用，市朝以一其求，致士民，聚萬货，農商工師各得所欲，交易而退。《易》曰：‘通其变，使民不倦。’故工不出，則農用乏；商不出，則寶货絕。農用乏，則穀不殖；寶货絕，則财用匮。故鹽、鐵、均输，所以通委财而調缓急。罢之，不便也。”","sortOrder":9},
  {"id":"s_work_dtl_1_10","chapterId":"ch_work_dtl_1","text":"文學曰：“夫导民以德，則民歸厚；示民以利，則民俗薄。俗薄則背義而趨利，趨利則百姓交於道而接於市。老子曰：‘貧國若有餘，非多财也，嗜欲眾而民躁也。’是以王者崇本退末，以禮義防民欲，實菽粟货财。市、商不通無用之物，工不作無用之器。故商所以通鬱滯，工所以備器械，非治國之本務也。”","sortOrder":10},
  {"id":"s_work_dtl_1_11","chapterId":"ch_work_dtl_1","text":"大夫曰：“管子雲：‘國有沃野之饒而民不足於食者，器械不備也。有山海之货而民不足於财者，商工不備也。’隴、蜀之丹漆旄羽，荆、扬之皮革骨象，江南之楠梓竹箭，燕、齊之魚鹽旃裘，兖、豫之漆絲絺纻，養生送終之具也，待商而通，待工而成。故聖人作為舟楫之用，以通川穀，服牛駕馬，以達陵陆；致遠窮深，所以交庶物而便百姓。是以先帝建鐵官以贍農用，开均输以足民财；鹽、鐵、均输，萬民所載仰而取給者，罢之，不便也。”","sortOrder":11},
  {"id":"s_work_dtl_1_12","chapterId":"ch_work_dtl_1","text":"文學曰：“國有沃野之饒而民不足於食者，工商盛而本業荒也；有山海之货而民不足於财者，不務民用而淫巧眾也。故川源不能實漏卮，山海不能贍溪壑。是以盤庚萃居，舜藏黃金，高帝禁商贾不得仕宦，所以遏貪鄙之俗，而醇至誠之風也。排困市井，防塞利門，而民猶為非也，况上之為利乎？《傳》曰：‘諸侯好利則大夫鄙，大夫鄙則士貪，士貪則庶人盜。’是开利孔為民罪梯也。”","sortOrder":12},
  {"id":"s_work_dtl_1_13","chapterId":"ch_work_dtl_1","text":"大夫曰：“往者，郡國諸侯各以其方物貢输，往來煩雜，物多苦惡，或不偿其費。故郡國置输官以相給運，而便遠方之貢，故曰均输。开委府於京師，以籠货物。賤即買，貴則賣。是以縣官不失實，商贾無所貿利，故曰平准。平准則民不失職，均输則民齊勞逸。故平准、均输，所以平萬物而便百姓，非开利孔而為民罪梯者也。”","sortOrder":13},
  {"id":"s_work_dtl_1_14","chapterId":"ch_work_dtl_1","text":"文學曰：“古者之賦稅於民也，因其所工，不求所拙。農人納其獲，女工效其功。今釋其所有，责其所無。百姓賤賣货物，以便上求。間者，郡國或令民作布絮，吏恣留難，與之為市。吏之所入，非獨齊、阿之缣，蜀、漢之布也，亦民間之所為耳。行奸賣平，農民重苦，女工再稅，未見输之均也。縣官猥發，阖門擅市，則萬物併收。萬物併收，則物騰躍。騰躍，則商贾侔利。自市，則吏容奸。豪吏富商積货储物以待其急，輕贾奸吏收賤以取貴，未見准之平也。蓋古之均输，所以齊勞逸而便貢输，非以為利而贾萬物也。”","sortOrder":14},
  {"id":"s_work_dtl_1_15","chapterId":"ch_work_dtl_1","text":"◎力耕第二","sortOrder":15},
  {"id":"s_work_dtl_1_16","chapterId":"ch_work_dtl_1","text":"大夫曰：“王者塞天财，禁關市，執准守時，以輕重御民。丰年歲登，則储積以備乏絕；凶年惡歲，則行幣物；流有餘而調不足也。昔禹水湯旱，百姓匮乏，或相假以接衣食。禹以歷山之金，湯以莊山之銅，鑄幣以贖其民，而天下稱仁。往者财用不足，戰士或不得祿，而山東被灾，齊、趙大飢，賴均输之畜，仓廪之積，戰士以奉，飢民以赈。故均输之物，府库之财，非所以贾萬民而专奉兵師之用，亦所以赈困乏而備水旱之灾也。”","sortOrder":16},
  {"id":"s_work_dtl_1_17","chapterId":"ch_work_dtl_1","text":"文學曰：“古者，十一而稅，泽梁以時入而無禁，黎民鹹被南畝而不失其務。故三年耕而餘一年之蓄，九年耕有三年之蓄。此禹、湯所以備水旱而安百姓也。草萊不辟，田畴不治，雖擅山海之财，通百末之利，猶不能贍也。是以古者尚力務本而种树繁，躬耕趣時而衣食足，雖累凶年而人不病也。故衣食者民之本，稼穡者民之務也。二者修，則國富而民安也。《詩》雲：‘百室盈止，婦子寧止’也。”","sortOrder":17},
  {"id":"s_work_dtl_1_18","chapterId":"ch_work_dtl_1","text":"大夫曰：“賢聖治家非一寶，富國非一道。昔管仲以權譎霸，而紀氏以強本亡。使治家養生必於農，則舜不甄陶而伊尹不為庖。故善為國者，天下之下我高，天下之輕我重。以末易其本，以虛荡其實。今山泽之财，均输之藏，所以御輕重而役諸侯也。汝、漢之金，纖微之貢，所以誘外國而釣胡、羌之寶也。夫中國一端之缦，得匈奴累金之物，而損敵國之用。是以騾驢馲駝，衔尾入塞，驒騱騵馬，盡為我畜，鼲貂狐貉，采旃文罽，充於內府，而璧玉珊瑚琉璃，鹹為國之寶。是則外國之物內流，而利不外泄也。異物內流則國用饒，利不外泄則民用給矣。《詩》曰：‘百室盈止，婦子寧止。’”","sortOrder":18},
  {"id":"s_work_dtl_1_19","chapterId":"ch_work_dtl_1","text":"文學曰：“古者，商通物而不豫，工致牢而不伪。故君子耕稼田魚，其實一也。商則長诈，工則飾骂，內懷窥窬而心不怍，是以薄夫欺而敦夫薄。昔桀女樂充宮室，文繡衣裳，故伊尹高逝遊薄，而女樂終废其國。今騾驢之用，不中牛馬之功，鼲貂旃罽，不益錦绨之實。美玉珊瑚出於崑山，珠璣犀象出於桂林，此距漢萬有餘里。計耕桑之功，資财之費，是一物而售百倍其价也，一揖而中萬鐘之粟也。夫上好珍怪，則淫服下流，貴遠方之物，則货财外充。是以王者不珍無用以節其民，不愛奇货以富其國。故理民之道，在於節用尚本，分土井田而已。”","sortOrder":19},
  {"id":"s_work_dtl_1_20","chapterId":"ch_work_dtl_1","text":"大夫曰：“自京師東西南北，歷山川，經郡國，諸殷富大都，無非街衢五通，商贾之所凑，萬物之所殖者。故聖人因天時，智者因地财，上士取諸人，中士勞其形。長沮、桀溺，無百金之積，跖蹻之徒，無猗頓之富，宛、周、齊、魯，商遍天下。故乃商贾之富，或累萬金，追利乘羨之所致也。富國何必用本農，足民何必井田也？”","sortOrder":20},
  {"id":"s_work_dtl_1_21","chapterId":"ch_work_dtl_1","text":"文學曰：“洪水滔天，而有禹之績，河水泛濫，而有宣房之功。商紂暴虐，而有孟津之謀，天下煩扰，而有乘羨之富。夫上古至治，民朴而貴本、安愉而寡求。當此之時，道路罕行，市朝生草。故耕不強者無以充虛，織不強者無以掩形。雖有凑會之要，陶、宛之術，無所施其巧。自古及今，不施而得報，不勞而有功者，未之有也。”","sortOrder":21},
  {"id":"s_work_dtl_1_22","chapterId":"ch_work_dtl_1","text":"◎通有第三","sortOrder":22},
  {"id":"s_work_dtl_1_23","chapterId":"ch_work_dtl_1","text":"大夫曰：“燕之涿、蓟，趙之邯鄲，魏之溫轵，韓之滎陽，齊之臨淄，楚之宛、陳，鄭之陽翟，三川之二周，富冠海內，皆為天下名都，非有助之耕其野而田其地者也，居五諸之冲，跨街衢之路也。故物丰者民衍，宅近市者家富。富在術數，不在勞身；利在势居，不在力耕也。","sortOrder":23},
  {"id":"s_work_dtl_1_24","chapterId":"ch_work_dtl_1","text":"文學曰：“荆、扬南有桂林之饒，內有江、湖之利，左陵陽之金，右蜀、漢之材，伐木而树穀，燔萊而播粟，火耕而水耨，地廣而饒材；然民鮆窳偷生，好衣甘食，雖白屋草庐，歌謳鼓琴，日給月单，朝歌暮戚。趙、中山帶大河，纂四通神衢，當天下之蹊，商贾错於路，諸侯交於道；然民淫好末，侈靡而不務本，田畴不修，男女矜飾，家無斗筲，鳴琴在室。是以楚、趙之民，均貧而寡富。宋、衛、韓、梁，好本稼穡，編戶齊民，無不家衍人給。故利在自惜，不在势居街衢；富在俭力趣時，不在歲司羽鳩也。”","sortOrder":24},
  {"id":"s_work_dtl_1_25","chapterId":"ch_work_dtl_1","text":"大夫曰：“五行：東方木，而丹、章有金銅之山；南方火，而交趾有大海之川；西方金，而蜀、隴有名材之林；北方水，而幽都有積沙之地。此天地所以均有無而通萬物也。今吳、越之竹，隋、唐之材，不可勝用，而曹、衛、梁、宋，采棺轉尸；江、湖之魚，萊、黃之鲐，不可勝食，而邹、魯、周、韓，藜藿蔬食。天地之利無不贍，而山海之货無不富也；然百姓匮乏，财用不足，多寡不調，而天下财不散也。”","sortOrder":25},
  {"id":"s_work_dtl_1_26","chapterId":"ch_work_dtl_1","text":"文學曰：“古者，采椽不斫，茅茨不翦，衣布褐，飯土硎，鑄金為鉏，埏埴為器，工不造奇巧，世不寶不可衣食之物，各安其居，樂其俗，甘其食，便其器。是以遠方之物不交，而崑山之玉不至。今世俗坏而競於淫靡，女極纖微，工極技巧，雕素朴而尚珍怪，鑽山石而求金銀，没深淵求珠璣，設機陷求犀象，張網羅求翡翠，求蠻、貉之物以眩中國，徙邛、筰之货，致之東海，交萬里之财，曠日費功，無益於用。是以褐夫匹婦，勞罢力屈，而衣食不足也。故王者禁溢利，節漏費。溢利禁則反本，漏費節則民用給。是以生無乏資，死無轉尸也。”","sortOrder":26},
  {"id":"s_work_dtl_1_27","chapterId":"ch_work_dtl_1","text":"大夫曰：“古者，宮室有度，舆服以庸；采椽茅茨，非先生之製也。君子節奢刺俭，俭則固。昔孫叔敖相楚，妻不衣帛，馬不秣粟。孔子曰：‘不可，大俭極下。’此《蟋蟀》所為作也。《管子》曰：‘不飾宮室，則材木不可勝用，不充庖厨，則禽獸不損其寿。無末利，則本業無所出，無黼黻，則女工不施。’故工商梓匠，邦國之用，器械之備也。自古有之，非獨於此。絃高販牛於周，五羖賃車入秦，公输子以規矩，欧冶以鎔鑄。《語》曰：‘百工居肆，以致其事。’農商交易，以利本末。山居泽處，蓬蒿墝埆，财物流通，有以均之。是以多者不獨衍，少者不獨饉。若各居其處，食其食，則是橘柚不鬻，朐滷之鹽不出，旃罽不市，而吳、唐之材不用也。”","sortOrder":27},
  {"id":"s_work_dtl_1_28","chapterId":"ch_work_dtl_1","text":"文學曰：“孟子雲：‘不违農時，穀不可勝食。蠶麻以時，布帛不可勝衣也。斧斤以時，材木不可勝用。田漁以時，魚肉不可勝食。’若則飾宮室，增台榭，梓匠斫巨為小，以圓為方，上成雲氣，下成山林，則材木不足用也。男子去本為末，雕文刻鏤，以象禽獸，窮物究变，則穀不足食也。婦女飾微治細，以成文章，極伎盡巧，則絲布不足衣也。庖宰烹殺胎卵，煎炙齊和，窮極五味，則魚肉不足食也。當今世，非患禽獸不損，材木不勝，患僣侈之無窮也；非患無旃罽橘柚，患無狹庐糠糟也。”","sortOrder":28},
  {"id":"s_work_dtl_1_29","chapterId":"ch_work_dtl_1","text":"◎错幣第四","sortOrder":29},
  {"id":"s_work_dtl_1_30","chapterId":"ch_work_dtl_1","text":"大夫曰：“交幣通施，民事不及，物有所併也。計本量委，民有飢者，穀有所藏也。智者有百人之功，愚者有不更本之事。人君不調，民有相萬之富也。此其所以或储百年之餘，或不厭糟糠也。民大富，則不可以祿使也；大強，則不可以罰威也。非散聚均利者不齊。故人主積其食，守其用，製其有餘，調其不足，禁溢羨，厄利途，然後百姓可家給人足也。”","sortOrder":30},
  {"id":"s_work_dtl_1_31","chapterId":"ch_work_dtl_1","text":"文學曰：“古者，貴德而賤利，重義而輕财。三王之時，迭盛迭衰。衰則扶之，傾則定之。是以夏忠、殷敬、周文，庠序之教，恭讓之禮，粲然可得而觀也。及其後，禮義弛崩，風俗滅息，故自食祿之君子，违於義而競於财，大小相吞，激轉相傾。此所以或储百年之餘，或無以充虛蔽形也。古之仕者不穡，田者不漁，抱關击柝，皆有常秩，不得兼利盡物。如此，則愚智同功，不相傾也。《詩》雲：‘彼有遺秉，此有滯穗，伊寡婦之利。’言不盡物也。”","sortOrder":31},
  {"id":"s_work_dtl_1_32","chapterId":"ch_work_dtl_1","text":"大夫曰：“湯、文繼衰，漢興乘弊。一质一文，非苟易常也。俗弊更法，非務变古也，亦所以救失扶衰也。故教與俗改，弊與世易。夏後以玄貝，周人以紫石，後世或金錢刀布。物極而衰，終始之運也。故山泽無征，則君臣同利，刀幣無禁，則奸貞併行。夫臣富則相侈，下专利則相傾也。”","sortOrder":32},
  {"id":"s_work_dtl_1_33","chapterId":"ch_work_dtl_1","text":"文學曰：“古者，市朝而無刀幣，各以其所有易所無，抱布貿絲而已。後世即有龟貝金錢，交施之也。幣數变而民滋伪。夫救伪以质，防失以禮。湯、文繼衰，革法易化，而殷、周道興。漢初乘弊，而不改易，畜利变幣，欲以反本，是猶以煎止燔，以火止沸也。上好禮則民闇飾，上好货則下死利也。”","sortOrder":33},
  {"id":"s_work_dtl_1_34","chapterId":"ch_work_dtl_1","text":"大夫曰：“文帝之時，縱民得鑄錢、冶鐵、煮鹽。吳王擅鄣海泽，邓通专西山。山東奸猾，鹹聚吳國，秦、雍、漢、蜀因邓氏。吳、邓錢布天下，故有鑄錢之禁。禁御之法立而奸伪息，奸伪息則民不期於妄得而各務其職不反本何為？故統一，則民不二也；幣由上，則下不疑也。”","sortOrder":34},
  {"id":"s_work_dtl_1_35","chapterId":"ch_work_dtl_1","text":"文學曰：“往古，幣眾财通而民樂。其後，稍去舊幣，更行白金龟龍，民多巧新幣。幣數易而民益疑。於是废天下諸錢，而专命水衡三官作。吏匠侵利，或不中式，故有薄厚輕重。農人不習，物類比之，信故疑新，不知奸貞。商贾以美貿惡，以半易倍。買則失實，賣則失理，其疑或滋益甚。夫鑄伪金錢以有法，而錢之善惡無增損於故。擇錢則物稽滯，而用人尤被其苦。《春秋》曰：‘算不及蠻、夷則不行。’故王者外不鄣海泽以便民用，內不禁刀幣以通民施。”","sortOrder":35},
  {"id":"s_work_dtl_1_36","chapterId":"ch_work_dtl_1","text":"◎禁耕第五","sortOrder":36},
  {"id":"s_work_dtl_1_37","chapterId":"ch_work_dtl_1","text":"大夫曰：“家人有寶器，尚函匣而藏之，况人主之山海乎？夫權利之處，必在深山窮泽之中，非豪民不能通其利。異時，鹽鐵未籠，布衣有朐邴，人君有吳王，皆鹽鐵初議也。吳王专山泽之饒，薄賦其民，赈贍窮乏，以成私威。私威積而逆節之心作。夫不蚤絕其源而忧其末，若决呂梁，沛然，其所傷必多矣。太公曰：‘一家害百家，百家害諸侯，諸侯害天下，王法禁之。’今放民於權利，罢鹽鐵以資暴強，遂其貪心，眾邪群聚，私門成党，則強御日以不製，而併兼之徒奸形成也。”","sortOrder":37},
  {"id":"s_work_dtl_1_38","chapterId":"ch_work_dtl_1","text":"文學曰：“民人藏於家，諸侯藏於國，天子藏於海內。故民人以垣牆為藏閉，天子以四海為匣匮。天子適諸侯，升自阼階，諸侯納管鍵，執策而聽命，示莫為主也。是以王者不畜聚，下藏於民，遠浮利，務民之義；義禮立，則民化上。若是，雖湯、武生存於世，無所容其慮。工商之事，欧冶之任，何奸之能成？三桓专魯，六卿分晉，不以鹽鐵。故權利深者，不在山海，在朝廷；一家害百家，在萧牆，而不在朐邴也。”","sortOrder":38},
  {"id":"s_work_dtl_1_39","chapterId":"ch_work_dtl_1","text":"大夫曰：“山海有禁而民不傾；貴賤有平而民不疑。縣官設衡立准，人從所欲，雖使五尺童子適市，莫之能欺。今罢去之，則豪民擅其用而专其利。决市闾巷，高下在口吻，貴賤無常，端坐而民豪，是以養強抑弱而藏於跖也。強養弱抑，則齊民消；若眾秽之盛而害五穀。一家害百家，不在朐邴，如何也？”","sortOrder":39},
  {"id":"s_work_dtl_1_40","chapterId":"ch_work_dtl_1","text":"文學曰：“山海者，财用之寶路也。鐵器者，農夫之死士也。死士用，則仇讎滅，仇讎滅，則田野辟，田野辟而五穀熟。寶路开，則百姓贍而民用給，民用給則國富。國富而教之以禮，則行道有讓，而工商不相豫，人懷敦朴以相接，而莫相利。夫秦、楚、燕、齊，土力不同，刚柔異势，巨小之用，居句之宜，党殊俗易，各有所便。縣官籠而一之，則鐵器失其宜，而農民失其便。器用不便，則農夫罢於野而草萊不辟。草萊不辟，則民困乏。故鹽冶之處，大傲皆依山川，近鐵炭，其势鹹遠而作剧。郡中卒踐更者，多不勘，责取庸代。縣邑或以戶口賦鐵，而賤平其准。良家以道次發僦運鹽、鐵，煩費，百姓病苦之。愚竊見一官之傷千里，未睹其在朐邴也。”","sortOrder":40},
  {"id":"s_work_dtl_1_41","chapterId":"ch_work_dtl_1","text":"◎复古第六","sortOrder":41},
  {"id":"s_work_dtl_1_42","chapterId":"ch_work_dtl_1","text":"大夫曰：“故扇水都尉彭祖寧歸，言：‘鹽、鐵令品，令品甚明。卒徒衣食縣官，作鑄鐵器，給用甚眾，無妨於民。而吏或不良，禁令不行，故民煩苦之。’令意總一鹽、鐵，非獨為利入也，將以建本抑末，離朋党，禁淫侈，絕併兼之路也。古者，名山大泽不以封，為下之专利也。山海之利，廣泽之畜，天地之藏也，皆宜屬少府；陛下不私，以屬大司農，以佐助百姓。浮食奇民，好欲擅山海之货，以致富業，役利細民，故沮事議者眾。鐵器兵刃，天下之大用也，非眾庶所宜事也。往者，豪強大家，得管山海之利，采鐵石鼓鑄，煮海為鹽。一家聚眾，或至千餘人，大抵盡收放流人民也。遠去乡里，弃墳墓，依倚大家，聚深山窮泽之中，成奸伪之業，遂朋党之權，其輕為非亦大矣！今者，廣進賢之途，練擇守尉，不待去鹽、鐵而安民也。”","sortOrder":42},
  {"id":"s_work_dtl_1_43","chapterId":"ch_work_dtl_1","text":"文學曰：“扇水都尉所言，當時之權，一切之術也，不可以久行而傳世，此非明王所以君國子民之道也。《詩》雲：‘哀哉為猶，匪先民是程，匪大猶是經，維邇言是聽。’此詩人刺不通於王道，而善為權利者。孝武皇帝攘九夷，平百越，師旅數起，糧食不足。故立田官，置錢，入穀射官，救急贍不給。今陛下繼大功之勤，養勞倦之民，此用麋鬻之時；公卿宜思所以安集百姓，致利除害，辅明主以仁義，修润洪業之道。明主即位以來，六年於茲，公卿無請减除不急之官，省罢機利之人。人權縣太久，民良望於上。陛下宣聖德，昭明光，令郡國賢良、文學之士，乘傳詣公車，議五帝、三王之道，《六藝》之風，册陳安危利害之分，指意粲然。今公卿辨議，未有所定，此所謂守小節而遺大體，抱小利而忘大利者也。”","sortOrder":43},
  {"id":"s_work_dtl_1_44","chapterId":"ch_work_dtl_1","text":"大夫曰：“宇棟之內，燕雀不知天地之高；坎井之蛙，不知江海之大；窮夫否婦，不知國家之慮；負荷之商，不知猗頓之富。先帝計外國之利，料胡、越之兵，兵敵弱而易製，用力少而功大，故因势变以主四夷，地濱山海，以屬長城，北略河外，开路匈奴之乡，功未卒。蓋文王受命伐崇，作邑於丰；武王繼之，載尸以行，破商擒紂，遂成王業。曹沬弃三北之恥，而复侵地；管仲負當世之累，而立霸功。故志大者遺小，用權者離俗。有司思師望之計，遂先帝之業，志在絕胡、貉，擒单於，故未遑扣扃之義，而錄拘儒之論。”","sortOrder":44},
  {"id":"s_work_dtl_1_45","chapterId":"ch_work_dtl_1","text":"文學曰：“燕雀離巢宇而有鷹隼之忧，坎井之蛙離其居而有蛇鼠之患，况翱翔千仞而遊四海乎？其禍必大矣！此李斯所以折翼，而趙高没淵也。聞文、武受命，伐不義以安諸侯大夫，未聞弊諸夏以役夷、狄也。昔秦常舉天下之力以事胡、越，竭天下之财以奉其用，然眾不能畢；而以百萬之師，為一夫之任，此天下共聞也。且數戰則民勞，久師則兵弊，此百姓所疾苦，而拘儒之所忧也。”","sortOrder":45},
  {"id":"s_work_dtl_1_46","chapterId":"ch_work_dtl_1","text":"《鹽鐵論》　西漢桓宽","sortOrder":46},
  {"id":"s_work_dtl_2_1","chapterId":"ch_work_dtl_2","text":"卷二","sortOrder":1},
  {"id":"s_work_dtl_2_2","chapterId":"ch_work_dtl_2","text":"◎非鞅第七","sortOrder":2},
  {"id":"s_work_dtl_2_3","chapterId":"ch_work_dtl_2","text":"大夫曰：“昔商君相秦也，內立法度，嚴刑罰，飭政教，奸伪無所容。外設百倍之利，收山泽之稅，國富民強，器械完飾，蓄積有餘。是以征敵伐國，攘地斥境，不賦百姓而師以贍。故利用不竭而民不知，地盡西河而民不苦。鹽、鐵之利，所以佐百姓之急，足軍旅之費，務蓄積以備乏絕，所給甚眾，有益於國，無害於人。百姓何苦爾，而文學何忧也？”","sortOrder":3},
  {"id":"s_work_dtl_2_4","chapterId":"ch_work_dtl_2","text":"文學曰：“昔文帝之時，無鹽、鐵之利而民富；今有之而百姓困乏，未見利之所利也，而見其害也。且利不從天來，不從地出，一取之民間，謂之百倍，此計之失者也。無異於愚人反裘而負薪，愛其毛，不知其皮盡也。夫李梅實多者，來年為之衰；新穀熟而舊穀為之虧。自天地不能兩盈，而况於人事乎？故利於彼者必耗於此，猶陰陽之不併曜，晝夜之有長短也。商鞅峭法長利，秦人不聊生，相與哭孝公。吳起長兵攻取，楚人搔動，相與泣悼王。其後楚日以危，秦日以弱。故利蓄而怨積，地廣而禍構，惡在利用不竭而民不知，地盡西河而人不苦也？今商鞅之册任於內，吳起之兵用於外，行者勤於路，居者匮於室，老母號泣，怨女叹息；文學雖欲無忧，其可得也？”","sortOrder":4},
  {"id":"s_work_dtl_2_5","chapterId":"ch_work_dtl_2","text":"大夫曰：“秦任商君，國以富強，其後卒併六國而成帝業。及二世之時，邪臣擅斷，公道不行，諸侯叛弛，宗廟隳亡。《春秋》曰：‘末言爾，祭仲亡也。’夫善歌者使人續其聲，善作者使人紹其功。椎車之蝉攫，負子之教也。周道之成，周公之力也。雖有裨諶之草創，無子產之润色，有文、武之規矩，而無周、呂之凿枘，則功業不成。今以趙高之亡秦而非商鞅，猶以崇虎亂殷而非伊尹也。”","sortOrder":5},
  {"id":"s_work_dtl_2_6","chapterId":"ch_work_dtl_2","text":"文學曰：“善凿者建周而不拔，善基者致高而不蹶。伊尹以尧、舜之道為殷國基，子孫紹位，百代不絕。商鞅以重刑峭法為秦國基，故二世而奪。刑既嚴峻矣，又作為相坐之法，造誹謗，增肉刑，百姓斋栗，不知所措手足也。賦斂既煩數矣，又外禁山泽之原，內設百倍之利，民無所开說容言。崇利而簡義，高力而尚功，非不廣壤進地也，然猶人之病水，益水而疾深，知其為秦开帝業，不知其為秦致亡道也。狐刺之凿，雖公输子不能善其枘。畚土之基，雖良匠不能成其高。譬若秋蓬被霜，遭風則零落，雖有十子產，如之何？故扁鵲不能肉白骨，微、箕不能存亡國也。”","sortOrder":6},
  {"id":"s_work_dtl_2_7","chapterId":"ch_work_dtl_2","text":"大夫曰：“言之非難，行之為難。故賢者處實而效功，亦非徒陳空文而已。昔商君明於开塞之術，假當世之權，為秦致利成業，是以戰勝攻取，併近滅遠，乘燕、趙，陵齊、楚，諸侯斂衽，西面而向風。其後，蒙恬征胡，斥地千里，逾之河北，若坏朽折腐。何者？商君之遺謀，備飭素修也。故舉而有利，動而有功。夫畜積筹策，國家之所以強也。故弛废而歸之民，未睹巨計而涉大道也。”","sortOrder":7},
  {"id":"s_work_dtl_2_8","chapterId":"ch_work_dtl_2","text":"文學曰：“商鞅之开塞，非不行也；蒙恬却胡千里，非無功也；威震天下，非不強也；諸侯隨風西面，非不從也；然而皆秦之所以亡也。商鞅以權數危秦國，蒙恬以得千里亡秦社稷：此二子者，知利而不知害，知進而不知退，故果身死而眾败。此所謂恋朐之智，而愚人之計也，夫何大道之有？故曰：‘小人先合而後忤，初雖乘馬，卒必泣血。’此之謂也。”","sortOrder":8},
  {"id":"s_work_dtl_2_9","chapterId":"ch_work_dtl_2","text":"大夫曰：“淑好之人，戚施之所妒也；賢知之士，阘茸之所惡也。是以上官大夫短屈原於頃襄，公伯寮愬子路於季孫。夫商君起布衣，自魏入秦，期年而相之，革法明教，而秦人大治。故兵動而地割，兵休而國富。孝公大說，封之於、商之地方五百里，功如丘山，名傳後世。世人不能為，是以相與嫉其能而疵其功也。”","sortOrder":9},
  {"id":"s_work_dtl_2_10","chapterId":"ch_work_dtl_2","text":"文學曰：“君子進必以道，退不失義，高而勿矜，勞而不伐，位尊而行恭，功大而理順；故俗不疾其能，而世不妒其業。今商鞅弃道而用權，废德而任力，峭法盛刑，以虐戾為俗，欺舊交以為功，刑公族以立威，無恩於百姓，無信於諸侯，人與之為怨，家與之為讎，雖以獲功見封，猶食毒肉愉飽而罹其咎也。蘇秦合縱連橫，統理六國，業非不大也；桀、紂與尧、舜併稱，至今不亡，名非不長也；然非者不足貴。故事不苟多，名不苟傳也。”","sortOrder":10},
  {"id":"s_work_dtl_2_11","chapterId":"ch_work_dtl_2","text":"大夫曰：“縞素不能自分於緇墨，賢聖不能自理於亂世。是以箕子執囚，比幹被刑。伍員相阖闾以霸，夫差不道，流而殺之。樂毅信功於燕昭，而見疑於惠王。人臣盡節以徇名，遭世主之不用。大夫种辅翼越王，為之深謀，卒擒強吳，據有東夷，終賜屬鏤而死。驕主背恩德，聽流說，不計其功故也，豈身之罪哉？”","sortOrder":11},
  {"id":"s_work_dtl_2_12","chapterId":"ch_work_dtl_2","text":"文學曰：“比幹剖心，子胥鴟夷，非輕犯君以危身，強諫以幹名也。忄朁怛之忠誠，心動於內，忘禍患之發於外，志在匡君救民，故身死而不怨。君子能行是不能御非，雖在刑戮之中，非其罪也。是以比幹死而殷人怨，子胥死而吳人恨。今秦怨毒商鞅之法，甚於私仇，故孝公卒之日，舉國而攻之，東西南北莫可奔走，仰天而叹曰：‘嗟乎，為政之弊，至於斯極也！’卒車裂族夷，為天下笑。斯人自殺，非人殺之也。”","sortOrder":12},
  {"id":"s_work_dtl_2_13","chapterId":"ch_work_dtl_2","text":"◎晁错第八","sortOrder":13},
  {"id":"s_work_dtl_2_14","chapterId":"ch_work_dtl_2","text":"大夫曰：“《春秋》之法，君親無將，將而必誅。故臣罪莫重於弒君，子罪莫重於弒父。日者，淮南、衡山修文學，招四方遊士，山東儒、墨鹹聚於江、淮之間，講議集論，著書數十篇。然卒於背義不臣，使謀叛逆，誅及宗族。晁错变法易常，不用製度，迫蹙宗室，侵削諸侯，蕃臣不附，骨肉不親，吳、楚積怨，斬错東市，以慰三軍之士而謝諸侯。斯亦誰殺之乎？”","sortOrder":14},
  {"id":"s_work_dtl_2_15","chapterId":"ch_work_dtl_2","text":"文學曰：“孔子不飲盜泉之流，曾子不入勝母之闾。名且惡之，而况為不臣不子乎？是以孔子沐浴而朝，告之哀公。陳文子有馬十乘，弃而违之。《傳》曰：‘君子可貴可賤，可刑可殺，而不可使為亂。’若夫外飾其貌而內無其實，口誦其文而行不猶其道，是盜，固與盜而不容於君子之域。《春秋》不以寡犯眾，誅絕之義有所止，不兼怨惡也。故舜之誅，誅鯀；其舉，舉禹。夫以玙璠之玼，而弃其璞，以一人之罪，而兼其眾，則天下無美寶信士也。晁生言諸侯之地大，富則驕奢，急即合從。故因吳之過而削之會稽，因楚之罪而奪之東海，所以均輕重，分其權，而為萬世慮也。絃高誕於秦而信於鄭，晁生忠於漢而讎於諸侯。人臣各死其主，為其國用，此解楊之所以厚於晉而薄於荆也。”","sortOrder":15},
  {"id":"s_work_dtl_2_16","chapterId":"ch_work_dtl_2","text":"◎刺權第九","sortOrder":16},
  {"id":"s_work_dtl_2_17","chapterId":"ch_work_dtl_2","text":"大夫曰：“今夫越之具區，楚之雲夢，宋之鉅野，齊之孟諸，有國之富而霸王之資也。人君統而守之則強，不禁則亡。齊以其腸胃予人，家強而不製，枝大而折幹，以专巨海之富而擅魚鹽之利也。势足以使眾，恩足以恤下，是以齊國內倍而外附。權移於臣，政墜於家，公室卑而田宗強，轉轂遊海者蓋三千乘，失之於本而末不可救。今山川海泽之原，非獨雲夢、孟諸也。鼓鑄煮鹽，其势必深居幽穀，而人民所罕至。奸猾交通山海之际，恐生大奸。乘利驕溢，散朴滋伪，則人之貴本者寡。大農鹽鐵丞鹹陽、孔仅等上請：‘願募民自給費，因縣官器，煮鹽予用，以杜浮伪之路。’由此觀之：令意所禁微，有司之慮亦遠矣。”","sortOrder":17},
  {"id":"s_work_dtl_2_18","chapterId":"ch_work_dtl_2","text":"文學曰：“有司之慮遠，而權家之利近；令意所禁微，而僣奢之道著。自利害之設，三業之起，貴人之家，雲行於途，轂击於道，攘公法，申私利，跨山泽，擅官市，非特巨海魚鹽也；執國家之柄，以行海內，非特田常之势、陪臣之權也；威重於六卿，富累於陶、衛，舆服僣於王公，宮室溢於製度，併兼列宅，隔絕闾巷，閣道错連，足以遊觀，凿池曲道，足以騁骛，臨淵釣魚，放犬走兔，隆豺鼎力，蹋鞠斗雞，中山素女撫流征於堂上，鳴鼓巴俞作於堂下，婦女被羅紈，婢妾曳絺纻，子孫連車列騎，田獵出入，畢弋捷健。是以耕者釋耒而不勤，百姓冰釋而懈怠。何者？己為之而彼取之，僣侈相效，上升而不息，此百姓所以滋伪而罕歸本也。”","sortOrder":18},
  {"id":"s_work_dtl_2_19","chapterId":"ch_work_dtl_2","text":"大夫曰：“官尊者祿厚，本美者枝茂。故文王德而子孫封，周公相而伯禽富。水廣者魚大，父尊者子貴。《傳》曰：‘河、海润千里。’盛德及四海，况之妻子乎？故夫貴於朝，妻貴於室，富曰苟美，古之道也。《孟子》曰：‘王者與人同，而如彼者，居使然也。’居編戶之列，而望卿相之子孫，是以跛夫之欲及樓季也，無錢而欲千金之寶，不亦虛望哉？”","sortOrder":19},
  {"id":"s_work_dtl_2_20","chapterId":"ch_work_dtl_2","text":"文學曰：“禹、稷自布衣，思天下有不得其所者，若己推而納之溝中，故起而佐尧，平治水土，教民稼穡。其自任天下如此其重也，豈雲食祿以養妻子而已乎？夫食萬人之力者，蒙其忧，任其勞。一人失職，一官不治，皆公卿之累也。故君子之仕，行其義，非樂其势也。受祿以润賢，非私其利。見賢不隱，食祿不专，此公叔之所以為文，魏成子所以為賢也。故文王德成而後封子孫，天下不以為党，周公功成而後受封，天下不以為貪。今則不然。親戚相推，朋党相舉，父尊於位，子溢於內，夫貴於朝，妻謁行於外。無周公之德而有其富，無管仲之功而有其侈，故編戶跛夫而望疾步也。”","sortOrder":20},
  {"id":"s_work_dtl_2_21","chapterId":"ch_work_dtl_2","text":"◎刺复第十","sortOrder":21},
  {"id":"s_work_dtl_2_22","chapterId":"ch_work_dtl_2","text":"大夫為色矜而心不怿，曰：“但居者不知負載之勞，從旁議者與當局者異忧。方今為天下腹居郡，諸侯併臻，中外未然，心憧憧若涉大川，遭風而未薄。是以夙夜思念國家之用，寢而忘寐，飢而忘食，計數不離於前，萬事簡閱於心。丞史器小，不足與謀，獨鬱大道，思睹文學，若俟周、邵而望高子。御史案事郡國，察廉舉賢才，歲不乏也。今賢良、文學臻者六十餘人，懷《六藝》之術，騁意極論，宜若开光發蒙；信往而乖於今，道古而不合於世務。意者不足以知士也？將多飾文誣能以亂實邪？何賢士之難睹也！自千乘倪宽以治《尚書》位冠九卿，及所聞睹選舉之士，擢升贊憲甚顯，然未見絕倫比，而為縣官興滯立功也。”","sortOrder":22},
  {"id":"s_work_dtl_2_23","chapterId":"ch_work_dtl_2","text":"文學曰：“输子之製材木也，正其規矩而凿枘調。師曠之諧五音也，正其六律而宮商調。當世之工匠，不能調其凿枘，則改規矩，不能协聲音，則变舊律。是以凿枘刺戾而不合，聲音泛越而不和。夫舉規矩而知宜，吹律而知变，上也；因循而不作，以俟其人，次也。是以曹丞相日飲醇酒，倪大夫閉口不言。故治大者不可以煩，煩則亂；治小者不可以怠，怠則废。《春秋》曰：‘其政恢卓，恢卓可以為卿相。其政察察，察察可以為匹夫。’夫維綱不張，禮義不行，公卿之忧也。案上之文，期會之事，丞史之任也。《尚書》曰：‘俊乂在官，百僚師師，百工惟時，庶尹允諧。’言官得其人，人任其事，故官治而不亂，事起而不废，士守其職，大夫理其位，公卿總要執凡而已。故任能者责成而不勞，任己者事废而無功。桓公之於管仲，耳而目之。故君子勞於求賢，逸於用之，豈雲殆哉？昔周公之相也，謙卑而不鄰，以勞天下之士，是以俊乂滿朝，賢智充門。孔子無爵位，以布衣從才士七十有餘人，皆諸侯卿相之人也，况處三公之尊以養天下之士哉？今以公卿之上位，爵祿之美，而不能致士，則未有進賢之道。尧之舉舜也，賓而妻之。桓公舉管仲也，賓而師之。以天子而妻匹夫，可謂親賢矣。以諸侯而師匹夫，可謂敬賓矣。是以賢者從之若流，歸之不疑。今當世在位者，既無燕昭之下士，《鹿鳴》之樂賢，而行臧文、子椒之意，蔽賢妒能，自高其智，訾人之才，足己而不問，卑士而不友，以位尚賢，以祿驕士，而求士之用，亦難矣！”","sortOrder":23},
  {"id":"s_work_dtl_2_24","chapterId":"ch_work_dtl_2","text":"大夫缪然不言，蓋賢良長叹息焉。","sortOrder":24},
  {"id":"s_work_dtl_2_25","chapterId":"ch_work_dtl_2","text":"御史進曰：“太公相文、武以王天下，管仲相桓公以霸諸侯。故賢者得位，猶龍得水，騰蛇遊霧也。公孫丞相以《春秋》說先帝，遽即三公，處周、邵之列，據萬里之势，為天下准繩，衣不重彩，食不兼味，以先天下，而無益於治。博士褚泰、徐偃等，承明詔，建節馳傳，巡省郡國，舉孝、廉，勸元元，而流俗不改。招舉賢良、方正、文學之士，超遷官爵，或至卿大夫，非燕昭之荐士，文王之廣賢也？然而未睹功業所成。殆非龍蛇之才，而《鹿鳴》之所樂賢也。”","sortOrder":25},
  {"id":"s_work_dtl_2_26","chapterId":"ch_work_dtl_2","text":"文學曰：“冰炭不同器，日月不併明。當公孫弘之時，人主方設謀垂意於四夷，故權譎之謀進，荆、楚之士用，將帥或至封侯食邑，而克獲者鹹蒙厚賞，是以奋击之士由此興。其後，幹戈不休，軍旅相望，甲士糜弊，縣官用不足，故設险興利之臣起，磻溪熊羆之士隱。涇、渭造渠以通漕運，東郭鹹陽、孔仅建鹽、鐵，策諸利，富者買爵販官，免刑除罪，公用弥多而為者徇私，上下兼求，百姓不堪，抏弊而從法，故忄朁急之臣進，而見知、废格之法起。杜周、鹹宣之屬，以峻文决理貴，而王溫舒之徒以鷹隼击殺顯。其欲據仁義以道事君者寡，偷合取容者眾。獨以一公孫弘，如之何？”","sortOrder":26},
  {"id":"s_work_dtl_2_27","chapterId":"ch_work_dtl_2","text":"◎論儒第十一","sortOrder":27},
  {"id":"s_work_dtl_2_28","chapterId":"ch_work_dtl_2","text":"御史曰：“文學祖述仲尼，稱誦其德，以為自古及今，未之有也。然孔子修道魯、衛之間，教化洙、泗之上，弟子不為变，當世不為治，魯國之削滋甚。齊宣王褒儒尊學，孟軻、淳於髡之徒，受上大夫之祿，不任職而論國事，蓋齊稷下先生千有餘人。當此之時，非一公孫弘也。弱燕攻齊，長驅至臨淄，湣王遁逃，死於莒而不能救；王建禽於秦，與之俱虜而不能存。若此，儒者之安國尊君，未始有效也。”","sortOrder":28},
  {"id":"s_work_dtl_2_29","chapterId":"ch_work_dtl_2","text":"文學曰：“無鞭策，雖造父不能調驷馬。無势位，雖舜、禹不能治萬民。孔子曰：“鳳鳥不至，河不出圖，吾已矣夫！”故轺車良馬，無以馳之；聖德仁義，無所施之。齊威、宣之時，顯賢進士，國家富強，威行敵國。及湣王，奋二世之餘烈，南舉楚、淮，北併巨宋，苞十二國，西摧三晉，却強秦，五國賓從，邹、魯之君，泗上諸侯皆入臣。矜功不休，百姓不堪。諸儒諫不從，各分散，慎到、捷子亡去，田骈如薛，而孫卿適楚。內無良臣，故諸侯合謀而伐之。王建聽流說，信反間，用後勝之計，不與諸侯從親，以亡國。為秦所禽，不亦宜乎？”","sortOrder":29},
  {"id":"s_work_dtl_2_30","chapterId":"ch_work_dtl_2","text":"御史曰：“伊尹以割烹事湯，百里以飯牛要穆公，始為苟合，信然與之霸王。如此，何言不從？何道不行？故商君以王道說孝公，不用，即以強國之道，卒以就功。邹子以儒術幹世主，不用，即以变化始終之論，卒以顯名。故馬效千里，不必胡、代；士貴成功，不必文辭。孟軻守舊術，不知世務，故困於梁宋。孔子能方不能圓，故飢於黎丘。今晚世之儒勤德，時有乏匮，言以為非，困此不行。自周室以來，千有餘歲，獨有文，武、成、康，如言必參一焉，取所不能及而稱之，猶躄者能言遠不能行也。聖人異途同歸，或行或止，其趣一也。商君雖革法改教，志存於強國利民。邹子之作，变化之術，亦歸於仁義。祭仲自貶損以行權，時也。故小枉大直，君子為之。今硁硁然守一道，引尾生之意，即晉文之譎諸侯以尊周室不足道，而管仲蒙恥辱以存亡不足稱也。”","sortOrder":30},
  {"id":"s_work_dtl_2_31","chapterId":"ch_work_dtl_2","text":"文學曰：“伊尹之幹湯，知聖主也。百里之歸秦，知明君也。二君之能知霸主，其册素形於己，非暗而以冥冥决事也。孔子曰：‘名不正則言不順，言不順則事不成。’如何其苟合而以成霸王也？君子執德秉義而行，故造次必於是，顛沛必於是。孟子曰：‘居今之朝，不易其俗，而成千乘之势，不能一朝居也。’寧窮飢居於陋巷安能变己而從俗化？阖庐殺僚，公子札去而之延陵，終身不入吳國。魯公殺子赤，叔眄退而隱處，不食其祿。虧義得尊，枉道取容，效死不為也。聞正道不行，釋事而退，未聞枉道以求容也。”","sortOrder":31},
  {"id":"s_work_dtl_2_32","chapterId":"ch_work_dtl_2","text":"御史曰：“《論語》：‘親於其身為不善者，君子不入也。’有是言而行不足從也。季氏為無道，逐其君，奪其政，而冉求、仲由臣焉。《禮》：‘男女不授受，不交爵。’孔子適衛，因嬖臣弥子瑕以見衛夫人，子路不說。子瑕，佞臣也，夫子因之，非正也。男女不交，孔子見南子，非禮也。禮義由孔氏，且貶道以求容，惡在其釋事而退也？”","sortOrder":32},
  {"id":"s_work_dtl_2_33","chapterId":"ch_work_dtl_2","text":"文學曰：“天下不平，庶國不寧，明王之忧也。上無天子，下無方伯，天下煩亂，賢聖之忧也。是以尧忧洪水，伊尹忧民，管仲束縛，孔子周流，忧百姓之禍而欲安其危也。是以負鼎俎、囚拘、匍匐以救之。故追亡者趨，拯溺者濡。今民陷溝壑，雖欲無濡，豈得已哉？”","sortOrder":33},
  {"id":"s_work_dtl_2_34","chapterId":"ch_work_dtl_2","text":"御史默不對。","sortOrder":34},
  {"id":"s_work_dtl_2_35","chapterId":"ch_work_dtl_2","text":"◎忧邊第十二","sortOrder":35},
  {"id":"s_work_dtl_2_36","chapterId":"ch_work_dtl_2","text":"大夫曰：“文學言：‘天下不平，庶國不寧，明王之忧也。’故王者之於天下，猶一室之中也，有一人不得其所，則謂之不樂。故民流溺而弗救，非惠君也。國家有難而不忧，非忠臣也。夫守節死難者，人臣之職也；衣食飢寒者，慈父之道也。今子弟遠勞於外，人主為之夙夜不寧，群臣盡力畢議，册滋國用。故少府丞令請建酒榷，以贍邊，給戰士，拯民於難也。為人父兄者，豈可以已乎！內省衣食以恤在外者，猶未足，今又欲罢諸用，减奉邊之費，未可為慈父賢兄也。”","sortOrder":36},
  {"id":"s_work_dtl_2_37","chapterId":"ch_work_dtl_2","text":"文學曰：“周之季末，天子微弱，諸侯力政，故國君不安，謀臣奔馳。何者？敵國眾而社稷危也。今九州同域，天下一統，陛下優遊巖廊，覽群臣極言至論，內詠《雅》、《頌》，外鳴和鑾，純德粲然，併於唐、虞，功烈流於子孫。夫蠻、貊之人，不食之地，何足以煩慮，而有戰國之忧哉？若陛下不弃，加之以德，施之以惠，北夷必內向，款塞自至，然後以為胡製於外臣，即匈奴没齒不食其所用矣。”","sortOrder":37},
  {"id":"s_work_dtl_2_38","chapterId":"ch_work_dtl_2","text":"大夫曰：“聖主思中國之未寧，北邊之未安，使故廷尉評等問人間所疾苦。拯恤貧賤，周贍不足。群臣所宣明王之德，安宇內者，未得其紀，故問諸生。諸生議不幹天則入淵，乃欲以闾里之治，而况國家之大事，亦不幾矣！發於畎畝，出於窮巷，不知冰水之寒，若醉而新寤，殊不足與言也。”","sortOrder":38},
  {"id":"s_work_dtl_2_39","chapterId":"ch_work_dtl_2","text":"文學曰：“夫欲安民富國之道，在於反本，本立而道生。順天之理，因地之利，即不勞而功成。夫不修其源而事其流，無本以統之，雖竭精神，盡思慮，無益於治。欲安之適足以危之，欲救之適足以败之。夫治亂之端，在於本末而已，不至勞其心而道可得也。孔子曰：‘不通於論者難於言治，道不同者，不相與謀。’今公卿意有所倚，故文學之言，不可用也。”","sortOrder":39},
  {"id":"s_work_dtl_2_40","chapterId":"ch_work_dtl_2","text":"大夫曰：“吾聞為人臣者盡忠以順職，為人子者致孝以承業。君有非，則臣覆蓋之。父有非，則子匿逃之。故君薨，臣不变君之政，父没，則子不改父之道也。《春秋》譏毀泉台，為其隳先祖之所為，而扬君父之惡也。今鹽、鐵、均输，所從來久矣，而欲罢之，得無害先帝之功，而妨聖主之德乎？有司倚於忠孝之路，是道殊而不同於文學之謀也。”","sortOrder":40},
  {"id":"s_work_dtl_2_41","chapterId":"ch_work_dtl_2","text":"文學曰：“明者因時而变，知者隨世而製。孔子曰：‘麻冕，禮也，今也純，俭，吾從眾。’故聖人上賢不離古，順俗而不偏宜。魯定公序昭穆，順祖祢，昭公废卿士，以省事節用，不可謂变祖之所為，而改父之道也？二世充大阿房以崇緒，趙高增累秦法以廣威，而未可謂忠臣孝子也。”","sortOrder":41},
  {"id":"s_work_dtl_2_42","chapterId":"ch_work_dtl_2","text":"《鹽鐵論》　西漢桓宽","sortOrder":42},
  {"id":"s_work_dtl_3_1","chapterId":"ch_work_dtl_3","text":"卷三","sortOrder":1},
  {"id":"s_work_dtl_3_2","chapterId":"ch_work_dtl_3","text":"◎園池第十三","sortOrder":2},
  {"id":"s_work_dtl_3_3","chapterId":"ch_work_dtl_3","text":"大夫曰：“諸侯以國為家，其忧在內。天子以八極為境，其慮在外。故宇小者用菲，功巨者用大。是以縣官开園池，總山海，致利以助貢賦，修溝渠，立諸農，廣田牧，盛苑囿。太仆、水衡、少府、大農，歲課諸入田牧之利，池篽之假，及北邊置任田官，以贍諸用，而猶未足。今欲罢之，絕其源，杜其流，上下俱殫，困乏之應也，雖好省事節用，如之何其可也？”","sortOrder":3},
  {"id":"s_work_dtl_3_4","chapterId":"ch_work_dtl_3","text":"文學曰：“古者，製地足以養民，民足以承其上。千乘之國，百里之地，公侯伯子男，各充其求贍其欲。秦兼萬國之地，有四海之富，而意不贍，非宇小而用菲，嗜欲多而下不堪其求也。語曰：‘厨有腐肉，國有飢民，廄有肥馬，路有餧人。’今狗馬之養，虫獸之食，豈特腐肉肥馬之費哉！無用之官，不急之作，服淫侈之变，無功而衣食縣官者眾，是以上不足而下困乏也。今不减除其本而欲贍其末，設機利，造田畜，與百姓爭荐草，與商贾爭市利，非所以明主德而相國家也。夫男耕女績，天下之大業也。故古者分地而處之，製田畝而事之。是以業無不食之地，國無乏作之民。今縣官之多張苑囿、公田、池泽，公家有鄣假之名，而利歸權家。三辅迫近於山、河，地狹人眾，四方併凑，粟米薪菜，不能相贍。公田轉假，桑榆菜果不殖，地力不盡。愚以為非。先帝之开苑囿、池篽，可賦歸之於民，縣官租稅而已。假稅殊名，其實一也。夫如是，匹夫之力，盡於南畝，匹婦之力，盡於麻枲。田野辟，麻枲治，則上下俱衍，何困乏之有矣？”","sortOrder":4},
  {"id":"s_work_dtl_3_5","chapterId":"ch_work_dtl_3","text":"大夫默然，视其丞相、御史。","sortOrder":5},
  {"id":"s_work_dtl_3_6","chapterId":"ch_work_dtl_3","text":"◎輕重第十四","sortOrder":6},
  {"id":"s_work_dtl_3_7","chapterId":"ch_work_dtl_3","text":"御史進曰：“昔太公封於營丘，辟草萊而居焉。地薄人少，於是通利末之道，極女工之巧。是以鄰國交於齊，财畜货殖，世為強國。管仲相桓公，袭先君之業，行輕重之变，南服強楚而霸諸侯。今大夫君修太公、桓、管之術，總一鹽、鐵，通山川之利而萬物殖。是以縣官用饒足，民不困乏，本末併利，上下俱足，此筹計之所致，非獨耕桑農也。”","sortOrder":7},
  {"id":"s_work_dtl_3_8","chapterId":"ch_work_dtl_3","text":"文學曰：“禮義者，國之基也，而權利者，政之殘也。孔子曰：‘能以禮讓為國乎？何有。’伊尹、太公以百里興其君，管仲专於桓公，以千乘之齊，而不能至於王，其所務非也。故功名隳坏而道不濟。當此之時，諸侯莫能以德，而爭於公利，故以權相傾。今天下合為一家，利末惡欲行？淫巧惡欲施？大夫君以心計策國用，構諸侯，參以酒榷，鹹陽、孔仅增以鹽、鐵，江充、楊可之等，各以鋒銳，言利末之事析秋毫，可為無間矣。非特管仲設九府，徼山海也。然而國家衰耗，城郭空虛。故非特崇仁義無以化民，非力本農無以富邦也。”","sortOrder":8},
  {"id":"s_work_dtl_3_9","chapterId":"ch_work_dtl_3","text":"御史曰：“水有猵獭而池魚勞，國有強御而齊民消。故茂林之下無丰草，大塊之間無美苗。夫理國之道，除秽鋤豪，然後百姓均平，各安其宇。張廷尉論定律令，明法以繩天下，誅奸猾，絕併兼之徒，而強不凌弱，眾不暴寡。大夫君運筹策，建國用，籠天下鹽、鐵諸利，以排富商大贾，買官贖罪，損有餘，補不足，以齊黎民。是以兵革東西征伐，賦斂不增而用足。夫損益之事，賢者所睹，非眾人之所知也。”","sortOrder":9},
  {"id":"s_work_dtl_3_10","chapterId":"ch_work_dtl_3","text":"文學曰：“扁鵲撫息脈而知疾所由生，陽氣盛，則損之而調陰，寒氣盛，則損之而調陽，是以氣脈調和，而邪氣無所留矣。夫拙医不知脈理之腠，血氣之分，妄刺而無益於疾，傷肌膚而已矣。今欲損有餘，補不足，富者愈富，貧者愈貧矣。嚴法任刑，欲以禁暴止奸，而奸猶不止，意者非扁鵲之用針石，故眾人未得其職也。”","sortOrder":10},
  {"id":"s_work_dtl_3_11","chapterId":"ch_work_dtl_3","text":"御史曰：“周之建國也，蓋千八百諸侯。其後，強吞弱，大兼小，併為六國。六國連兵結難數百年，內拒敵國，外攘四夷。由此觀之：兵甲不休，戰伐不乏，軍旅外奉，仓库內實。今以天下之富，海內之财，百郡之貢，非特齊、楚之畜，趙、魏之库也。計委量入，雖急用之，宜無乏絕之時。顧大農等以術體躬稼，則後稷之烈，軍四出而用不繼，非天之财少也？用針石，調陰陽，均有無，補不足，亦非也？上大夫君與治粟都尉管領大農事，灸刺稽滯，开利百脈，是以萬物流通，而縣官富實。當此之時，四方征暴亂，車甲之費，克獲之賞，以亿萬計，皆贍大司農。此者扁鵲之力，而鹽、鐵之福也。”","sortOrder":11},
  {"id":"s_work_dtl_3_12","chapterId":"ch_work_dtl_3","text":"文學曰：“邊郡山居穀處，陰陽不和，寒冻裂地，冲風飄滷，沙石凝積，地势無所宜。中國，天地之中，陰陽之际也，日月經其南，斗極出其北，含眾和之氣，產育庶物。今去而侵邊，多斥不毛寒苦之地，是猶弃江皋河濱，而田於嶺阪菹泽也。轉仓廪之委，飛府库之财，以給邊民。中國困於繇賦，邊民苦於戍御。力耕不便种籴，無桑麻之利，仰中國絲絮而後衣之，皮裘蒙毛，曾不足蓋形，夏不失复，冬不離窟，父子夫婦內藏於专室土圜之中。中外空虛，扁鵲何力？而鹽、鐵何福也？”","sortOrder":12},
  {"id":"s_work_dtl_3_13","chapterId":"ch_work_dtl_3","text":"◎未通第十五","sortOrder":13},
  {"id":"s_work_dtl_3_14","chapterId":"ch_work_dtl_3","text":"御史曰：“內郡人眾，水泉荐草，不能相贍，地势溫濕，不宜牛馬；民蹠耒而耕，負簷而行，勞罢而寡功。是以百姓貧苦，而衣食不足，老弱負辂於路，而列卿大夫，或乘牛車。孝武皇帝平百越以為園圃，却羌、胡以為苑囿，是以珍怪異物，充於後宮，騊駼駃騠，實於外廄，匹夫莫不乘堅良，而民間厭橘柚。由此觀之：邊郡之利亦饒矣！而曰‘何福之有？’未通於計也。”","sortOrder":14},
  {"id":"s_work_dtl_3_15","chapterId":"ch_work_dtl_3","text":"文學曰：“禹平水土，定九州，四方各以土地所生貢獻，足以充宮室，供人主之欲，膏壤萬里，山川之利，足以富百姓，不待蠻、貊之地，遠方之物而用足。聞往者未伐胡、越之時，繇賦省而民富足，溫衣飽食，藏新食陳，布帛充用，牛馬成群。農夫以馬耕載，而民莫不騎乘；當此之時，却走馬以粪。其後，師旅數發，戎馬不足，牸牝入陣，故駒犢生於戰地。六畜不育於家，五穀不殖於野，民不足於糟糠，何橘柚之所厭？《傳》曰：‘大軍之後，累世不复。’方今郡國，田野有隴而不墾，城郭有宇而不實，邊郡何饒之有乎？”","sortOrder":15},
  {"id":"s_work_dtl_3_16","chapterId":"ch_work_dtl_3","text":"御史曰：“古者，製田百步為畝，民井田而耕，什而籍一。義先公而後己，民臣之職也。先帝哀怜百姓之愁苦，衣食不足，製田二百四十步而一畝，率三十而稅一。墮民不務田作，飢寒及己，固其理也。其不耕而欲播，不种而欲獲，鹽、鐵又何過乎？”","sortOrder":16},
  {"id":"s_work_dtl_3_17","chapterId":"ch_work_dtl_3","text":"文學曰：“什一而籍，民之力也。丰耗美惡，與民共之。民勤，己不獨衍；民衍，己不獨勤。故曰：‘什一者，天下之中正也。’田雖三十，而以頃畝出稅，樂歲粒米狼戾而寡取之，凶年飢饉而必求足。加之以口賦更繇之役，率一人之作，中分其功。農夫悉其所得，或假貸而益之。是以百姓疾耕力作，而飢寒遂及己也。筑城者先厚其基而後求其高，畜民者先厚其業而後求其贍。《論語》曰：‘百姓足，君孰與不足乎？’”","sortOrder":17},
  {"id":"s_work_dtl_3_18","chapterId":"ch_work_dtl_3","text":"御史曰：“古者，諸侯爭強，戰國併起，甲兵不休，民曠於田畴，什一而籍，不违其職。今賴陛下神靈，甲兵不動久矣，然則民不齊出於南畝，以口率被墾田而不足，空仓廪而赈貧乏，侵益日甚，是以愈惰而仰利縣官也。為斯君者亦病矣，反以身勞民；民猶背恩弃義而遠流亡，避匿上公之事。民相仿效田地日芜，租賦不入，抵扞縣官。君雖欲足，誰與之足乎？”","sortOrder":18},
  {"id":"s_work_dtl_3_19","chapterId":"ch_work_dtl_3","text":"文學曰：“树木數徙則萎，虫獸徙居則坏。故‘代馬依北風，飛鳥翔故巢’，莫不哀其生。由此觀之，民非利避上公之事而樂流亡也。往者，軍陣數起，用度不足，以訾征賦，常取給見民，田家又被其勞，故不齊出於南畝也。大抵逋流，皆在大家，吏正畏憚，不敢篤责，刻急細民，細民不堪，流亡遠去；中家為之絕出，後亡者為先亡者服事；錄民數創於惡吏，故相仿效，去尤甚而就少愈者多。《傳》曰：“政宽者民死之，政急者父子離。’是以田地日荒，城郭空虛。夫牧民之道，除其所疾，適其所安，安而不扰，使而不勞，是以百姓勸業而樂公賦。若此，則君無赈於民，民無利於上，上下相讓而頌聲作。故取而民不厭，役而民不苦。《靈台》之詩，非或使之，民自為之。若斯，則君何不足之有乎？”","sortOrder":19},
  {"id":"s_work_dtl_3_20","chapterId":"ch_work_dtl_3","text":"御史曰：“古者，十五入大學，與小役；二十冠而成人，與戎；五十以上，血脈溢刚，曰艾壮。《詩》曰：‘方叔元老，克壮其猷。’故商師若乌，周師若荼。今陛下哀怜百姓，宽力役之政，二十三始傅，五十六而免，所以辅耆壮而息老艾也。丁者治其田里，老者修其唐園，俭力趣時，無飢寒之患。不治其家而訟縣官，亦悖矣。”","sortOrder":20},
  {"id":"s_work_dtl_3_21","chapterId":"ch_work_dtl_3","text":"文學曰：“十九年已下為殇，未成人也；二十而冠；三十而娶，可以從戎事；五十已上曰艾老，杖於家，不從力役，所以扶不足而息高年也；乡飲酒之禮，耆老異饌，所以優耆耄而明養老也。故老者非肉不飽，非帛不暖，非杖不行。今五十已上至六十，與子孫服挽输，併給繇役，非養老之意也。古有大丧者，君三年不呼其門，通其孝道，遂其哀戚之心也。君子之所重而自盡者，其惟親之丧乎！今或僵尸，弃衰绖而從戎事，非所以子百姓，順孝悌之心也。周公抱成王聽天下，恩塞海內，泽被四表，矧惟人面，含仁保德，靡不得其所。《詩》雲：‘夙夜基命宥密。’陛下富於春秋，委任大臣，公卿辅政，政教未均，故庶人議也。”","sortOrder":21},
  {"id":"s_work_dtl_3_22","chapterId":"ch_work_dtl_3","text":"御史默不答也。","sortOrder":22},
  {"id":"s_work_dtl_3_23","chapterId":"ch_work_dtl_3","text":"《鹽鐵論》　西漢桓宽","sortOrder":23},
  {"id":"s_work_dtl_4_1","chapterId":"ch_work_dtl_4","text":"卷四","sortOrder":1},
  {"id":"s_work_dtl_4_2","chapterId":"ch_work_dtl_4","text":"◎地廣第十六","sortOrder":2},
  {"id":"s_work_dtl_4_3","chapterId":"ch_work_dtl_4","text":"大夫曰：“王者包含併覆，普愛無私，不為近重施，不為遠遺恩。今俱是民也，俱是臣也，安危勞佚不齊，獨不當調邪？不念彼而獨計此，斯亦好議矣？緣邊之民，處寒苦之地，距強胡之難，烽燧一動，有没身之累。故邊民百戰，而中國恬臥者，以邊郡為蔽扞也。《詩》雲：‘莫非王事，而我獨勞。’刺不均也。是以聖王懷四方獨苦，興師推却胡、越，遠寇安灾，散中國肥饒之餘，以調邊境，邊境強，則中國安，中國安則晏然無事。何求而不默也？”","sortOrder":3},
  {"id":"s_work_dtl_4_4","chapterId":"ch_work_dtl_4","text":"文學曰：“古者，天子之立於天下之中，縣內方不過千里，諸侯列國，不及不食之地，《禹貢》至於五千里；民各供其君，諸侯各保其國，是以百姓均調，而繇役不勞也。今推胡、越數千里，道路回避，士卒勞罢。故邊民有刎頸之禍，而中國有死亡之患，此百姓所以嚣嚣而不默也。夫治國之道，由中及外，自近者始。近者親附，然後來遠；百姓內足，然後恤外。故群臣論或欲田輪台，明主不許，以為先救近務及時本業也。故下詔曰：‘當今之務，在於禁苛暴，止擅賦，力本農。’公卿宜承意，請减除不任，以佐百姓之急。今中國弊落不忧，務在邊境。意者地廣而不耕，多种而不耨，費力而無功，《詩》雲：‘無田甫田，維莠驕驕。’其斯之謂欤。”","sortOrder":4},
  {"id":"s_work_dtl_4_5","chapterId":"ch_work_dtl_4","text":"大夫曰：“湯、武之伐，非好用兵也；周宣王辟國千里，非貪侵也；所以除寇賊而安百姓也。故無功之師，君子不行；無用之地，聖王不貪。先帝舉湯、武之師，定三垂之難，一面而製敵，匈奴遁逃，因河、山以為防，故去砂石鹹滷不食之地，故割斗辟之縣，弃造陽之地以與胡，省曲塞，據河险，守要害，以宽徭役，保士民。由此觀之：聖主用心，非務廣地以勞眾而已矣。”","sortOrder":5},
  {"id":"s_work_dtl_4_6","chapterId":"ch_work_dtl_4","text":"文學曰：“秦之用兵，可謂極矣，蒙恬斥境，可謂遠矣。今逾蒙恬之塞，立郡縣寇虜之地，地弥遠而民滋勞。朔方以西，長安以北，新郡之功，外城之費，不可勝計。非徒是也，司馬、唐蒙凿西南夷之途，巴、蜀弊於邛、筰；橫海征南夷，樓船戍東越，荆、楚罢於甌、骆，左將伐朝鮮，开臨屯，燕、齊困於秽貉，張騫通殊遠，納無用，府库之藏，流於外國；非特斗辟之費，造陽之役也。由此觀之：非人主用心，好事之臣為縣官計過也。”","sortOrder":6},
  {"id":"s_work_dtl_4_7","chapterId":"ch_work_dtl_4","text":"大夫曰：“挟管仲之智者，非為厮役之使也。懷陶朱之慮者，不居貧困之處。文學能言而不能行，居下而訕上，處貧而非富，大言而不從，高厲而行卑，誹譽訾議，以要名采善於當世。夫祿不過秉握者，不足以言治，家不滿簷石者，不足以計事。儒皆貧羸，衣冠不完，安知國家之政，縣官之事乎？何斗辟造陽也！”","sortOrder":7},
  {"id":"s_work_dtl_4_8","chapterId":"ch_work_dtl_4","text":"文學曰：“夫賤不害智，貧不妨行。顏淵屢空，不為不賢。孔子不容，不為不聖。必將以貌舉人，以才進士，則太公終身鼓刀，寧戚不離飯牛矣。古之君子，守道以立名，修身以俟時，不為窮变節，不為賤易志，惟仁之處，惟義之行。臨财苟得，見利反義，不義而富，無名而貴，仁者不為也。故曾參、闵子不以其仁易晉、楚之富。伯夷不以其行易諸侯之位，是以齊景公有馬千驷，而不能與之爭名。孔子曰：‘賢哉回也！一箪食，一瓢飲，在於陋巷，人不堪其忧，回也不改其樂。’故惟仁者能處約、樂，小人富斯暴，貧斯濫矣。楊子曰：‘為仁不富，為富不仁。’苟先利而後義，取奪不厭。公卿積亿萬，大夫積千金，士積百金，利己併财以聚；百姓寒苦，流離於路，儒獨何以完其衣冠也？”","sortOrder":8},
  {"id":"s_work_dtl_4_9","chapterId":"ch_work_dtl_4","text":"◎貧富第十七","sortOrder":9},
  {"id":"s_work_dtl_4_10","chapterId":"ch_work_dtl_4","text":"大夫曰：“餘結發束修年十三，幸得宿衛，給事輦轂之下，以至卿大夫之位，獲祿受賜，六十有餘年矣。車馬衣服之用，妻子仆養之費，量入為出，俭節以居之，奉祿賞賜，一二筹策之，積浸以致富成業。故分土若一，賢者能守之；分财若一，智者能筹之。夫白圭之废著，子貢之三至千金，豈必賴之民哉？運之六寸，轉之息耗，取之貴賤之間耳！”","sortOrder":10},
  {"id":"s_work_dtl_4_11","chapterId":"ch_work_dtl_4","text":"文學曰：“古者，事業不二，利祿不兼，然諸業不相遠，而貧富不相懸也。夫乘爵祿以謙讓者，名不可勝舉也；因權势以求利者，入不可勝數也。食湖池，管山海，刍荛者不能與之爭泽，商贾不能與之爭利。子貢以布衣致之，而孔子非之，况以势位求之者乎？故古者大夫思其仁義以充其位，不為權利以充其私也。”","sortOrder":11},
  {"id":"s_work_dtl_4_12","chapterId":"ch_work_dtl_4","text":"大夫曰：“山嶽有饒，然後百姓贍焉。河、海有润，然後民取足焉。夫尋常之污，不能溉陂泽，丘阜之木，不能成宮室。小不能苞大，少不能贍多。未有不能自足而能足人者也。未有不能自治而能治人者也。故善為人者，能自為者也，善治人者，能自治者也。文學不能治內，安能理外乎？”","sortOrder":12},
  {"id":"s_work_dtl_4_13","chapterId":"ch_work_dtl_4","text":"文學曰：“行遠道者假於車，濟江、海者因於舟。故賢士之立功成名，因於資而假物者也。公输子能因人主之材木，以構宮室台榭，而不能自為专屋狹庐，材不足也。欧冶能因國君之銅鐵，以為金爐大鐘，而不能自為壶鼎盤杅，無其用也。君子能因人主之正朝，以和百姓，润眾庶，而不能自饒其家，势不便也。故舜耕歷山，恩不及州里，太公屠牛於朝歌，利不及妻子，及其見用，恩流八荒，德溢四海。故舜假之尧，太公因之周，君子能修身以假道者，不能枉道而假财也。”","sortOrder":13},
  {"id":"s_work_dtl_4_14","chapterId":"ch_work_dtl_4","text":"大夫曰：“道懸於天，物布於地，智者以衍，愚者以困。子貢以著積顯於諸侯、陶朱公以货殖尊於當世。富者交焉，貧者贍焉。故上自人君，下及布衣之士，莫不戴其德，稱其仁。原憲、孔伋，當世被飢寒之患，顏回屢空於窮巷，當此之時，迫於窟穴，拘於缊袍，雖欲假财信奸佞，亦不能也。”","sortOrder":14},
  {"id":"s_work_dtl_4_15","chapterId":"ch_work_dtl_4","text":"文學曰：“孔子雲：‘富而可求，雖執鞭之事，吾亦為之；如不可求，從吾所好。’君子求義，非苟富也。故刺子貢不受命而货殖焉。君子遭時則富且貴，不遇，退而樂道。不以利累己，故不违義而妄取。隱居修節，不欲妨行，故不毀名而趨势。雖付之以韓、魏之家，非其志，則不居也。富貴不能榮，謗毀不能傷也。故原憲之缊袍，賢於季孫之狐貉，趙宣孟之魚飧，甘於智伯之刍豢，子思之銀佩，美於虞公之垂棘。魏文侯軾段幹木之闾，非以其有势也；晉文公見韓慶，下車而趨，非以其多财，以其富於仁，充於德也。故貴何必财，亦仁義而已矣！”","sortOrder":15},
  {"id":"s_work_dtl_4_16","chapterId":"ch_work_dtl_4","text":"◎毀學第十八","sortOrder":16},
  {"id":"s_work_dtl_4_17","chapterId":"ch_work_dtl_4","text":"大夫曰：“夫懷枉而言正，自托於無欲而實不從，此非士之情也？昔李斯與包丘子俱事荀卿，既而李斯入秦，遂取三公，據萬乘之權以製海內，切侔伊、望，名巨泰山；而包丘子不免於瓮牖蒿庐，如潦歲之蛙，口非不眾也，卒死於溝壑而已。今內無以養，外無以稱，貧賤而好義，雖言仁義，亦不足貴者也！”","sortOrder":17},
  {"id":"s_work_dtl_4_18","chapterId":"ch_work_dtl_4","text":"文學曰：“方李斯之相秦也，始皇任之，人臣無二，然而荀卿謂之不食，睹其罹不测之禍也。包丘子飯麻蓬藜，修道白屋之下，樂其志，安之於廣厦刍豢，無赫赫之势，亦無戚戚之忧。夫晉獻垂棘，非不美也，宮之奇見之而叹，知荀息之圖之也。智伯富有三晉，非不盛也，然不知襄子之謀之也。季孫之狐貉，非不麗也，而不知魯君之患之也。故晉獻以寶馬釣虞、虢，襄子以城坏誘智伯。故智伯身禽於趙，而虞、虢卒併於晉，以其務得不顧其後，貪土地而利寶馬也。孔子曰：‘人無遠慮，必有近忧。’今之在位者，見利不虞害，貪得不顧恥，以利易身，以财易死。無仁義之德，而有富貴之祿，若蹈坎阱，食於懸門之下，此李斯之所以伏五刑也。南方有鳥名鵷雏，非竹實不食，非醴泉不飲，飛過泰山，泰山之鴟，俯啄腐鼠，仰見鵷雏而吓。今公卿以其富貴笑儒者，為之常行，得無若泰山鴟吓鵷雏乎？”","sortOrder":18},
  {"id":"s_work_dtl_4_19","chapterId":"ch_work_dtl_4","text":"大夫曰：“學者所以防固辭，禮者所以文鄙行也。故學以辅德，禮以文质。言思可道，行思可樂。惡言不出於口，邪行不及於己。動作應禮，從容中道。故禮以行之，孫以出之。是以終日言，無口過；終身行，無冤尤。今人主張官立朝以治民，疏爵分祿以褒賢，而曰‘懸門腐鼠’，何辭之鄙背而悖於所聞也？”","sortOrder":19},
  {"id":"s_work_dtl_4_20","chapterId":"ch_work_dtl_4","text":"文學曰：“聖主設官以授任，能者處之；分祿以任賢，能者受之。義貴無高，義取無多。故舜受尧之天下，太公不避周之三公；苟非其人，箪食豆羹猶為賴民也。故德薄而位高，力少而任重，鮮不及矣。夫泰山鴟啄腐鼠於窮泽幽穀之中，非有害於人也。今之有司，盜主财而食之於刑法之旁，不知機之是發，又以吓人，其患惡得若泰山之鴟乎？”","sortOrder":20},
  {"id":"s_work_dtl_4_21","chapterId":"ch_work_dtl_4","text":"大夫曰：“司馬子言：‘天下穰穰，皆為利往。’趙女不擇丑好，鄭嫗不擇遠近，商人不愧恥辱，戎士不愛死力，士不在親，事君不避其難，皆為利祿也。儒、墨內貪外矜，往來遊說，栖栖然亦未為得也。故尊榮者士之願也，富貴者士之期也。方李斯在荀卿之門，阘茸與之齊軫，及其奋翼高舉，龍升骥骛，過九軼二，翱翔萬仞，鸿鵠華骝且同侣，况跛牂燕雀之屬乎！席天下之權，御宇內之眾，後車百乘，食祿萬鐘。而拘儒布褐不完，糟糠不飽，非甘菽藿而卑廣厦，亦不能得已。雖欲吓人，其何已乎！”","sortOrder":21},
  {"id":"s_work_dtl_4_22","chapterId":"ch_work_dtl_4","text":"文學曰：“君子懷德，小人懷土。賢士徇名，貪夫死利。李斯貪其所欲，致其所惡。孫叔敖早見於未萌，三去相而不悔，非樂卑賤而惡重祿也，慮患遠而避害謹也。夫郊祭之牛，養食期年，衣之文繡，以入廟堂，太宰執其鸞刀，以啟其毛；方此之時，願任重而上峻阪，不可得也。商鞅困於彭池，吳起之伏王尸，願被布褐而處窮鄙之蒿庐，不可得也。李斯相秦，席天下之势，志小萬乘；及其囚於囹圄，車裂於雲陽之市，亦願負薪入東門，行上蔡曲街径，不可得也。蘇秦、吳起以權势自殺，商鞅、李斯以尊重自滅，皆貪祿慕榮以没其身，從車百乘，曾不足以載其禍也！”","sortOrder":22},
  {"id":"s_work_dtl_4_23","chapterId":"ch_work_dtl_4","text":"◎褒賢第十九","sortOrder":23},
  {"id":"s_work_dtl_4_24","chapterId":"ch_work_dtl_4","text":"大夫曰：“伯夷以廉飢，尾生以信死。由小器而虧大體，匹夫匹婦之為谅也，經於溝渎而莫之知也。何功名之有？蘇秦、張儀，智足以強國，勇足以威敵，一怒而諸侯懼，安居而天下息。萬乘之主，莫不屈體卑辭，重幣請交，此所謂天下名士也。夫智不足與謀，而權不能舉當世，民斯為下也。今舉亡而為有，虛而為盈，布衣穿履，深念徐行，若有遺亡，非立功名之士，而亦未免於世俗也。”","sortOrder":24},
  {"id":"s_work_dtl_4_25","chapterId":"ch_work_dtl_4","text":"文學曰：“蘇秦以從顯於趙，張儀以橫任於秦，方此之時，非不尊貴也，然智士隨而忧之，知夫不以道進者必不以道退，不以義得者必不以義亡。季、孟之權，三桓之富，不可及也，孔子為之曰‘微’。為人臣，權均於君，富侔於國者，亡。故其位弥高而罪弥重，祿滋厚而罪滋多。夫行者先全己而後求名，仕者先辟害而後求祿。故香餌非不美也，龟龍聞而深藏，鸞鳳見而高逝者，知其害身也。夫為乌鵲魚鱉，食香餌而後狂飛奔走，遜頭屈遰，無益於死。今有司盜秉國法，進不顧罪，卒然有急，然後車馳入趨，無益於死。所盜不足偿於臧獲，妻子奔亡無處所，身在深牢，莫知恤视。方此之時，何暇得以笑乎？”","sortOrder":25},
  {"id":"s_work_dtl_4_26","chapterId":"ch_work_dtl_4","text":"大夫曰：“文學高行，矯然若不可卷；盛節絜言，皦然若不可涅。然戍卒陳勝釋挽辂，首為叛逆，自立張楚，素非有回、由處士之行，宰相列臣之位也。奋於大泽，不過旬月，而齊、魯儒墨縉紳之徒，肆其長衣，─長衣，容衣也。─負孔氏之禮器《詩》、《書》，委质為臣。孔甲為涉博士，卒俱死陳，為天下大笑。深藏高逝者固若是也？”","sortOrder":26},
  {"id":"s_work_dtl_4_27","chapterId":"ch_work_dtl_4","text":"文學曰：“周室衰，禮樂坏，不能統理，天下諸侯交爭，相滅亡，併為六國，兵革不休，民不得寧息。秦以虎狼之心，蠶食諸侯，併吞戰國以為郡縣，伐能矜功，自以為過尧、舜而羞與之同。弃仁義而尚刑罰，以為今時不師於文而决於武。趙高治獄於內，蒙恬用兵於外，百姓愁苦，同心而患秦。陳王赫然奋爪牙為天下首事，道雖凶而儒墨或幹之者，以為無王之矣，道擁遏不得行，自孔子以至於茲，而秦复重禁之，故發憤於陳王也。孔子曰：‘如有用我者，吾其為東周乎！’庶幾成湯、文、武之功，為百姓除殘去賊，豈貪祿樂位哉？”","sortOrder":27},
  {"id":"s_work_dtl_4_28","chapterId":"ch_work_dtl_4","text":"大夫曰：“文學言行雖有伯夷之廉，不及柳下惠之貞，不過高瞻下视，絜言污行，觴酒豆肉，遷延相讓，辭小取大，雞廉狼吞。趙綰、王臧之等，以儒術擢為上卿，而有奸利殘忍之心。主父偃以口舌取大官，竊權重，欺绐宗室，受諸侯之賂，卒皆誅死。東方朔自稱辯略，消堅釋石，當世無双；然省其私行，狂夫不忍為，况無東方朔之口，其餘無可觀者也？”","sortOrder":28},
  {"id":"s_work_dtl_4_29","chapterId":"ch_work_dtl_4","text":"文學曰：“志善者忘惡，謹小者致大。俎豆之間足以觀禮，閨門之內足以論行。夫服古之服，誦古之道，舍此而為非者，鮮矣。故君子時然後言，義然後取，不以道得之不居也。滿而不溢，泰而不驕。故袁盎親於景帝，秣馬不過一驷；公孫弘即三公之位，家不過十乘；東方先生說聽言行於武帝，而不驕溢；主父見困厄之日久矣，疾在位者不好道而富且貴，莫知恤士也，於是取饒衍之餘以周窮士之急，非為私家之業也。當世嚣嚣，非患儒之雞廉，患在位者之虎飽鴟咽，於求覽無所孑遺耳。”","sortOrder":29},
  {"id":"s_work_dtl_4_30","chapterId":"ch_work_dtl_4","text":"《鹽鐵論》　西漢桓宽","sortOrder":30},
  {"id":"s_work_dtl_5_1","chapterId":"ch_work_dtl_5","text":"卷五","sortOrder":1},
  {"id":"s_work_dtl_5_2","chapterId":"ch_work_dtl_5","text":"◎相刺第二十","sortOrder":2},
  {"id":"s_work_dtl_5_3","chapterId":"ch_work_dtl_5","text":"大夫曰：“古者，經井田，製廛里，丈夫治其田畴，女子治其麻枲，無曠地，無遊人。故非商工不得食於利末，非良農不得食於收獲，非執政不得食於官爵。今儒者釋耒耜而學不验之語，曠日弥久，而無益於治，往來浮遊，不耕而食，不蠶而衣，巧伪良民，以奪農妨政，此亦當世之所患也。”","sortOrder":3},
  {"id":"s_work_dtl_5_4","chapterId":"ch_work_dtl_5","text":"文學曰：“禹戚洪水，身親其勞，泽行路宿，過門不入。當此之時，簪墮不掇，冠掛不顧，而暇耕乎？孔子曰：‘詩人疾之不能默，丘疾之不能伏。’是以東西南北七十說而不用，然後退而修王道，作《春秋》，垂之萬載之後，天下折中焉，豈與匹夫匹婦耕織同哉！《傳》曰：‘君子當時不動，而民無觀也。’故非君子莫治小人，非小人無以養君子，不當耕織為匹夫匹婦也。君子耕而不學，則亂之道也。”","sortOrder":4},
  {"id":"s_work_dtl_5_5","chapterId":"ch_work_dtl_5","text":"大夫曰：“文學言治尚於唐、虞，言義高於秋天，有華言矣，未見其實也。昔魯穆公之時，公儀為相，子思、子柳為之卿，然北削於齊，以泗為境，南畏楚人，西賓秦國。孟軻居梁，兵折於齊，上將軍死，而太子虜，西败於秦，地奪壤削，亡河內、河外。夫仲尼之門，七十子之徒，去父母，捐室家，負荷而隨孔子，不耕而學，亂乃愈滋。故玉屑滿箧，不為有寶；詩書負笈，不為有道。要在安國家，利人民，不苟繁文眾辭而已。”","sortOrder":5},
  {"id":"s_work_dtl_5_6","chapterId":"ch_work_dtl_5","text":"文學曰：“虞不用百里奚之謀而滅，秦穆用之以至霸焉。夫不用賢則亡，而不削何可得乎？孟子適梁，惠王問利，答以仁義。趣舍不合，是以不用而去，懷寶而無語。故有粟不食，無益於飢；睹賢不用，無益於削。紂之時，內有微、箕二子，外有膠鬲、棘子，故其不能存。夫言而不用，諫而不聽，雖賢，惡得有益於治也？”","sortOrder":6},
  {"id":"s_work_dtl_5_7","chapterId":"ch_work_dtl_5","text":"大夫曰：“橘柚生於江南，而民皆甘之於口，味同也；好音生於鄭、衛，而人皆樂之於耳，聲同也。越人子臧、戎人由餘，待譯而後通，而併顯齊、秦，人之心於善惡同也。故曾子倚山而吟，山鳥下翔；師曠鼓琴，百獸率舞。未有善而不合，誠而不應者也。意未誠與？何故言而不見從，行而不合也？”","sortOrder":7},
  {"id":"s_work_dtl_5_8","chapterId":"ch_work_dtl_5","text":"文學曰：“扁鵲不能治不受針藥之疾，賢聖不能正不食諫諍之君。故桀有關龍逄而夏亡，紂有三仁而商滅，故不患無由餘、子臧之論，患無桓、穆之聽耳。是以孔子東西無所遇，屈原放逐於楚國也。故曰：‘直道而事人，焉往而不三黜？枉道而事人，何必去父母之邦。’此所以言而不見從，行而不得合者也。”","sortOrder":8},
  {"id":"s_work_dtl_5_9","chapterId":"ch_work_dtl_5","text":"大夫曰：“歌者不期於利聲，而貴在中節；論者不期於麗辭，而務在事實。善聲而不知轉，未可為能歌也；善言而不知变，未可謂能說也。持規而非矩，執准而非繩，通一孔，晓一理，而不知權衡，以所不睹不信人，若蝉之不知雪，堅據古文以應當世，猶辰參之错，膠柱而調瑟，固而難合矣。孔子所以不用於世，而孟軻見賤於諸侯也。”","sortOrder":9},
  {"id":"s_work_dtl_5_10","chapterId":"ch_work_dtl_5","text":"文學曰：“日月之光，而盲者不能見，雷電之聲，而聋人不能聞。夫為不知音者言，若語於喑聋，何特蝉之不知重雪耶？夫以伊尹之智，太公之賢，而不能开辭於桀、紂，非說者非，聽者過也。是以荆和抱璞而泣血，曰：‘安得良工而剖之！’屈原行吟泽畔，曰：‘安得皋陶而察之！’夫人君莫不欲求賢以自辅，任能以治國，然牵於流說，惑於道諛，是以賢聖蔽掩，而讒佞用事，以此亡國破家，而賢士飢於巖穴也。昔趙高無過人之志，而居萬人之位，是以傾覆秦國而禍殃其宗，盡失其瑟，何膠柱之調也？”","sortOrder":10},
  {"id":"s_work_dtl_5_11","chapterId":"ch_work_dtl_5","text":"大夫曰：“所謂文學高第者，智略能明先王之術，而姿质足以履行其道。故居則為人師，用則為世法。今文學言治則稱尧、舜，道行則言孔、墨，授之政則不達，懷古道而不能行，言直而行枉，道是而情非，衣冠有以殊於乡曲，而實無以異於凡人。諸生所謂中直者，遭時蒙幸，備數適然耳，殆非明舉所謂，固未可與論治也。”","sortOrder":11},
  {"id":"s_work_dtl_5_12","chapterId":"ch_work_dtl_5","text":"文學曰：“天設三光以照記，天子立公卿以明治。故曰：公卿者，四海之表儀，神化之丹青也。上有辅明主之任，下有遂聖化之事，和陰陽，調四時，安眾庶，育群生，使百姓辑睦，無怨思之色，四夷順德，無叛逆之忧，此公卿之職，而賢者之所務也。若伊尹、周、召三公之才，太顛、閎夭九卿之人。文學不中聖主之明舉，今之執政，亦未能稱盛德也。”","sortOrder":12},
  {"id":"s_work_dtl_5_13","chapterId":"ch_work_dtl_5","text":"大夫不說，作色不應也。","sortOrder":13},
  {"id":"s_work_dtl_5_14","chapterId":"ch_work_dtl_5","text":"文學曰：“朝無忠臣者政闇，大夫無直士者位危。任座正言君之過，文侯改言行，稱為賢君。袁盎面刺絳侯之驕矜，卒得其慶。故觸死亡以幹主之過者，忠臣也，犯顏以匡公卿之失者，直士也。鄙人不能巷言面违。方今入穀之教令，張而不施，食祿多非其人，以妨農商工，市井之利，未歸於民，民望不塞也。且夫帝王之道，多墮坏而不修，《詩》雲：‘濟濟多士。’意者誠任用其計，非苟陳虛言而已。”","sortOrder":14},
  {"id":"s_work_dtl_5_15","chapterId":"ch_work_dtl_5","text":"◎殊路第二十一","sortOrder":15},
  {"id":"s_work_dtl_5_16","chapterId":"ch_work_dtl_5","text":"大夫曰：“七十子躬受聖人之術，有名列於孔子之門，皆諸侯卿相之才，可南面者數人雲。政事者冉有、季路，言語宰我、子貢。宰我秉事，有寵於齊，田常作難，道不行，身死庭中，簡公殺於檀台。子路仕衛，孔悝作亂，不能救君出亡，身菹於衛；子貢、子皋遁逃，不能死其難。食人之重祿不能更，處人尊官不能存，何其厚於己而薄於君哉？同門共業，自以為知古今之義，明君臣之禮。或死或亡，二三子殊路，何道之悖也！”","sortOrder":16},
  {"id":"s_work_dtl_5_17","chapterId":"ch_work_dtl_5","text":"文學曰：“宋殇公知孔父之賢而不早任，故身死。魯莊知季有之賢，授之政晚而國亂。衛君近佞遠賢，子路居蒲，孔悝為政。簡公不聽宰我而漏其謀。是以二君身被放殺，而禍及忠臣。二子者有事而不與其謀，故可以死，可以生，去止其義一也。晏婴不死崔、慶之難，不可謂不義；微子去殷之亂，可謂不仁乎？”","sortOrder":17},
  {"id":"s_work_dtl_5_18","chapterId":"ch_work_dtl_5","text":"大夫曰：“至美素璞，物莫能飾也。至賢保真，伪文莫能增也。故金玉不琢，美珠不畫。今仲由、冉求無檀柘之材，隋、和之璞，而強文之，譬若雕朽木而砺鉛刀，飾嫫母畫土人也。被以五色，斐然成章，及遭行潦流波，則沮矣。夫重懷古道，枕籍《詩》、《書》，危不能安，亂不能治，郵里逐雞，雞亦無党也？”","sortOrder":18},
  {"id":"s_work_dtl_5_19","chapterId":"ch_work_dtl_5","text":"文學曰：“非學無以治身，非禮無以辅德。和氏之璞，天下之美寶也、待礛諸之工而後明。毛嫱，天下之姣人也，待香泽脂粉而後容。周公，天下之至聖人也，待賢師學問而後通。今齊世庸士之人，不好學問，专以己之愚而荷負臣任，若無橶舳，濟江海而遭大風，漂没於百仞之淵，東流無崖之川，安得沮而止乎？”","sortOrder":19},
  {"id":"s_work_dtl_5_20","chapterId":"ch_work_dtl_5","text":"大夫曰：“性有刚柔，形有好惡，聖人能因而不能改。孔子外变二三子之服，而不能革其心。故子路解長劍，去危冠，屈節於夫子之門，然攝齊師友，行行爾，鄙心猶存。宰予晝寢，欲損三年之丧。孔子曰：‘粪土之牆，不可杇也’，‘若由不得其死然。’故內無其质而外學其文，雖有賢師良友，若畫脂鏤冰，費日損功。故良師不能飾戚施，香泽不能化嫫母也。”","sortOrder":20},
  {"id":"s_work_dtl_5_21","chapterId":"ch_work_dtl_5","text":"文學曰：“西子蒙以不絜，鄙夫掩鼻；惡人盛飾，可以宗祀上帝。使二人不涉聖人之門，不免為窮夫，安得卿大夫之名？故砥所以致於刃，學所以盡其才也。孔子曰：‘觚不觚，觚哉，觚哉！’故人事加則為宗廟器，否則斯養之爨材。幹、越之鋌不厲，匹夫賤之；工人施巧，人主服而朝也。夫丑者自以為姣，故飾；愚者自以為知，故不學。觀笑在己而不自知，不好用人，自是之過也。”","sortOrder":21},
  {"id":"s_work_dtl_5_22","chapterId":"ch_work_dtl_5","text":"◎訟賢第二十二","sortOrder":22},
  {"id":"s_work_dtl_5_23","chapterId":"ch_work_dtl_5","text":"大夫曰：“刚者折，柔者卷。故季由以強梁死，宰我以柔弱殺。使二子不學，未必不得其死。何者？矜己而伐能，小知而巨牧，欲人之從己，不能以己從人，莫视而自見，莫贾而自貴，此其所以身殺死而終菹醢也。未見其為宗廟器，睹其為世戮也。當此之時，東流亦安之乎？”","sortOrder":23},
  {"id":"s_work_dtl_5_24","chapterId":"ch_work_dtl_5","text":"文學曰：“騏骥之挽鹽車垂頭於太行之阪，屠者持刀而睨之。太公之窮困，負販於朝歌也，蓬頭相聚而笑之。當此之時，非無遠筋駿才也，非文王、伯樂莫知之贾也。子路、宰我生不逢伯樂之舉，而遇狂屠，故君子傷之，若“由不得其死然”，‘天其祝予’矣。孔父累華督之難，不可謂不義。仇牧涉宋萬之禍，不可謂不賢也。”","sortOrder":24},
  {"id":"s_work_dtl_5_25","chapterId":"ch_work_dtl_5","text":"大夫曰：“今之學者，無太公之能，騏骥之才，有以蜂蠆介毒而自害也。東海成顒，河東胡建是也。二子者以術蒙舉，起卒伍，為縣令。獨非自是，無與合同。引之不來，推之不往，狂狷不遜，忮害不恭，刻轹公主，侵陵大臣。知其不可而強行之，欲以幹名。所由不軌，果没其身。未睹功業所至而見東觀之殃，身得重罪，不得以寿終。狡而以為知，訐而以為直，不遜以為勇，其遭難，故亦宜也。”","sortOrder":25},
  {"id":"s_work_dtl_5_26","chapterId":"ch_work_dtl_5","text":"文學曰：“二公懷精白之心，行忠正之道，直己以事上，竭力以徇公，奉法推理，不避強御，不阿所親，不貴妻子之養，不顧私家之業。然卒不能免於嫉妒之人，為眾枉所排也。其所以累不测之刑而功不遂也。夫公族不正則法令不行，肱肱不正則奸邪興起。趙奢行之平原，范雎行之穰侯，二國治而兩家全。故君過而臣正，上非而下譏，大臣正，縣令何有？不反諸己而行非於人，執政之大失也。夫屈原之沉淵，遭子椒之谮也；管子得行其道，鮑叔之力也。今不睹鮑叔之力，而見汨羅之禍，雖欲以寿終，無其能得乎？”","sortOrder":26},
  {"id":"s_work_dtl_5_27","chapterId":"ch_work_dtl_5","text":"◎遵道第二十三","sortOrder":27},
  {"id":"s_work_dtl_5_28","chapterId":"ch_work_dtl_5","text":"大夫曰：“御史！”","sortOrder":28},
  {"id":"s_work_dtl_5_29","chapterId":"ch_work_dtl_5","text":"御史未應。","sortOrder":29},
  {"id":"s_work_dtl_5_30","chapterId":"ch_work_dtl_5","text":"謂丞相史曰：“文學結發學語，服膺不舍，辭若循環，轉若陶鈞。文繁如春華，無效如抱風。飾虛言以亂實，道古以害今。從之，則縣官用废，虛言不可實而行之；不從，文學以為非也，眾口嚣嚣，不可勝聽。諸卿都大府日久矣，通先古，明當世，今將何從而可矣？”","sortOrder":30},
  {"id":"s_work_dtl_5_31","chapterId":"ch_work_dtl_5","text":"丞相史進曰：“晉文公譎而不正，齊桓公正而不譎，所由不同，俱歸於霸。而必隨古不革，袭故不改，是文质不变，而椎車尚在也。故或作之，或述之，然後法令調於民，而器械便於用也。孔對三君殊意，晏子相三君異道，非苟相反，所務之時異也。公卿既定大業之路，建不竭之本，願無顧細故之語，牵儒、墨論也。”","sortOrder":31},
  {"id":"s_work_dtl_5_32","chapterId":"ch_work_dtl_5","text":"文學曰：“師曠之調五音，不失宮商。聖王之治世，不離仁義。故有改製之名，無变道之實。上自黃帝，下及三王，莫不明德教，謹庠序，崇仁義，立教化。此百世不易之道也。殷、周因循而昌，秦王变法而亡。《詩》雲：‘雖無老成人，尚有典刑。’言法教也。故没而存之，舉而貫之，貫而行之，何更為哉？”","sortOrder":32},
  {"id":"s_work_dtl_5_33","chapterId":"ch_work_dtl_5","text":"丞相史曰：“說西施之美無益於容，道尧、舜之德無益於治。今文學不言所為治，而言以治之無功，猶不言耕田之方，美富人之囷仓也。夫欲粟者務時，欲治者因世。故商君昭然獨見存亡不可與世俗同者，為其沮功而多近也。庸人安其故，而愚者果所聞。故舟車之治，使民三年而後安之。商君之法立，然後民信之。孔子曰：‘可與共學，未可與權。’文學可令扶繩循刻，非所與論道術之外也。”","sortOrder":33},
  {"id":"s_work_dtl_5_34","chapterId":"ch_work_dtl_5","text":"文學曰：“君子多聞闕疑，述而不作，聖達而謀大，叡智而事寡。是以功成而不隳，名立而不頓。小人智淺而謀大，羸弱而任重，故中道而废，蘇秦、商鞅是也。無先王之法，非聖人之道，而因於己，故亡。《易》曰：‘小人處盛位，雖高必崩。不盈其道，不恒其德，而能以善終身，未之有也。是以初登於天，後入於地。’禹之治水也，民知其利，莫不勸其功。商鞅之立法，民知其害，莫不畏其刑。故夏後功立而王，商鞅法行而亡。商鞅有獨智之慮，世乏獨見之證。文學不足與權當世，亦無負累蒙殃也。”","sortOrder":34},
  {"id":"s_work_dtl_5_35","chapterId":"ch_work_dtl_5","text":"◎論誹第二十四","sortOrder":35},
  {"id":"s_work_dtl_5_36","chapterId":"ch_work_dtl_5","text":"丞相史曰：“晏子有言：‘儒者華於言而寡於實，繁於樂而舒於民，久丧以害生，厚葬以傷業，禮煩而難行，道迂而難遵，稱往古而訾當世，賤所見而貴所聞。’此人本枉，以己為式。此顏異所以誅黜，而狄山死於匈奴也。處其位而非其朝，生乎世而訕其上，終以被戮而丧其軀，此獨誰為負其累而蒙其殃乎？”","sortOrder":36},
  {"id":"s_work_dtl_5_37","chapterId":"ch_work_dtl_5","text":"文學曰：“禮所以防淫，樂所以移風，禮興樂正則刑罰中。故堤防成而民無水菑，禮義立而民無亂患。故禮義坏，堤防决，所以治者，未之有也。孔子曰：‘禮與其奢也寧俭，丧與其易也寧戚。’故禮之所為作，非以害生傷業也，威儀節文，非以亂化傷俗也。治國謹其禮，危國謹其法。昔秦以武力吞天下，而斯、高以妖孽累其禍，废古術，隳舊禮，专任刑法，而儒、墨既丧焉。塞士之途，壅人之口，道諛日進而上不聞其過，此秦所以失天下而殒社稷也。故聖人為政，必先誅之，伪巧言以辅非而傾覆國家也。今子安取亡國之語而來乎？夫公卿處其位，不正其道，而以意阿邑順風，疾小人淺淺面從，以成人之過也。故知言之死，不忍從苟合之徒，是以不免於螺绁。悲夫！”","sortOrder":37},
  {"id":"s_work_dtl_5_38","chapterId":"ch_work_dtl_5","text":"丞相史曰：“檀柘而有乡，萑苇而有藂，言物類之相從也。孔子曰：‘德不孤，必有鄰。’故湯興而伊尹至，不仁者遠矣。未有明君在上而亂臣在下也。今先帝躬行仁聖之道，以臨海內，招舉俊才賢良之士，唯仁是用，誅逐亂臣，不避所親，務以求賢而簡退不肖，猶尧之舉舜、禹之族，殛鯀放驩兜也。而曰‘苟合之徒’，是則主非而臣阿，是也？”","sortOrder":38},
  {"id":"s_work_dtl_5_39","chapterId":"ch_work_dtl_5","text":"文學曰：“皋陶對舜：‘在知人，惟帝其難之。’洪水之灾，尧獨愁悴而不能治，得舜、禹而九州寧。故雖有尧明之君，而無舜、禹之佐，則純德不流。《春秋》刺有君而無主。先帝之時，良臣未備，故邪臣得間。尧得舜、禹而鯀殛驩兜誅，趙簡子得叔向而盛青肩诎。語曰：‘未見君子，不知伪臣。’《詩》雲：‘未見君子，忧心忡忡。既見君子，我心則降。’此之謂也。”","sortOrder":39},
  {"id":"s_work_dtl_5_40","chapterId":"ch_work_dtl_5","text":"丞相史曰：“尧任鯀、驩兜，得舜、禹而放殛之以其罪，而天下鹹服，誅不仁也。人君用之齊民，而顏異，濟南亭長也，先帝舉而加之高位，官至上卿。狄山起布衣，為漢議臣，處舜、禹之位，執天下之中，不能以治，而反坐訕上；故驩兜之誅加而刑戮至焉。賢者受賞而不肖者被刑，固其然也。文學又何怪焉？”","sortOrder":40},
  {"id":"s_work_dtl_5_41","chapterId":"ch_work_dtl_5","text":"文學曰：“論者相扶以義，相喻以道，從善不求勝，服義不恥窮。若相迷以伪，相亂以辭，相矜於後息，期於苟勝，非其貴者也。夫蘇秦、張儀，熒惑諸侯，傾覆萬乘，使人失其所恃；非不辯，然亂之道也。君子疾鄙夫之不可與事君，患其聽從而無所不至也。今子不聽正義以辅卿相，又從而順之，好須臾之說，不計其後。若子之為人吏，宜受上戮，子姑默矣！”","sortOrder":41},
  {"id":"s_work_dtl_5_42","chapterId":"ch_work_dtl_5","text":"丞相史曰：“蓋聞士之居世也，衣服足以勝身，食飲足以供親，內足以相恤，外不求於人。故身修然後可以理家，家理然後可以治官。故飯蔬糲者不可以言孝，妻子飢寒者不可以言慈，緒業不修者不可以言理。居斯世，行斯身，而有此三累者，斯亦足以默矣。”","sortOrder":42},
  {"id":"s_work_dtl_5_43","chapterId":"ch_work_dtl_5","text":"◎孝養第二十五","sortOrder":43},
  {"id":"s_work_dtl_5_44","chapterId":"ch_work_dtl_5","text":"文學曰：“善養者不必刍豢也，善供服者不必錦繡也。以己之所有盡事其親，孝之至也。故匹夫勤勞，猶足以順禮，歠菽飲水，足以致其敬。孔子曰：‘今之孝者，是為能養，不敬，何以別乎？’故上孝養志，其次養色，其次養體。貴其禮，不貪其養，禮順心和，養雖不備，可也。《易》曰：‘東鄰殺牛，不如西鄰之禴祭也。’故富貴而無禮，不如貧賤之孝悌。閨門之內盡孝焉，閨門之外盡悌焉，朋友之道盡信焉，三者，孝之至也。居家理者，非謂積财也，事親孝者，非謂鮮肴也，亦和顏色、承意盡禮義而已矣。”","sortOrder":44},
  {"id":"s_work_dtl_5_45","chapterId":"ch_work_dtl_5","text":"丞相史曰：“八十曰耋，七十曰耄。耄，食非肉不飽，衣非帛不暖。故孝子曰甘毳以養口，輕暖以養體。曾子養曾皙，必有酒肉。無端絻，雖公西赤不能以為容。無肴膳，雖闵、曾不能以卒養。禮無虛加，故必有其實然後為之文。與其禮有餘而養不足，寧養有餘而禮不足。夫洗爵以盛水，升降而進糲，禮雖備，然非其貴者也。”","sortOrder":45},
  {"id":"s_work_dtl_5_46","chapterId":"ch_work_dtl_5","text":"文學曰：“周襄王之母非無酒肉也，衣食非不如曾皙也，然而被不孝之名，以其不能事其父母也。君子重其禮，小人貪其養。夫嗟來而招之，投而與之，乞者由不取也。君子苟無其禮，雖美不食焉。故禮主人不親饋，則客不祭。是饋輕而禮重也。”","sortOrder":46},
  {"id":"s_work_dtl_5_47","chapterId":"ch_work_dtl_5","text":"丞相史曰：“孝莫大以天下一國養，次祿養，下以力。故王公人君，上也，卿大夫，次也。夫以家人言之，有賢子當路於世者，高堂邃宇，安車大馬，衣輕暖，食甘毳。無者，褐衣皮冠，窮居陋巷，有旦無暮，食蔬糲葷茹，膢腊而後見肉。老親之腹非唐園，唯菜是盛。夫蔬糲，乞者所不取，而子以養親，雖欲以禮，非其貴也。”","sortOrder":47},
  {"id":"s_work_dtl_5_48","chapterId":"ch_work_dtl_5","text":"文學曰：“無其能而竊其位，無其功而有其祿，雖有富貴，由跖、蹻之養也。高台極望，食案方丈，而不可謂孝。老親之腹非盜囊也，何故常盛不道之物？夫取非有非職，财入而患從之，身且死禍殃，安得膢腊而食肉？曾參、闵子無卿相之養，而有孝子之名；周襄王富有天下，而有不能事父母之累。故禮菲而養丰，非孝也。掠囷而以養，非孝也。”","sortOrder":48},
  {"id":"s_work_dtl_5_49","chapterId":"ch_work_dtl_5","text":"丞相史曰：“上孝養色，其次安親，其次全身。往者，陳餘背漢，斬於泜水；五被邪逆，而夷三族。近世，主父偃行不軌而誅滅，呂步舒弄口而見戮，行身不謹，誅及無罪之親。由此觀之：虛禮無益於己也。文實配行，禮養俱施，然後可以言孝。孝在實质，不在於飾貌；全身在於謹慎，不在於馳語也。”","sortOrder":49},
  {"id":"s_work_dtl_5_50","chapterId":"ch_work_dtl_5","text":"文學曰：“言而不誠，期而不信，臨難不勇，事君不忠，不孝之大者也。孟子曰：‘今之世，今之大夫，皆罪人也。皆逢其意以順其惡。’今子不忠不信，巧言以亂政，导諛以求合。若此者，不容於世。《春秋》曰：‘士守一不移，循理不外援，共其職而已。’故卑位而言高者，罪也，言不及而言者，傲也。有詔公卿與斯議，而空戰口也？”","sortOrder":50},
  {"id":"s_work_dtl_5_51","chapterId":"ch_work_dtl_5","text":"◎刺議第二十六","sortOrder":51},
  {"id":"s_work_dtl_5_52","chapterId":"ch_work_dtl_5","text":"丞相史曰：“山陵不讓椒跬，以成其崇；君子不辭負薪之言，以廣其名。故多見者博，多聞者知，距諫者塞，专己者孤。故謀及下者無失策，舉及眾者無頓功。《詩》雲：‘詢於刍荛。’故布衣皆得風議，何况公卿之史乎？《春秋》士不載文，而書咺者，以為宰士也。孔子曰：‘雖不吾以，吾其與聞諸。’仆雖不敏，亦嘗傾耳下風，攝齊句指，受業径於君子之途矣。使文學言之而是，仆之言有何害？使文學言之而非，雖微丞相史，孰不非也？”","sortOrder":52},
  {"id":"s_work_dtl_5_53","chapterId":"ch_work_dtl_5","text":"文學曰：“以正辅人謂之忠，以邪导人謂之佞。夫怫過納善者，君之忠臣，大夫之直士也。孔子曰：‘大夫有爭臣三人，雖無道，不失其家。’今子處宰士之列，無忠正之心，枉不能正，邪不能匡，順流以容身，從風以說上。上所言則苟聽，上所行則曲從，若影之隨形，响之於聲，終無所是非。衣儒衣，冠儒冠，而不能行其道，非其儒也。譬若土龍，文章首目具而非龍也。葶歷似菜而味殊，玉石相似而異類。子非孔氏執經守道之儒，乃公卿面從之儒，非吾徒也。冉有為季氏宰而附益之，孔子曰：‘小子鳴鼓而攻之，可也。故辅桀者不為智，為桀斂者不為仁。”","sortOrder":53},
  {"id":"s_work_dtl_5_54","chapterId":"ch_work_dtl_5","text":"丞相史默然不對。","sortOrder":54},
  {"id":"s_work_dtl_5_55","chapterId":"ch_work_dtl_5","text":"◎利議第二十七","sortOrder":55},
  {"id":"s_work_dtl_5_56","chapterId":"ch_work_dtl_5","text":"大夫曰：“作世明主，忧勞萬民，思念北邊之未安，故使使者舉賢良、文學高第，詳延有道之士，將欲觀殊議異策，虛心傾耳以聽，庶幾雲得。諸生無能出奇計遠圖，伐匈奴安邊境之策，抱枯竹，守空言，不知趨舍之宜，時世之变，議論無所依，如膝痒而搔背，辯訟公門之下，訩訩不可勝聽，如品即口以成事，此豈明主所欲聞哉？”","sortOrder":56},
  {"id":"s_work_dtl_5_57","chapterId":"ch_work_dtl_5","text":"文學曰：“諸生對册，殊路同歸，指在崇禮義，退财利，复往古之道，匡當世之失，莫不雲太平；雖未盡可亶用，宜若有可行者焉。執事闇於明禮，而喻於利末，沮事隋議，計慮筹策，以故至今未决。非儒無成事，公卿欲成利也。”","sortOrder":57},
  {"id":"s_work_dtl_5_58","chapterId":"ch_work_dtl_5","text":"大夫曰：“色厲而內荏，亂真者也。文表而枲里，亂實者也。文學裒衣博帶，竊周公之服；鞠躬踧踖，竊仲尼之容；議論稱誦，竊商、賜之辭；刺譏言治，竊管、晏之才。心卑卿相，志小萬乘。及授之政，昏亂不治。故以言舉人，若以毛相馬。此其所以多不稱舉。詔策曰：‘朕嘉宇內之士，故詳延四方豪俊文學博習之士，超遷官祿。’言者不必有德，何者？言之易而行之難。有舍其車而識其牛，貴其不言而多成事也。吳铎以其舌自破，主父偃以其舌自殺。鶡鴠夜鳴，無益於明；主父鳴鴟，無益於死。非有司欲成利，文學桎梏於舊術，牵於間言者也。”","sortOrder":58},
  {"id":"s_work_dtl_5_59","chapterId":"ch_work_dtl_5","text":"文學曰：“能言之，能行之者，湯、武也。能言，不能行者，有司也。文學竊周公之服，有司竊周公之位。文學桎梏於舊術，有司桎梏於财利。主父偃以舌自殺，有司以利自困。夫骥之才千里，非造父不能使；禹之知萬人，非舜為相不能用。故季桓子聽政，柳下惠忽然不見，孔子為司寇，然後悖炽。骥，舉之在伯樂，其功在造父。造父攝辔，馬無駑良，皆可取道。周公之時，士無賢不肖，皆可與言治。故御之良者善調馬，相之賢者善使士。今舉異才而使臧騶御之，是猶扼骥鹽車而责之使疾。此賢良、文學多不稱舉也。”","sortOrder":59},
  {"id":"s_work_dtl_5_60","chapterId":"ch_work_dtl_5","text":"大夫曰：“嘻！諸生阘茸無行，多言而不用，情貌不相副。若穿逾之盜，自古而患之。是孔丘斥逐於魯君，曾不用於世也。何者？以其首攝多端，迂時而不要也。故秦王燔去其術而不行，坑之渭中而不用。乃安得鼓口舌，申顏眉，預前論議，是非國家之事也？”","sortOrder":60},
  {"id":"s_work_dtl_5_61","chapterId":"ch_work_dtl_5","text":"◎國疾第二十八","sortOrder":61},
  {"id":"s_work_dtl_5_62","chapterId":"ch_work_dtl_5","text":"文學曰：“國有賢士而不用，非士之過，有國者之恥。孔子大聖也，諸侯莫能用，當小位於魯，三月，不令而行，不禁而止，沛若時雨之灌萬物，莫不興起也。况乎位天下之本朝，而施聖主之德音教泽乎？今公卿處尊位，執天下之要，十有餘年，功德不施於天下，而勤勞於百姓，百姓貧陋困窮，而私家累萬金。此君子所恥，而《伐檀》所刺也。昔者，商鞅相秦，後禮讓，先貪鄙，尚首功，務進取，無德厚於民，而嚴刑罰於國，俗日坏而民滋怨，故惠王烹菹其身，以謝天下。當此之時，亦不能論事矣。今執政患儒貧賤而多言，儒亦忧執事富貴而多患也。”","sortOrder":62},
  {"id":"s_work_dtl_5_63","chapterId":"ch_work_dtl_5","text":"大夫视文學，悒悒而不言也。","sortOrder":63},
  {"id":"s_work_dtl_5_64","chapterId":"ch_work_dtl_5","text":"丞相史曰：“夫辯國家之政事，論執政之得失，何不徐徐道理相喻，何至切切如此乎！大夫難罢鹽、鐵者，非有私也，忧國家之用，邊境之費也。諸生訚訚爭鹽、鐵，亦非為己也，欲反之於古而辅成仁義也。二者各有所宗，時世異務，又安可堅任古術而非今之理也。且夫小雅非人，必有以易之。諸生若有能安集國中，懷來遠方，使邊境無寇虜之灾，租稅盡為諸生除之，何况鹽、鐵、均输乎！所以貴術儒者，貴其處謙推讓，以道盡人。今辯訟愕愕然，無赤、賜之辭，而見鄙倍之色，非所聞也。大夫言過，而諸生亦如之，諸生不直謝大夫耳。”","sortOrder":64},
  {"id":"s_work_dtl_5_65","chapterId":"ch_work_dtl_5","text":"賢良、文學皆離席曰：‘鄙人固陋，希涉大庭，狂言多不稱，以逆執事。夫藥酒苦於口而利於病，忠言逆於耳而利於行。故愕愕者福也，諓々者賊也。林中多疾風，富貴多諛言。萬里之朝，日聞唯唯，而後聞諸生之愕愕，此乃公卿之良藥針石。”","sortOrder":65},
  {"id":"s_work_dtl_5_66","chapterId":"ch_work_dtl_5","text":"大夫色少宽，面文學而蘇賢良曰：“窮巷多曲辯，而寡見者難喻。文學守死溟涬之語，而終不移。夫往古之事，昔有之語，已可睹矣。今以近世觀之，自以目有所見，耳有所聞，世殊而事異。文、景之际，建元之始，民朴而歸本，吏廉而自重，殷殷屯々，人衍而家富。今政非改而教非易也，何世之弥薄而俗之滋衰也！吏即少廉，民即寡恥，刑非誅惡，而奸猶不止。世人有言：‘鄙儒不如都士。’文學皆出山東，希涉大論。子大夫論京師之日久，願分明政治得失之事，故所以然者也。”","sortOrder":66},
  {"id":"s_work_dtl_5_67","chapterId":"ch_work_dtl_5","text":"賢良曰：“夫山東天下之腹心，賢士之戰場也。高皇帝龍飛鳳舉於宋、楚之間，山東子弟萧、曹、樊、郦、滕、灌之屬為辅，雖即異世，亦既閎夭、太顛而已。禹出西羌，文王生北夷，然聖德高世，有萬人之才，負迭群之任，出入都市，一旦不知返，數然後終於厮役而已。仆雖不生長京師，才駑下愚，不足與大議，竊以所聞闾里長老之言，往者，常民衣服溫暖而不靡，器质朴牢而致用，衣足以蔽體，器足以便事，馬足以易步，車足以自載，酒足以合歡而不湛，樂足以理心而不淫，入無宴樂之聞，出無佚遊之觀，行即負嬴，止則鋤耘，用約而财饒，本修而民富，送死哀而不華，養生適而不奢，大臣正而無欲，執政宽而不苛；故黎民寧其性，百吏保其官。建元之始，崇文修德，天下乂安。其後，邪臣各以伎藝，虧亂至治，外障山海，內興諸利。楊可告缗，江充禁服，張大夫革令，杜周治獄，罰贖科適，微細併行，不可勝載。夏蘭之屬妄搏，王溫舒之徒妄殺，殘吏萌起，扰亂良民。當此之時，百姓不保其首領，豪富莫必其族姓。聖主覺焉，乃刑戮充等，誅滅殘賊，以殺死罪之怨，塞天下之责，然居民肆然复安。然其禍累世不复，瘡痍至今未息。故百官尚有殘賊之政，而強宰尚有強奪之心。大臣擅權而击斷，豪猾多党而侵陵，富貴奢侈，貧賤篡殺，女工難成而易弊，車器難就而易败，車不累期，器不終歲，一車千石，一衣十鐘。常民文杯畫案，機席緝⻊習，婢妾衣紈履絲，匹庶粺飯肉食，里有俗，党有場，康莊馳逐，窮巷蹋鞠，秉耒抱臿，躬耕身織者寡，聚要斂容、傅白黛青者眾。無而為有，貧而強夸，文表無里，紈袴枲裝，生不養，死厚送，葬死殫家，遣女滿車，富者欲過，貧者欲及，富者空减，貧者稱貸。是以民年急而歲促，貧即寡恥，乏即少廉，此所以刑非誅惡而奸猶不止也。故國有嚴急之征，即生散不足之疾矣。”","sortOrder":67},
  {"id":"s_work_dtl_5_68","chapterId":"ch_work_dtl_5","text":"《鹽鐵論》　西漢桓宽","sortOrder":68},
  {"id":"s_work_dtl_6_1","chapterId":"ch_work_dtl_6","text":"卷六","sortOrder":1},
  {"id":"s_work_dtl_6_2","chapterId":"ch_work_dtl_6","text":"◎散不足第二十九","sortOrder":2},
  {"id":"s_work_dtl_6_3","chapterId":"ch_work_dtl_6","text":"大夫曰：“吾以賢良為少愈，乃反其幽明，若胡車相隨而鳴。諸生獨不見季夏之螇乎？音聲入耳，秋至而聲無。者生無易由言，不顧其患，患至而後默，晚矣。”","sortOrder":3},
  {"id":"s_work_dtl_6_4","chapterId":"ch_work_dtl_6","text":"賢良曰：“孔子讀《史記》，喟然而叹，傷正德之废，君臣之危也。夫賢人君子，以天下為任者也。任大者思遠，思遠者忘近。誠心闵悼，惻隱加爾，故忠心獨而無累。此詩人所以傷而作，比幹、子胥遺身忘禍也。其惡勞人若斯之急，安能默乎？《詩》雲：‘忧心如惔，不敢戲談。’孔子栖栖，疾固也。墨子遑遑，闵世也。”","sortOrder":4},
  {"id":"s_work_dtl_6_5","chapterId":"ch_work_dtl_6","text":"大夫默然。","sortOrder":5},
  {"id":"s_work_dtl_6_6","chapterId":"ch_work_dtl_6","text":"丞相曰：“願聞散不足。”","sortOrder":6},
  {"id":"s_work_dtl_6_7","chapterId":"ch_work_dtl_6","text":"賢良曰：“宮室舆馬，衣服器械，丧祭食飲，聲色玩好，人情之所不能已也。故聖人為之製度以防之。間者，士大夫務於權利，怠於禮義；故百姓仿效，頗逾製度。今故陳之，曰：","sortOrder":7},
  {"id":"s_work_dtl_6_8","chapterId":"ch_work_dtl_6","text":"“古者，穀物菜果，不時不食，鳥獸魚鱉，不中殺不食。故徼罔不入於泽，雜毛不取。今富者逐驅殲罔罝，掩捕麑鷇，耽湎沈酒鋪百川。鮮羔⺶兆，幾胎肩，皮黃口。春鹅秋雏，冬葵溫韭浚，茈蓼蘇，丰薷耳菜，毛果虫貉。","sortOrder":8},
  {"id":"s_work_dtl_6_9","chapterId":"ch_work_dtl_6","text":"“古者，采椽茅茨，陶桴复穴，足御寒暑、蔽風雨而已。及其後世，采椽不斫，茅茨不翦，無斫削之事，磨砻之功。大夫達稜楹，士穎首，庶人斧成木構而已。今富者井幹增梁，雕文槛楯，堊〈巾夔〉壁飾。","sortOrder":9},
  {"id":"s_work_dtl_6_10","chapterId":"ch_work_dtl_6","text":"“古者，衣服不中製，器械不中用，不粥於市。今民間雕琢不中之物，刻畫玩好無用之器。玄黃雜青，五色繡衣，戲弄蒲人雜婦，百獸馬戲斗虎，唐锑追人，奇虫胡妲。","sortOrder":10},
  {"id":"s_work_dtl_6_11","chapterId":"ch_work_dtl_6","text":"“古者，諸侯不秣馬，天子有命，以車就牧。庶人之乘馬者，足以代其勞而已。故行則服桅，止則就犁。今富者連車列騎，驂貳辎軿。中者微舆短轂，繁髦掌蹄。夫一馬伏櫪，當中家六口之食，亡丁男一人之事。","sortOrder":11},
  {"id":"s_work_dtl_6_12","chapterId":"ch_work_dtl_6","text":"“古者，庶人耋老而後衣絲，其餘則麻枲而已，故命曰布衣。及其後，則絲里枲表，直領無袆，袍合不緣。夫羅紈文繡者，人君後妃之服也。茧䌷缣練者，婚姻之嘉飾也。是以文繒薄織，不粥於市。今富者縟繡羅紈，中者素绨冰錦。常民而被後妃之服，亵人而居婚姻之飾。夫紈素之贾倍缣，缣之用倍紈也。","sortOrder":12},
  {"id":"s_work_dtl_6_13","chapterId":"ch_work_dtl_6","text":"“古者，椎車無柔，栈舆無植。及其後，木軨不衣，長轂數幅，蒲荐苙蓋，蓋無漆絲之飾。大夫士則单椱木具，盤韦柔革。常民漆舆大軨蜀輪。今庶人富者銀黃華左搔，結綏韜槓。中者错鑣涂采，珥靳飛軨。","sortOrder":13},
  {"id":"s_work_dtl_6_14","chapterId":"ch_work_dtl_6","text":"“古者，鹿裘皮冒，蹄足不去。及其後，大夫士狐貉縫腋，羔麑豹袪。庶人則毛絝衳彤，羝幞皮衤尃。今富者鼲貂，狐白凫翁。中者罽衣金縷，燕〈鼠各〉代黃。","sortOrder":14},
  {"id":"s_work_dtl_6_15","chapterId":"ch_work_dtl_6","text":"“古者，庶人賤騎繩控，革鞮皮荐而已。及其後，革鞍犛成，鐵鑣不飾。今富者〈革真〉耳銀鑷〈革巤〉，黃金琅勒，罽繡弇汗，華珥明鮮。中者漆韦紹系，采畫暴幹。","sortOrder":15},
  {"id":"s_work_dtl_6_16","chapterId":"ch_work_dtl_6","text":"“古者，污尊抔飲，蓋無爵觴樽俎。及其後，庶人器用即竹柳陶匏而已。唯瑚璉觴豆而後雕文彤漆。今富者銀口黃耳，金罍玉鐘。中者野王纻器，金错蜀杯。夫一文杯得銅杯十，贾賤而用不殊。箕子之譏，始在天子，今在匹夫。","sortOrder":16},
  {"id":"s_work_dtl_6_17","chapterId":"ch_work_dtl_6","text":"“古者，燔黍食稗，而捭豚以相饗。其後，乡人飲酒，老者重豆，少者立食，一醬一肉，旅飲而已。及其後，賓婚相召，則豆羹白飯，綦脍熟肉。今民間酒食，肴殳旅重叠，燔炙滿案，臑鱉脍鯉，麑卵鶉鷃橙枸，鲐鳢醢醯，眾物雜味。","sortOrder":17},
  {"id":"s_work_dtl_6_18","chapterId":"ch_work_dtl_6","text":"“古者，庶人春夏耕耘，秋冬收藏，昏晨力作，夜以繼日。《詩》雲：‘晝爾於茅，宵爾索绹，亟其乘屋，其始播百穀。’非膢腊不休息，非祭祀無酒肉。今賓昏酒食，接連相因，析酲什半，弃事相隨，慮無乏日。","sortOrder":18},
  {"id":"s_work_dtl_6_19","chapterId":"ch_work_dtl_6","text":"“古者，庶人糲食藜藿，非乡飲酒膢腊祭祀無酒肉。故諸侯無故不殺牛羊，大夫士無故不殺犬豕。今闾巷縣佰。阡伯屠沽，無故烹殺，相聚野外。負粟而往，挈肉而歸。夫一豕之肉，得中年之收，十五斗粟，當丁男半月之食。","sortOrder":19},
  {"id":"s_work_dtl_6_20","chapterId":"ch_work_dtl_6","text":"“古者，庶人魚菽之祭，春秋修其祖祠。士一廟，大夫三，以時有事於五祀，蓋無出門之祭。今富者祈名嶽，望山川，椎牛击鼓，戲倡舞像。中者南居當路，水上雲台，屠羊殺狗，鼓瑟吹笙。貧者雞豕五芳，衛保散腊，傾蓋社場。","sortOrder":20},
  {"id":"s_work_dtl_6_21","chapterId":"ch_work_dtl_6","text":"“古者，德行求福，故祭祀而宽。仁義求吉，故卜筮而希。今世俗宽於行而求於鬼，怠於禮而篤於祭，嫚親而貴势，至妄而信日，聽訑言而幸得，出實物而享虛福。","sortOrder":21},
  {"id":"s_work_dtl_6_22","chapterId":"ch_work_dtl_6","text":"“古者，君子夙夜孳孳思其德；小人晨昏孜孜思其力。故君子不素餐，小人不空食。今世俗飾伪行诈，為民巫祝，以取厘謝，堅頟健舌，或以成業致富，故憚事之人，釋本相學。是以街巷有巫，闾里有祝。","sortOrder":22},
  {"id":"s_work_dtl_6_23","chapterId":"ch_work_dtl_6","text":"“古者，無槓樠之寢，床栘之案。及其後世，庶人即采木之槓，牒樺之樠。士不斤成，大夫苇莞而已。今富者黼繡帷幄，涂屏错跗。中者錦绨高張，采畫丹漆。","sortOrder":23},
  {"id":"s_work_dtl_6_24","chapterId":"ch_work_dtl_6","text":"“古者，皮毛草蓐，無茵席之加，旃蒻之美。及其後，大夫士复荐草緣，蒲平单莞。庶人即草蓐索經单蔺蘧蒢而已。今富者繡茵翟柔，蒲子露床。中者滩皮代旃，阘坐平莞。","sortOrder":24},
  {"id":"s_work_dtl_6_25","chapterId":"ch_work_dtl_6","text":"“古者不粥飪，不市食。及其後，則有屠沽，沽酒市脯魚鹽而已。今熟食遍列，殽施成市，作業墮怠，食必趣時，楊豚韭卵，狗〈月習〉馬朘煎魚切肝，羊淹雞寒，挏馬酪酒，蹇捕胃脯，胹羔豆賜，鷇膹雁羹，臭鮑甘瓠，熟梁貊炙。","sortOrder":25},
  {"id":"s_work_dtl_6_26","chapterId":"ch_work_dtl_6","text":"“古者，土鼓塊枹，击木拊石，以盡其歡。及其後，卿大夫有管磬，士有琴瑟。往者，民間酒會，各以党俗，彈筝鼓缶而已。無要妙之音，变羽之轉。今富者鐘鼓五樂，歌兒數曹。中者鳴竽調瑟，鄭舞趙謳。","sortOrder":26},
  {"id":"s_work_dtl_6_27","chapterId":"ch_work_dtl_6","text":"“古者，瓦棺容尸，木板塈周，足以收形骸，藏發齒而已。及其後，桐棺不衣，采椁不斫。今富者繡牆題凑。中者梓棺楩椁，貧者畫荒衣袍，繒囊緹橐。","sortOrder":27},
  {"id":"s_work_dtl_6_28","chapterId":"ch_work_dtl_6","text":"“古者，明器有形無實，示民不可用也。及其後，則有〈酉盆〉醢之藏，桐馬偶人弥祭，其物不備。今厚資多藏，器用如生人。郡國繇吏，素桑楺偶車橹輪，匹夫無貌領，桐人衣紈绨。","sortOrder":28},
  {"id":"s_work_dtl_6_29","chapterId":"ch_work_dtl_6","text":"“古者，不封不树，反虞祭於寢，無壇宇之居，廟堂之位。及其後，則封之，庶人之墳半仞，其高可隱。今富者積土成山，列树成林，台榭連閣，集觀增樓。中者祠堂屏合，垣闕罘罳。","sortOrder":29},
  {"id":"s_work_dtl_6_30","chapterId":"ch_work_dtl_6","text":"“古者，鄰有丧，舂不相杵，巷不歌謠。孔子食於有丧者之侧，未嘗飽也，子於是日哭，則不歌。今俗因人之丧以求酒肉，幸與小坐而责辨，歌舞俳優，連笑伎戲。","sortOrder":30},
  {"id":"s_work_dtl_6_31","chapterId":"ch_work_dtl_6","text":"“古者，男女之际尚矣，嫁娶之服，未之以記。及虞、夏之後，蓋表布內絲，骨笄象珥，封君夫人加錦尚褧而已。今富者皮衣朱貉，繁露環佩。中者長裾交袆，璧瑞簪珥。","sortOrder":31},
  {"id":"s_work_dtl_6_32","chapterId":"ch_work_dtl_6","text":"“古者，事生盡愛，送死盡哀。故聖人為製節，非虛加之。今生不能致其愛敬，死以奢侈相高；雖無哀戚之心，而厚葬重幣者，則稱以為孝，顯名立於世，光榮著於俗。故黎民相慕效，至於發屋賣業。","sortOrder":32},
  {"id":"s_work_dtl_6_33","chapterId":"ch_work_dtl_6","text":"“古者，夫婦之好，一男一女，而成家室之道。及後，士一妾，大夫二，諸侯有侄娣九女而已。今諸侯百數，卿大夫十數，中者侍御，富者盈室。是以女或曠怨失時，男或放死無匹。","sortOrder":33},
  {"id":"s_work_dtl_6_34","chapterId":"ch_work_dtl_6","text":"“古者，凶年不備，丰年補败，仍舊貫而不改作。今工異变而吏殊心，坏败成功，以匿厥意。意極乎功業，務存乎面目。積功以市譽，不恤民之急。田野不辟，而飾亭落，邑居丘墟，而高其郭。","sortOrder":34},
  {"id":"s_work_dtl_6_35","chapterId":"ch_work_dtl_6","text":"“古者，不以人力徇於禽獸，不奪民财以養狗馬，是以财衍而力有餘。今猛獸奇虫不可以耕耘，而令當耕耘者養食之。百姓或短褐不完，而犬馬衣文繡，黎民或糟糠不接，而禽獸食粱肉。","sortOrder":35},
  {"id":"s_work_dtl_6_36","chapterId":"ch_work_dtl_6","text":"“古者，人君敬事愛下，使民以時，天子以天下為家，臣妾各以其時供公職，古今之通義也。今縣官多畜奴婢，坐禀衣食，私作產業，為奸利，力作不盡，縣官失實。百姓或無斗筲之储，官奴累百金；黎民昏晨不釋事，奴婢垂拱遨遊也。","sortOrder":36},
  {"id":"s_work_dtl_6_37","chapterId":"ch_work_dtl_6","text":"“古者，親近而疏遠，貴所同而賤非類。不賞無功，不養無用。今蠻、貊無功，縣官居肆，廣屋大第，坐禀衣食。百姓或旦暮不贍，蠻、夷或厭酒肉。黎民泮汗力作，蠻、夷交胫肆踞。","sortOrder":37},
  {"id":"s_work_dtl_6_38","chapterId":"ch_work_dtl_6","text":"“古者，庶人粗菲草芰，縮絲尚韦而已。及其後，則綦下不借，挽鞮革舄。今富者革中名工，輕靡使容，紈里紃下，越端縱緣。中者邓里閒作蒯苴。蠢竖婢妾，韦沓絲履。走者茸芰絇綰。","sortOrder":38},
  {"id":"s_work_dtl_6_39","chapterId":"ch_work_dtl_6","text":"“古聖人勞躬養神，節欲適情，尊天敬地，履德行仁。是以上天歆焉，永其世而丰其年。故尧秀眉高彩，享國百載。及秦始皇覽怪迂，信禨祥，使盧生求羨門高，徐市等入海求不死之藥。當此之時，燕、齊之士，釋鋤耒，爭言神仙。方士於是趣鹹陽者以千數，言仙人食金飲珠，然後寿與天地相保。於是數巡狩五嶽、濱海之馆，以求神仙蓬萊之屬。數幸之郡縣，富人以赀佐，貧者筑道旁。其後，小者亡逃，大者藏匿；吏捕索掣頓，不以道理。名宮之旁，庐舍丘落，無生苗立树；百姓離心，怨思者十有半。《書》曰：‘享多儀，儀不及物曰不享。’故聖人非仁義不載於己，非正道不御於前。是以先帝誅文成、五利等，宣帝建學官，親近忠良，欲以絕怪惡之端，而昭至德之途也。","sortOrder":39},
  {"id":"s_work_dtl_6_40","chapterId":"ch_work_dtl_6","text":"“宮室奢侈，林木之蠹也。器械雕琢，财用之蠹也。衣服靡麗，布帛之蠹也。狗馬食人之食，五穀之蠹也。口腹從恣，魚肉之蠹也。用費不節，府库之蠹也。漏積不禁，田野之蠹也。丧祭無度，傷生之蠹也。墮成变故傷功，工商上通傷農。故一杯棬用百人之力，一屏風就萬人之功，其為害亦多矣！目修於五色，耳營於五音，體極輕薄，口極甘脆，功積於無用，财盡於不急，口腹不可為多。故國病聚不足即政怠，人病聚不足則身危。”","sortOrder":40},
  {"id":"s_work_dtl_6_41","chapterId":"ch_work_dtl_6","text":"丞相曰：“治聚不足奈何？”","sortOrder":41},
  {"id":"s_work_dtl_6_42","chapterId":"ch_work_dtl_6","text":"◎救匮第三十","sortOrder":42},
  {"id":"s_work_dtl_6_43","chapterId":"ch_work_dtl_6","text":"賢良曰：“蓋桡枉者以直，救文者以质。昔者，晏子相齊，一狐裘三十載。故民奢，示之以俭；民俭，示之以禮。方今公卿大夫子孫，誠能節車舆，適衣服，躬親節俭，率以敦朴，罢園池，損田宅，內無事乎市列，外無事乎山泽，農夫有所施其功，女工有所粥其業；如是，則氣脈和平，無聚不足之病矣。”","sortOrder":43},
  {"id":"s_work_dtl_6_44","chapterId":"ch_work_dtl_6","text":"大夫曰：“孤子語孝，躄者語杖，貧者語仁，賤者語治。議不在己者易稱，從旁議者易是，其當局則亂。故公孫弘布被，倪宽練袍，衣若仆妾，食若庸夫。淮南逆於內，蠻、夷暴於外，盜賊不為禁，奢侈不為節；若疫歲之巫，徒能鼓口耳，何散不足之能治乎？”","sortOrder":44},
  {"id":"s_work_dtl_6_45","chapterId":"ch_work_dtl_6","text":"賢良曰：“高皇帝之時，萧、曹為公，滕、灌之屬為卿，濟濟然斯則賢矣。文、景之际，建元之始，大臣尚有爭引守正之義。自此之後，多承意從欲，少敢直言面議而正刺，因公而徇私。故武安丞相訟園田，爭曲直人主之前。夫九層之台一傾，公输子不能正；本朝一邪，伊、望不能复。故公孫丞相、倪大夫侧身行道，分祿以養賢，卑己以下士，功業顯立，日力不足，無行人子產之繼。而葛繹、彭侯之等，隳坏其緒，紕亂其紀，毀其客馆議堂，以為馬廄婦舍，無養士之禮，而尚驕矜之色，廉恥陵遲而爭於利矣。故良田廣宅，民無所之；不恥為利者滿朝市，列田畜者弥郡國，橫暴掣頓，大第巨舍之旁，道路且不通，此固難医而不可為工。”","sortOrder":45},
  {"id":"s_work_dtl_6_46","chapterId":"ch_work_dtl_6","text":"大夫勃然作色，默而不應。","sortOrder":46},
  {"id":"s_work_dtl_6_47","chapterId":"ch_work_dtl_6","text":"◎箴石第三十一","sortOrder":47},
  {"id":"s_work_dtl_6_48","chapterId":"ch_work_dtl_6","text":"丞相曰：“吾聞諸鄭長者曰：‘君子正顏色，則遠暴嫚；出辭氣，則遠鄙倍矣。’故言可述，行可則。此有司夙昔所願睹也。若夫劍客論、博奕辯，盛色而相蘇，立權以不相假，使有司不能取賢良之議，而賢良、文學被不遜之名，竊為諸生不取也。公孫龍有言：‘論之為道辯，故不可以不屬意，屬意相宽，相宽其歸爭，爭而不讓，則入於鄙。’今有司以不仁，又蒙素餐，無以更责雪恥矣。縣官所招舉賢良、文學，而及親民伟仕，亦未見其能用箴石而医百姓之疾也。”","sortOrder":48},
  {"id":"s_work_dtl_6_49","chapterId":"ch_work_dtl_6","text":"賢良曰：“贾生有言：‘恳言則辭淺而不入，深言則逆耳而失指。’故曰：‘談何容易。’談且不易，而况行之乎？此胡建所以不得其死，而吳得幾不免於患也。語曰：‘五盜執一良人，枉木惡直繩。’今欲下箴石，通關鬲，則恐有盛、胡之累，懷箴橐艾，則被不工之名。‘狼跋其胡，載踕其尾。’君子之路，行止之道固狹耳。此子石所以叹息也。”","sortOrder":49},
  {"id":"s_work_dtl_6_50","chapterId":"ch_work_dtl_6","text":"◎除狹第三十二","sortOrder":50},
  {"id":"s_work_dtl_6_51","chapterId":"ch_work_dtl_6","text":"大夫曰：“賢者處大林，遭風雷而不迷。愚者雖處平敞大路，猶暗惑焉。今守、相親剖符贊拜，莅一郡之眾，古方伯之位也。受命专製，宰割千里，不御於內；善惡在於己，己不能故耳，道何狹之有哉？”","sortOrder":51},
  {"id":"s_work_dtl_6_52","chapterId":"ch_work_dtl_6","text":"賢良曰：“古之進士也，乡擇而里選，論其才能，然後官之，勝職任然後爵而祿之。故士修之乡曲，升諸朝廷，行之幽隱，明足顯著。疏遠無失士，小大無遺功。是以賢者進用，不肖者簡黜。今吏道雜而不選，富者以财贾官，勇者以死射功。戲車鼎躍，鹹出補吏，累功積日，或至卿相。垂青繩，擐銀龟，擅殺生之柄，专萬民之命。弱者，猶使羊將狼也，其亂必矣。強者，則是予狂夫利劍也，必妄殺生也。是以往者，郡國黎民相乘而不能理，或至鋸頸殺不辜而不能正。執綱紀非其道，蓋博亂愈甚。古者，封賢祿能，不過百里；百里之中而為都，疆垂不過五十，猶以為一人之身，明不能照，聰不得達，故立卿、大夫、士以佐之，而政治乃備。今守、相或無古諸侯之賢，而莅千里之政，主一郡之眾，施聖主之德，擅生殺之法，至重也。非仁人不能任，非其人不能行。一人之身，治亂在己，千里與之轉化，不可不熟擇也。故人主有私人以财，不私人以官，懸賞以待功，序爵以俟賢，舉善若不足，黜惡若仇讎，固為其非功而殘百姓也。夫辅主德，开臣途，在於選賢而器使之，擇練守、相然後任之。”","sortOrder":52},
  {"id":"s_work_dtl_6_53","chapterId":"ch_work_dtl_6","text":"◎疾貪第三十三","sortOrder":53},
  {"id":"s_work_dtl_6_54","chapterId":"ch_work_dtl_6","text":"大夫曰：“然。為医以拙矣，又多求謝。為吏既多不良矣，又侵漁百姓。長吏厲諸小吏，小吏厲諸百姓。故不患擇之不熟，而患求之與得異也；不患其不足也，患其貪而無厭也。”","sortOrder":54},
  {"id":"s_work_dtl_6_55","chapterId":"ch_work_dtl_6","text":"賢良曰：“古之製爵祿也，卿大夫足以润賢厚士，士足以優身及党，庶人為官者，足以代其耕而食其祿。今小吏祿薄，郡國繇役，遠至三辅，粟米貴，不足相贍。常居則匮於衣食，有故則賣畜粥業。非徒是也，繇使相遣，官庭攝追，小計權吏，行施乞貸，長吏侵漁，上府下求之縣，縣求之乡，乡安取之哉？語曰：‘货賂下流，猶水之赴下，不竭不止。’今大川江河飲巨海，巨海受之，而欲溪穀之讓流潦；百官之廉，不可得也。夫欲影正者端其表，欲下廉者先之身。故貪鄙在率不在下，教訓在政不在民也。”","sortOrder":55},
  {"id":"s_work_dtl_6_56","chapterId":"ch_work_dtl_6","text":"大夫曰：“賢不肖有质，而貪鄙有性，君子內絜己而不能純教於彼。故周公非不正管、蔡之邪，子產非不正邓皙之伪也。夫內不從父兄之教，外不畏刑法之罪，周公、子產不能化，必也。今一一則责之有司，有司豈能縛其手足而使之無為非哉？”","sortOrder":56},
  {"id":"s_work_dtl_6_57","chapterId":"ch_work_dtl_6","text":"賢良曰：“驷馬不馴，御者之過也。百姓不治，有司之罪也。春秋刺譏不及庶人，责其率也。故古者大夫將臨刑，聲色不御，刑以當矣，猶三巡而嗟叹之。其恥不能以化而傷其不全也。政教闇而不著，百姓顛蹶而不扶，猶赤子臨井焉，聽其入也。若此，則何以為民父母？故君子急於教，缓於刑。刑一而正百，殺一而慎萬。是以周公誅管、蔡，而子產誅邓皙也。刑誅一施，民遵禮義矣。夫上之化下，若風之靡草，無不從教。何一一而縛之也？”","sortOrder":57},
  {"id":"s_work_dtl_6_58","chapterId":"ch_work_dtl_6","text":"◎後刑第三十四","sortOrder":58},
  {"id":"s_work_dtl_6_59","chapterId":"ch_work_dtl_6","text":"大夫曰：“古之君子，善善而惡惡。人君不畜惡民，農夫不畜無用之苗。無用之苗，苗之害也；無用之民，民之賊也。鉏一害而眾苗成，刑一惡而萬民悅。雖周公、孔子不能釋刑而用惡。家之有姐子，器皿不居，况姐民乎！民者敖於愛而聽刑。故刑所以正民，鉏所以別苗也。”","sortOrder":59},
  {"id":"s_work_dtl_6_60","chapterId":"ch_work_dtl_6","text":"賢良曰：“古者，篤教以导民，明辟以正刑。刑之於治，猶策之於御也。良工不能無策而御、有策而勿用。聖人假法以成教，教成而刑不施。故威厲而不殺，刑設而不犯。今废其紀綱而不能張，坏其禮義而不能防。民陷於網從而獵之以刑，是猶开其阑牢，發以毒矢也，不盡不止。曾子曰：‘上失其道，民散久矣。如得其情，即哀矜而勿喜。’夫不傷民之不治，而伐己之能得奸，猶弋者睹鳥獸掛罻羅而喜也。今天下之被誅者，不必有管、蔡之邪、邓皙之伪，恐苗盡而不別，民欺而不治也。孔子曰：‘人而不仁，疾之已甚，亂也。’故民亂反之政，政亂反之身，身正而天下定。是以君子嘉善而矜不能，恩及刑人，德润窮夫，施惠悅爾，行刑不樂也。”","sortOrder":60},
  {"id":"s_work_dtl_6_61","chapterId":"ch_work_dtl_6","text":"◎授時第三十五","sortOrder":61},
  {"id":"s_work_dtl_6_62","chapterId":"ch_work_dtl_6","text":"大夫曰：“共其地，居是世也，非有灾害疾疫，獨以貧窮，非惰則奢也；無奇業旁入，而猶以富給，非俭則力也。今曰施惠悅爾，行刑不樂；則是闵無行之人，而養惰奢之民也。故妄予不為惠，惠惡者不為仁。”","sortOrder":62},
  {"id":"s_work_dtl_6_63","chapterId":"ch_work_dtl_6","text":"賢良曰：“三代之盛無亂萌，教也；夏、商之季世無順民，俗也。是以王者設庠序，明教化，以防道其民，及政教之洽，性仁而喻善。故禮義立，則耕者讓於野；禮義坏，則君子爭於朝。人爭則亂，亂則天下不均，故或貧或富。富則仁生，贍則爭止。昏暮叩人門戶，求水火，貪夫不吝，何則？所饒也。夫為政而使菽粟如水火，民安有不仁者乎！”","sortOrder":63},
  {"id":"s_work_dtl_6_64","chapterId":"ch_work_dtl_6","text":"大夫曰：“博戲馳逐之徒，皆富人子弟，非不足者也。故民饒則僣侈，富則驕奢，坐而委蛇，起而為非，未見其仁也。夫居事不力，用财不節，雖有财如水火，窮乏可立而待也。有民不畜，有司雖助之耕織，其能足之乎？”","sortOrder":64},
  {"id":"s_work_dtl_6_65","chapterId":"ch_work_dtl_6","text":"賢良曰：“周公之相成王也，百姓饒樂，國無窮人，非代之耕織也。易其田畴，薄其稅斂，則民富矣。上以奉君親，下無飢寒之忧，則教可成也。《語》曰：‘既富矣，又何加焉？曰，教之。’教之以德，齊之以禮，則民徙義而從善，莫不入孝出悌，夫何奢侈暴慢之有？管子曰：‘仓廪實而知禮節，百姓足而知榮辱。’故富民易與適禮。”","sortOrder":65},
  {"id":"s_work_dtl_6_66","chapterId":"ch_work_dtl_6","text":"大夫曰：“縣官之於百姓，若慈父之於子也：忠焉能勿誨乎？愛之而勿勞乎！故春親耕以勸農，赈貸以贍不足，通滀水，出輕系，使民務時也。蒙恩被泽，而至今猶以貧困，其難與適道若是夫！”","sortOrder":66},
  {"id":"s_work_dtl_6_67","chapterId":"ch_work_dtl_6","text":"賢良曰：“古者，春省耕以補不足，秋省斂以助不給。民勤於财則貢賦省，民勤於力則功筑罕。為民愛力，不奪須臾。故召伯聽斷於甘棠之下，為妨農業之務也。今時雨澍泽，种懸而不得播，秋稼零落乎野而不得收。田畴赤地，而停落成市，發春而後，懸青幡而策土牛，殆非明主勸耕稼之意，而春令之所謂也。”","sortOrder":67},
  {"id":"s_work_dtl_6_68","chapterId":"ch_work_dtl_6","text":"◎水旱第三十六","sortOrder":68},
  {"id":"s_work_dtl_6_69","chapterId":"ch_work_dtl_6","text":"大夫曰：“禹、湯聖主，後稷、伊尹賢相也，而有水旱之灾。水旱，天之所為，飢穰，陰陽之運也，非人力。故太歲之數，在陽為旱，在陰為水。六歲一飢，十二歲一荒。天道然，殆非獨有司之罪也。”","sortOrder":69},
  {"id":"s_work_dtl_6_70","chapterId":"ch_work_dtl_6","text":"賢良曰：“古者，政有德，則陰陽調，星辰理，風雨時。故行修於內，聲聞於外，為善於下，福應於天。周公載紀而天下太平，國無夭傷，歲無荒年。當此之時，雨不破塊，風不鳴條，旬而一雨，雨必以夜。無丘陵高下皆熟。《詩》曰：‘有渰萋萋，興雨祁祁。’今不省其所以然，而曰‘陰陽之運也’，非所聞也。《孟子》曰：‘野有饿殍，不知收也；狗豕食人食，不知檢也；為民父母，民飢而死，則曰，非我也，歲也，何異乎以刃殺之，則曰，非我也，兵也？’方今之務，在除飢寒之患，罢鹽、鐵，退權利，分土地，趣本業，養桑麻，盡地力也。寡功節用，則民自富。如是，則水旱不能忧，凶年不能累也。”","sortOrder":70},
  {"id":"s_work_dtl_6_71","chapterId":"ch_work_dtl_6","text":"大夫曰：“議者貴其辭約而指明，可於眾人之聽，不至繁文稠辭，多言害有司化俗之計，而家人語。陶朱為生，本末異径，一家數事，而治生之道乃備。今縣官鑄農器，使民務本，不營於末，則無飢寒之累。鹽、鐵何害而罢？”","sortOrder":71},
  {"id":"s_work_dtl_6_72","chapterId":"ch_work_dtl_6","text":"賢良曰：“農，天下之大業也，鐵器，民之大用也。器用便利，則用力少而得作多，農夫樂事勸功。用不具，則田畴荒，穀不殖，用力鮮，功自半。器便與不便，其功相什而倍也。縣官鼓鑄鐵器，大抵多為大器，務應員程，不給民用。民用钝弊，割草不痛，是以農夫作剧，得獲者少，百姓苦之矣。”","sortOrder":72},
  {"id":"s_work_dtl_6_73","chapterId":"ch_work_dtl_6","text":"大夫曰：“卒徒工匠，以縣官日作公事，财用饒，器用備。家人合會，褊於日而勤於用，鐵力不銷煉，堅柔不和。故有司請總鹽、鐵，一其用，平其贾，以便百姓公私。雖虞、夏之為治，不易於此。吏明其教，工致其事，則刚柔和，器用便。此則百姓何苦？而農夫何疾？”","sortOrder":73},
  {"id":"s_work_dtl_6_74","chapterId":"ch_work_dtl_6","text":"賢良曰：“卒徒工匠！故民得占租鼓鑄、煮鹽之時，鹽與五穀同贾，器和利而中用。今縣官作鐵器，多苦惡，用費不省，卒徒煩而力作不盡。家人相一，父子戮力，各務為善器，器不善者不集。農事急，挽運衍之阡陌之間。民相與市買，得以财货五穀新幣易货；或時贳民，不弃作業。置田器，各得所欲。更繇省約，縣官以徒复作，繕治道桥，諸發民便之。今總其原，壹其贾，器多堅〈石堅〉，善惡無所擇。吏數不在，器難得。家人不能多储，多储則镇生。弃膏腴之日，遠市田器，則後良時。鹽、鐵贾貴，百姓不便。貧民或木耕手耨，土耰淡食。鐵官賣器不售或頗賦與民。卒徒作不中呈，時命助之。發征無限，更繇以均剧，故百姓疾苦之。古者，千室之邑，百乘之家，陶冶工商，四民之求，足以相更。故農民不離畦畝，而足乎田器，工人不斬伐而足乎材木，陶冶不耕田而足乎粟米，百姓各得其便，而上無事焉。是以王者務本不作末，去炫耀，除雕琢，湛民以禮，示民以朴，是以百姓務本而不營於末。”","sortOrder":74},
  {"id":"s_work_dtl_6_75","chapterId":"ch_work_dtl_6","text":"《鹽鐵論》　西漢桓宽","sortOrder":75},
  {"id":"s_work_dtl_7_1","chapterId":"ch_work_dtl_7","text":"卷七","sortOrder":1},
  {"id":"s_work_dtl_7_2","chapterId":"ch_work_dtl_7","text":"◎崇禮第三十七","sortOrder":2},
  {"id":"s_work_dtl_7_3","chapterId":"ch_work_dtl_7","text":"大夫曰：“飾幾杖，修樽俎，為賓，非為主也。炫耀奇怪，所以陳四夷，非為民也。夫家人有客，尚有倡優奇变之樂，而况縣官乎？故列羽旄，陳戎馬，所以示威武，奇虫珍怪，所以示懷廣遠、明盛德，遠國莫不至也。”","sortOrder":3},
  {"id":"s_work_dtl_7_4","chapterId":"ch_work_dtl_7","text":"賢良曰：“王者崇禮施德，上仁義而賤怪力，故聖人絕而不言。孔子曰：‘言忠信，行篤敬，雖蠻、貊之邦，不可弃也。’今萬方絕國之君奉贽獻者，懷天子之盛德，而欲觀中國之禮儀，故設明堂、辟雍以示之，扬幹戚、昭《雅》、《頌》以風之。今乃以玩好不用之器，奇虫不畜之獸，角抵諸戲，炫耀之物陳夸之，殆與周公之待遠方殊。昔周公處謙以卑士，執禮以治天下，辭越裳之贽，見恭讓之禮也；既，與入文王之廟，是見大孝之禮也。目睹威儀幹戚之容，耳聽清歌《雅》、《頌》之聲，心充至德，欣然以歸，此四夷所以慕義內附，非重譯狄鞮來觀猛獸熊羆也。夫犀象兕虎，南夷之所多也；騾驢馲駝，北狄之常畜也。中國所鮮，外國賤之，南越以孔雀珥門戶，崑山之旁，以玉璞抵乌鵲。今貴人之所賤，珍人之所饒，非所以厚中國，明盛德也。隋、和，世之名寶也，而不能安危存亡。故喻德示威，惟賢臣良相，不在犬馬珍怪。是以聖王以賢為寶，不以珠玉為寶。昔晏子修之樽俎之間，而折冲乎千里；不能者，雖隋、和滿箧，無益於存亡。”","sortOrder":4},
  {"id":"s_work_dtl_7_5","chapterId":"ch_work_dtl_7","text":"大夫曰：“晏子相齊三君，崔慶無道，劫其君，亂其國，靈公國围；莊公弒死；景公之時，晉人來攻，取垂都，舉臨菑，邊邑削，城郭焚，宮室隳，寶器盡，何冲之所能折乎？由此觀之：賢良所言，賢人為寶，則損益無輕重也。”","sortOrder":5},
  {"id":"s_work_dtl_7_6","chapterId":"ch_work_dtl_7","text":"賢良曰：“管仲去魯入齊，齊霸魯削，非持其眾而歸齊也。伍子胥挟弓幹阖闾，破楚入郢，非負其兵而適吳也。故賢者所在國重，所去國輕。楚有子玉得臣，文公侧席；虞有宮之奇，晉獻不寐。夫賢臣所在，辟除开塞者亦遠矣。故《春秋》曰：‘山有虎豹，葵藿為之不采；國有賢士，邊境為之不害’也。”","sortOrder":6},
  {"id":"s_work_dtl_7_7","chapterId":"ch_work_dtl_7","text":"◎備胡第三十八","sortOrder":7},
  {"id":"s_work_dtl_7_8","chapterId":"ch_work_dtl_7","text":"大夫曰：“鄙語曰：‘賢者容不辱。’以世俗言之，乡曲有桀，人尚辟之。今明天子在上，匈奴公為寇，侵扰邊境，是仁義犯而藜藿采。昔狄人侵太王，匡人畏孔子，故不仁者，仁之賊也。是以縣官厲武以讨不義，設機械以備不仁。”","sortOrder":8},
  {"id":"s_work_dtl_7_9","chapterId":"ch_work_dtl_7","text":"賢良曰：“匈奴處沙漠之中，生不食之地，天所賤而弃之，無壇宇之居，男女之別，以廣野為闾里，以穹庐為家室，衣皮蒙毛，食肉飲血，會市行，牧竖居，如中國之麋鹿耳。好事之臣，求其義，责之禮，使中國幹戈至今未息，萬里設備，此《兔罝》之所刺，故小人非公侯腹心幹城也。”","sortOrder":9},
  {"id":"s_work_dtl_7_10","chapterId":"ch_work_dtl_7","text":"大夫曰：“天子者，天下之父母也。四方之眾，其義莫不願為臣妾；然猶修城郭，設關梁，厲武士，備衛於宮室，所以遠折難而備萬方者也。今匈奴未臣，雖無事，欲釋備，如之何？”","sortOrder":10},
  {"id":"s_work_dtl_7_11","chapterId":"ch_work_dtl_7","text":"賢良曰：“吳王所以見禽於越者，以其越近而陵遠也。秦所以亡者，以外備胡、越而內亡其政也。夫用軍於外，政败於內，備為所患，增主所忧。故人主得其道，則遐邇偕行而歸之，文王是也；不得其道，則臣妾為寇，秦王是也。夫文衰則武勝，德盛則備寡。”","sortOrder":11},
  {"id":"s_work_dtl_7_12","chapterId":"ch_work_dtl_7","text":"大夫曰：“往者，四夷俱強，併為寇虐：朝鮮逾徼，劫燕之東地；東越越東海，略浙江之南；南越內侵，滑服令；氐、僰、冉、駹、巂唐、崑明之屬，扰隴西、巴、蜀。今三垂已平，唯北邊未定。夫一舉則匈奴震懼，中外釋備，而何寡也？”","sortOrder":12},
  {"id":"s_work_dtl_7_13","chapterId":"ch_work_dtl_7","text":"賢良曰：“古者，君子立仁修義，以綏其民，故邇者習善，遠者順之。是以孔子仕於魯，前仕三月及齊平，後仕三月及鄭平，務以德安近而綏遠。當此之時，魯無敵國之難，鄰境之患。強臣变節而忠順，故季桓隳其都城。大國畏義而合好，齊人來歸鄆、讙、龟陰之田。故為政而以德，非獨辟害折冲也，所欲不求而自得。今百姓所以嚣嚣，中外不寧者，咎在匈奴。內無室宇之守，外無田畴之積，隨美草甘水而驅牧，匈奴不变業，而中國以骚動矣。風合而雲解，就之則亡，击之則散，未可一世而舉也。”","sortOrder":13},
  {"id":"s_work_dtl_7_14","chapterId":"ch_work_dtl_7","text":"大夫曰：“古者，明王讨暴衛弱，定傾扶危。衛弱扶危，則小國之君悅；讨暴定傾，則無罪之人附。今不征伐，則暴害不息；不備，則是以黎民委敵也。《春秋》貶諸侯之後，刺不卒戍。行役戍備，自古有之，非獨今也。”","sortOrder":14},
  {"id":"s_work_dtl_7_15","chapterId":"ch_work_dtl_7","text":"賢良曰：“匈奴之地廣大，而戎馬之足輕利，其势易骚動也。利則虎曳，病則鳥折，辟鋒銳而取罢極；少發則不足以更適，多發則民不堪其役。役煩則力罢，用多則财乏。二者不息，則民遺怨。此秦之所以失民心、陨社稷也。古者，天子封畿千里，繇役五百里，勝聲相聞，疾病相恤。無過時之師，無逾時之役。內節於民心，而事適其力。是以行者勸務，而止者安業。今山東之戎馬甲士戍邊郡者，絕殊遼遠，身在胡、越、心懷老母。老母垂泣，室婦悲恨，推其飢渴，念其寒苦。《詩》雲：‘昔我往矣，楊柳依依。今我來思，雨雪霏霏。行道遲遲，載渴載飢。我心傷悲，莫之我哀。’故聖人怜其如此，闵其久去父母妻子，暴露中野，居寒苦之地，故春使使者勞賜，舉失職者，所以哀遠民而慰撫老母也。德惠甚厚，而吏未稱奉職承詔以存恤，或侵侮士卒，興之為市，併力兼作，使之不以理。故士卒失職，而老母妻子感恨也。宋伯姬愁思而宋國火，魯妾不得意而魯寢灾。今天下不得其意者，非獨西宮之女。宋之老母也。《春秋》動眾則書，重民也。宋人围長葛，譏久役也。君子之用心必若是。”","sortOrder":15},
  {"id":"s_work_dtl_7_16","chapterId":"ch_work_dtl_7","text":"大夫默然不對。","sortOrder":16},
  {"id":"s_work_dtl_7_17","chapterId":"ch_work_dtl_7","text":"◎執務第三十九","sortOrder":17},
  {"id":"s_work_dtl_7_18","chapterId":"ch_work_dtl_7","text":"丞相曰：“先王之道，軼久而難复，賢良、文學之言，深遠而難行。夫稱上聖之高行，道至德之美言，非當世之所能及也。願聞方今之急務，可复行於政：使百姓鹹足於衣食，無乏困之忧；風雨時，五穀熟，螟螣不生；天下安樂，盜賊不起；流人還歸，各反其田里；吏皆廉正，敬以奉職，元元各得其理也。”","sortOrder":18},
  {"id":"s_work_dtl_7_19","chapterId":"ch_work_dtl_7","text":"賢良曰：“孟子曰：‘尧、舜之道，非遠人也，而人不思之耳。’《詩》雲：‘求之不得，寤寐思服。’有求如《關雎》，好德如《河廣》，何不濟不得之有？故高山仰止，景行行止，雖不能及，離道不遠也。顏淵曰：‘舜獨何人也，回何人也？’夫思賢慕能，從善不休，則成、康之俗可致，而唐、虞之道可及。公卿未思也，先王之道，何遠之有？齊桓公以諸侯思王政，忧周室，匡諸夏之難，平夷、狄之亂，存亡接絕，信義大行，著於天下。邵陵之會，予之為主。《傳》曰：‘予積也。’故土積而成山阜，水積而成江海，行積而成君子。孔子曰：‘吾於《河廣》，知德之至也。’而欲得之，各反其本，复諸古而已。古者，行役不逾時，春行秋反，秋行春來，寒暑未变，衣服不易，固已還矣。夫婦不失時，人安和如適。獄訟平，刑罰得，則陰陽調，風雨時。上不苛扰，下不煩勞，各修其業，安其性，則螟螣不生，而水旱不起。賦斂省而農不失時，則百姓足，而流人歸其田里。上清靜而不欲，則下廉而不貪。若今則繇役極遠，盡寒苦之地，危難之處，涉胡、越之域，今茲往而來歲旋，父母延頸而西望，男女怨曠而相思，身在東楚，志在西河，故一人行而乡曲恨，一人死而萬人悲。《詩》雲：‘王事靡盬，不能藝稷黍，父母何怙？’‘念彼恭人，涕零如雨。豈不懷歸？畏此罪罟。’吏不奉法以存撫，倍公任私，各以其權充其嗜欲，人愁苦而怨思，上不恤理，則惡政行而邪氣作；邪氣作，則虫螟生而水旱起。若此，雖祷祀雩祝，用事百神無時，豈能調陰陽而息盜賊矣？”","sortOrder":19},
  {"id":"s_work_dtl_7_20","chapterId":"ch_work_dtl_7","text":"◎能言第四十","sortOrder":20},
  {"id":"s_work_dtl_7_21","chapterId":"ch_work_dtl_7","text":"大夫曰：“盲者口能言白黑，而無目以別之。儒者口能言治亂，而無能以行之。夫坐言不行，則牧童兼乌獲之力，蓬頭苞尧、舜之德。故使言而近，則儒者何患於治亂，而盲人何患於白黑哉？言之不出，恥躬之不逮。故卑而言高，能言而不能行者，君子恥之矣。”","sortOrder":21},
  {"id":"s_work_dtl_7_22","chapterId":"ch_work_dtl_7","text":"賢良曰：“能言而不能行者，國之寶也。能行而不能言者，國之用也。兼此二者，君子也。無一者，牧童、蓬頭也。言滿天下，德覆四海，周公是也。口言之，躬行之，豈若默然載施其行而已。則執事亦何患何恥之有？今道不舉而務小利，慕於不急以亂群意，君子雖貧，勿為可也。藥酒，病之利也；正言，治之藥也。公卿誠能自強自忍，食文學之至言，去權诡，罢利官，一歸之於民，親以周公之道，則天下治而頌聲作。儒者安得治亂而患之乎？”","sortOrder":22},
  {"id":"s_work_dtl_7_23","chapterId":"ch_work_dtl_7","text":"◎取下第四十一","sortOrder":23},
  {"id":"s_work_dtl_7_24","chapterId":"ch_work_dtl_7","text":"大夫曰：“不軌之民，困桡公利，而欲擅山泽。從文學、賢良之意，則利歸於下，而縣官無可為者。上之所行則非之，上之所言則譏之，专欲損上徇下，虧主而適臣，尚安得上下之義，君臣之禮？而何頌聲能作也？”","sortOrder":24},
  {"id":"s_work_dtl_7_25","chapterId":"ch_work_dtl_7","text":"賢良曰：“古者，上取有量，自養有度，樂歲不盜，年飢則肆，用民之力，不過歲三日，籍斂，不過十一。君篤愛，臣盡力，上下交讓，天下平。‘浚發爾私’，上讓下也。‘遂及我私’，先公職也。《孟子》曰：‘未有仁而遺其親，義而後其君也。’君君臣臣，何為其無禮義乎？及周之末途，德惠塞而嗜欲眾，君奢侈而上求多，民困於下，怠於上公，是以有履畝之稅，《硕鼠》之詩作也。衛靈公當隆冬興眾穿池，海春諫曰：‘天寒，百姓冻餒，願公之罢役也。’公曰：‘天寒哉？我何不寒哉？’人之言曰：‘安者不能恤危，飽者不能食飢。’故餘粱肉者難為言隱約，處佚樂者難為言勤苦。夫高堂邃宇、廣厦洞房者，不知专屋狹庐、上漏下濕者之〈疒朁〉也。系馬百驷、货财充內、储陳納新者，不知有旦無暮、稱貸者之急也。廣第唐園、良田連比者，不知無運踵之業、竄頭宅者之役也。原馬被山，牛羊滿穀者，不知無孤豚瘠犢者之窭也。高枕談臥、無叫號者，不知忧私责與吏正戚者之愁也。被紈躡韦、搏粱嚙肥者，不知短褐之寒、糠〈米後〉之苦也。從容房闈之間、垂拱持案食者，不知跖耒躬耕者之勤也。乘堅驅良、列騎成行者，不知負簷步行者之勞也。匡床旃席、侍御滿侧者，不知負辂挽船、登高絕流者之難也。衣輕暖、被美裘、處溫室、載安車者，不知乘邊城、飄胡、代、乡清風者之危寒也。妻子好合。子孫保之者，不知老母之憔悴、匹婦之悲恨也。耳聽五音、目视弄優者，不知蒙流矢、距敵方外者之死也。東向伏幾、振筆如調文者，不知木索之急、棰楚者之痛也。坐旃茵之上，安圖籍之言若易然，亦不知步涉者之難也。昔商鞅之任秦也，刑人若刈菅茅，用師若彈丸；從軍者暴骨長城，戍漕者輦車相望，生而往，死而旋，彼獨非人子耶？故君子仁以恕，義以度，所好惡與天下共之，所不施不仁者。公劉好货，居者有積，行者有囊。大王好色，內無怨女，外無曠夫。文王作刑，國無怨獄。武王行師，士樂為之死，民樂為之用。若斯，則民何苦而怨，何求而譏？”","sortOrder":25},
  {"id":"s_work_dtl_7_26","chapterId":"ch_work_dtl_7","text":"公卿愀然，寂若無人。於是遂罢議止詞。","sortOrder":26},
  {"id":"s_work_dtl_7_27","chapterId":"ch_work_dtl_7","text":"奏曰：“賢良、文學不明縣官事，猥以鹽、鐵為不便。請且罢郡國榷沽、關內鐵官。”","sortOrder":27},
  {"id":"s_work_dtl_7_28","chapterId":"ch_work_dtl_7","text":"奏曰：“可。”","sortOrder":28},
  {"id":"s_work_dtl_7_29","chapterId":"ch_work_dtl_7","text":"◎击之第四十二","sortOrder":29},
  {"id":"s_work_dtl_7_30","chapterId":"ch_work_dtl_7","text":"賢良、文學既拜，鹹取列大夫，辭丞相、御史。","sortOrder":30},
  {"id":"s_work_dtl_7_31","chapterId":"ch_work_dtl_7","text":"大夫曰：“前議公事，賢良、文學稱引往古，頗乖世務。論者不必相反，期於可行。往者，縣官未事胡、越之時，邊城四面受敵，北邊尤被其苦。先帝絕三方之難，撫從方國，以為蕃蔽，窮極郡國，以讨匈奴。匈奴壤界獸圈，孤弱無與，此困亡之時也。遼遠不遂，使得复喘息，休養士馬，負绐西域。西域迫近胡寇，沮心內解，必為巨患。是以主上欲扫除，煩仓廪之費也。終日逐禽，罢而釋之，則非計也。蓋舜紹緒，禹成功。今欲以《軍興》击之，何如？”","sortOrder":31},
  {"id":"s_work_dtl_7_32","chapterId":"ch_work_dtl_7","text":"文學曰：“異時，縣官修輕賦，公用饒，人富給。其後，保胡、越，通四夷，費用不足。於是興利害，算車舡，以訾助邊，贖罪告缗，與人以患矣。甲士死於軍旅，中士罢於轉漕，仍之以科適，吏征發極矣。夫勞而息之，極而反本，古之道也，雖舜、禹興，不能易也。”","sortOrder":32},
  {"id":"s_work_dtl_7_33","chapterId":"ch_work_dtl_7","text":"大夫曰：“昔夏後底洪水之灾，百姓孔勤，罢於籠臿，及至其後，鹹享其功。先帝之時，郡國頗煩於戎事，然亦宽三陲之役。語曰：‘見機不遂者陨功。’一日违敵，累世為患。休勞用供，因弊乘時。帝王之道，聖賢之所不能失也。功業有緒，惡勞而不卒，猶耕者倦休而困止也。夫事輟者無功，耕怠者無獲也。”","sortOrder":33},
  {"id":"s_work_dtl_7_34","chapterId":"ch_work_dtl_7","text":"文學曰：“地廣而不德者國危，兵強而凌敵者身亡。虎兕相據，而蝼蚁得志。兩敵相抗，而匹夫乘閒。是以聖王見利慮害，見遠存近。方今為縣官計者，莫若偃兵休士，厚幣結和親，修文德而已。若不恤人之急，不計其難，弊所恃以窮無用之地，亡十獲一，非文學之所知也。”","sortOrder":34},
  {"id":"s_work_dtl_7_35","chapterId":"ch_work_dtl_7","text":"《鹽鐵論》　西漢桓宽","sortOrder":35},
  {"id":"s_work_dtl_8_1","chapterId":"ch_work_dtl_8","text":"卷八","sortOrder":1},
  {"id":"s_work_dtl_8_2","chapterId":"ch_work_dtl_8","text":"◎結和第四十三","sortOrder":2},
  {"id":"s_work_dtl_8_3","chapterId":"ch_work_dtl_8","text":"大夫曰：“漢興以來，修好結和親，所聘遺单於者甚厚；然不紀重质厚賂之故改節，而暴害滋甚。先帝睹其可以武折，而不可以德懷，故廣將帥，招奋击，以誅厥罪；功勋粲然，著於海內，藏於記府，何命‘亡十獲一’乎？夫偷安者後危，慮近者忧邇，賢者離俗，智士權行，君子所慮，眾庶疑焉。故民可與觀成，不可與圖始。此有司所獨見，而文學所不睹。”","sortOrder":3},
  {"id":"s_work_dtl_8_4","chapterId":"ch_work_dtl_8","text":"文學曰：“往者，匈奴結和親，諸夷納貢，即君臣外內相信，無胡、越之患。當此之時，上求寡而易贍，民安樂而無事，耕田而食，桑麻而衣，家有數年之蓄，縣官餘货财，闾里耆老，鹹及其泽。自是之後，退文任武，苦師勞眾，以略無用之地，立郡沙石之間，民不能自守，發屯乘城，挽輦而贍之。愚竊見其亡，不睹其成。”","sortOrder":4},
  {"id":"s_work_dtl_8_5","chapterId":"ch_work_dtl_8","text":"大夫曰：“匈奴以虛名市於漢，而實不從；數為蠻、貊所绐，不痛之，何故也？高皇帝仗劍定九州；今以九州而不行於匈奴。闾里常民，尚有枭散，况萬里之主與小國之匈奴乎？夫以天下之力勤何不摧？以天下之士民何不服？今有帝名，而威不信於長城之外，反賂遺而尚踞敖，此五帝所不忍，三王所畢怒也。”","sortOrder":5},
  {"id":"s_work_dtl_8_6","chapterId":"ch_work_dtl_8","text":"文學曰：“湯事夏而卒服之，周事殷而卒滅之。故以大御小者王，以強凌弱者亡。聖人不困其眾以兼國，良御不困其馬以兼道。故造父之御不失和，聖人之治不倍德。秦攝利衔以御宇內，執修棰以笞八極，驂服以罢，而鞭策愈加，故有傾衔遺棰之变。士民非不眾，力勤非不多也，皆內倍外附而莫為用。此高皇帝所以仗劍而取天下也。夫兩主好合，內外交通，天下安寧，世世無患，士民何事？三王何怒焉？”","sortOrder":6},
  {"id":"s_work_dtl_8_7","chapterId":"ch_work_dtl_8","text":"大夫曰：“伯翳之始封秦，地為七十里。穆公开霸，孝公廣業。自卑至上，自小至大。故先祖基之，子孫成之。軒轅戰涿鹿，殺兩皞、蚩尤而為帝，湯、武伐夏、商，誅桀、紂而為王。黃帝以戰成功，湯、武以伐成孝。故手足之勤，腹腸之養也。當世之務，後世之利也。今四夷內侵，不攘，萬世必有長患。先帝興義兵以誅強暴，東滅朝鮮，西定冉、駹，南擒百越，北挫強胡，追匈奴以廣北州，湯、武之舉，蚩尤之兵也。故聖主斥地，非私其利，用兵，非徒奋怒也，所以匡難辟害，以為黎民遠慮。”","sortOrder":7},
  {"id":"s_work_dtl_8_8","chapterId":"ch_work_dtl_8","text":"文學曰：“秦南禽劲越，北却強胡，竭中國以役四夷，人罢極而主不恤，國內潰而上不知；是以一夫倡而天下和，兵破陳涉，地奪諸侯，何嗣之所利？《詩》雲：‘雍雍鳴鳱，旭日始旦。’登得前利，不念後咎。故吳王知伐齊之便，不知幹遂之患。秦知進取之利，而不知鸿門之難。是知一而不知十也。周謹小而得大，秦欲大而亡小。語曰：‘前車覆，後車戒。’‘殷鑒不遠，在夏後之世’矣。”","sortOrder":8},
  {"id":"s_work_dtl_8_9","chapterId":"ch_work_dtl_8","text":"◎誅秦第四十四","sortOrder":9},
  {"id":"s_work_dtl_8_10","chapterId":"ch_work_dtl_8","text":"大夫曰：“秦、楚、燕、齊、周之封國也；三晉之君，齊之田氏，諸侯家臣也；內守其國，外伐不義，地廣壤進，故立號萬乘，而為諸侯。宗周修禮長文，然國翦弱，不能自存，東攝六國，西畏於秦，身以放遷，宗廟絕祀。賴先帝大惠，紹興其後，封嘉潁川，號周子男君。秦既併天下，東絕沛水，併滅朝鮮，南取陆梁，北却胡、狄，西略氐、羌，立帝號，朝四夷。舟車所通，足跡所及，靡不畢至。非服其德，畏其威也。力多則人朝，力寡則朝於人矣。”","sortOrder":10},
  {"id":"s_work_dtl_8_11","chapterId":"ch_work_dtl_8","text":"文學曰：“禹、舜，尧之佐也，湯、文，夏、商之臣也，其所以從八極而朝海內者，非以陆梁之地，兵革之威也。秦、楚、三晉號萬乘，不務積德而務相侵，構兵爭強而卒俱亡。雖以進壤廣地，如食荝之充腸也，欲其安存，何可得也？夫禮讓為國者若江、海，流弥久不竭，其本美也。苟為無本，若蒿火暴怒而無繼，其亡可立而待，戰國是也。周德衰，然後列於諸侯，至今不絕。秦力盡而滅其族，安得朝人也？”","sortOrder":11},
  {"id":"s_work_dtl_8_12","chapterId":"ch_work_dtl_8","text":"大夫曰：“中國與邊境，猶支體與腹心也。夫肌膚寒於外，腹心疾於內，內外之相勞，非相為賜也！唇亡則齒寒，支體傷而心忄朁怛。故無手足則支體废，無邊境則內國害。昔者，戎狄攻太王於邠，逾岐、梁而與秦界於涇、渭，東至晉之陆浑，侵暴中國，中國疾之。今匈奴蠶食內侵，遠者不離其苦，獨邊境蒙其败。《詩》雲：‘忧心惨惨，念國之為虐。’不征備，則暴害不息。故先帝興義兵以征厥罪，遂破祁連、天山，散其聚党，北略至龍城，大围匈奴，单於失魂，仅以身免，乘奔逐北，斬首捕虜十餘萬。控絃之民，旃裘之長，莫不沮胆，挫折遠遁，遂乃振旅。浑耶率其眾以降，置五屬國以距胡，則長城之內，河、山之外，罕被寇灾。於是下詔令，减戍漕，宽徭役。初雖勞苦，卒獲其慶。”","sortOrder":12},
  {"id":"s_work_dtl_8_13","chapterId":"ch_work_dtl_8","text":"文學曰：“周累世積德，天下莫不願以為君，故不勞而王，恩施由近而遠，而蠻、貊自至。秦任戰勝以併天下，小海內而貪胡、越之地，使蒙恬击胡，取河南以為新秦，而忘其故秦，筑長城以守胡，而亡其所守。往者，兵革亟動，師旅數起，長城之北，旋車遺鏃相望。及李廣利等輕計－計還馬足，莫不寒心；雖得浑耶，不能更所亡。此非社稷之至計也。”","sortOrder":13},
  {"id":"s_work_dtl_8_14","chapterId":"ch_work_dtl_8","text":"◎伐功第四十五","sortOrder":14},
  {"id":"s_work_dtl_8_15","chapterId":"ch_work_dtl_8","text":"大夫曰：“齊桓公越燕伐山戎，破孤竹，殘令支。趙武靈王逾句註，過代穀，略滅林胡、樓煩。燕袭走東胡，辟地千里，度遼東而攻朝鮮。蒙公為秦击走匈奴，若鷙鳥之追群雀。匈奴势慑，不敢南面而望十餘年。及其後，蒙公死而諸侯叛秦，中國扰亂，匈奴紛紛，乃敢复為邊寇。夫以小國燕、趙，尚猶却寇虜以廣地，今以漢國之大，士民之力，非特齊桓之眾，燕、趙之師也；然匈奴久未服者，群臣不併力，上下未諧故也。”","sortOrder":15},
  {"id":"s_work_dtl_8_16","chapterId":"ch_work_dtl_8","text":"文學曰：“古之用師，非貪壤土之利，救民之患也。民思之，若旱之望雨，箪食壶漿，以逆王師。故忧人之患者，民一心而歸之，湯、武是也。不愛民之死，力盡而潰叛者，秦王是也。孟子曰：‘君不乡道，不由仁義，而為之強戰，雖克必亡。’此中國所以扰亂，非蒙恬死而諸侯叛秦。昔周室之盛也，越裳氏來獻，百蠻致貢。其後周衰，諸侯力征，蠻、貊分散，各有聚党，莫能相一，是以燕、趙能得意焉。其後，匈奴稍強，蠶食諸侯，故破走月氏，因兵威，徙小國，引弓之民，併為一家，一意同力，故難製也。前君為先帝畫匈奴之策：‘兵據西域，奪之便势之地，以候其变。以漢之強，攻於匈奴之眾，若以強弩潰痈疽；越之禽吳，豈足道哉！’上以為然。用君之義，聽君之計，雖越王之任种、蠡不過。以搜粟都尉為御史大夫，持政十有餘年，未見种、蠡之功，而見靡弊之效，匈奴不為加俯，而百姓黎民以敝矣。是君之策不能弱匈奴，而反衰中國也。善為計者，固若此乎？”","sortOrder":16},
  {"id":"s_work_dtl_8_17","chapterId":"ch_work_dtl_8","text":"◎西域第四十六","sortOrder":17},
  {"id":"s_work_dtl_8_18","chapterId":"ch_work_dtl_8","text":"大夫曰：“往者，匈奴據河、山之险，擅田牧之利，民富兵強，行入為寇，則句註之內驚動，而上郡以南鹹城。文帝時，虜入萧關，烽火通甘泉，群臣懼不知所出，乃請屯京師以備胡。胡西役大宛、康居之屬，南與群羌通。先帝推讓斥奪廣饒之地，建張掖以西，隔絕羌、胡，瓜分其援。是以西域之國，皆內拒匈奴，斷其右臂，曳劍而走，故募人田畜以廣用，長城以南，濱塞之郡，馬牛放縱，蓄積布野，未睹其計之所過也。夫以弱越而遂意強吳，才地計眾非鈞也，主思臣謀，其往必矣。”","sortOrder":18},
  {"id":"s_work_dtl_8_19","chapterId":"ch_work_dtl_8","text":"文學曰：“吳、越迫於江、海，三川循環之，處於五湖之間，地相迫，壤相次，其势易以相禽也。金鼓未聞，旌旗未舒，行軍未定，兵以接矣。師無辎重之費，士無乏絕之勞，此所謂食於厨仓而戰於門郊者也。今匈奴牧於無窮之泽，東西南北，不可窮極，雖輕車利馬，不能得也，况負重嬴兵以求之乎？其势不相及也。茫茫乎若行九皋未知所止，皓皓乎若無網羅而漁江、海，雖及之，三軍罢弊，適遺之餌也。故明王知其無所利，以為役不可數行，而權不可久張也，故詔公卿大夫、賢良、文學，所以复枉興微之路。公卿宜思百姓之急，匈奴之害，緣聖主之心，定安平之業。今乃留心於末計，摧本議，不順上意，未為盡於忠也。","sortOrder":19},
  {"id":"s_work_dtl_8_20","chapterId":"ch_work_dtl_8","text":"大夫曰：“初，貳師不克宛而還也，議者欲使人主不遂忿，則西域皆瓦解而附於胡，胡得眾國而益強。先帝絕奇聽，行武威，還袭宛，宛舉國以降，效其器物，致其寶馬。乌孫之屬駭胆，請為臣妾。匈奴失魄，奔走遁逃，雖未盡服，遠處寒苦硗埆之地，壮者死於祁連、天山，其孤未复。故群臣議以為匈奴困於漢兵，折翅傷翼，可遂击服。會先帝弃群臣，以故匈奴不革。譬如為山，未成一簣而止，度功業而無繼成之理，是弃與胡而資強敵也。輟幾沮成，為主計若斯，亦未可謂盡忠也。”","sortOrder":20},
  {"id":"s_work_dtl_8_21","chapterId":"ch_work_dtl_8","text":"文學曰：“有司言外國之事，議者皆徼一時之權，不慮其後。張騫言大宛之天馬汗血，安息之真玉大鳥，縣官既聞如甘心焉，乃大興師伐宛，歷數期而後克之。夫萬里而攻人之國，兵未戰而物故過半，雖破宛得寶馬，非計也。當此之時，將卒方赤面而事四夷，師旅相望，郡國併發，黎人困苦，奸伪萌生，盜賊併起，守尉不能禁，城邑不能止。然後遣上大夫衣繡衣以興击之。當此時，百姓元元，莫必其命，故山東豪杰，頗有異心。賴先帝聖靈斐然。其咎皆在於欲畢匈奴而遠幾也。為主計若此，可謂忠乎？”","sortOrder":21},
  {"id":"s_work_dtl_8_22","chapterId":"ch_work_dtl_8","text":"◎世務第四十七","sortOrder":22},
  {"id":"s_work_dtl_8_23","chapterId":"ch_work_dtl_8","text":"大夫曰：“諸生妄言！議者令可詳用，無徒守椎車之語，滑稽而不可循。夫漢之有匈奴，譬若木之有蠹，如人有疾，不治則浸以深。故謀臣以為击奪以困極之。諸生言以德懷之，此有其語而不可行也。諸生上無以似三王，下無以似近秦，令有司可舉而行當世，安蒸庶而寧邊境者乎？”","sortOrder":23},
  {"id":"s_work_dtl_8_24","chapterId":"ch_work_dtl_8","text":"文學曰：“昔齊桓公內附百姓，外綏諸侯，存亡接絕，而天下從風。其後，德虧行衰，葵丘之會，振而矜之，叛者九國。《春秋》刺其不崇德而崇力也。故任德，則強楚告服，遠國不召而自至；任力，則近者不親，小國不附。此其效也。誠上觀三王之所以昌，下論秦之所以亡，中述齊桓所以興，去武行文，废力尚德，罢關梁，除障塞，以仁義导之，則北垂無寇虜之忧，中國無幹戈之事矣。”","sortOrder":24},
  {"id":"s_work_dtl_8_25","chapterId":"ch_work_dtl_8","text":"大夫曰：“事不豫辨，不可以應卒。內無備，不可以御敵。《詩》雲：‘誥爾民人，謹爾侯度，用戒不虞。’故有文事，必有武備。昔宋襄公信楚而不備，以取大辱焉，身執囚而國幾亡。故雖有誠信之心，不知權变，危亡之道也。《春秋》不與夷、狄之執中國，為其無信也。匈奴貪狼，因時而動，乘可而發，飆舉電至。而欲以誠信之心，金帛之寶，而信無義之诈，是猶親跖、蹻而扶猛虎也。”","sortOrder":25},
  {"id":"s_work_dtl_8_26","chapterId":"ch_work_dtl_8","text":"文學曰：“《春秋》‘王者無敵。’言其仁厚，其德美，天下賓服，莫敢交也。德行延及方外，舟車所臻，足跡所及，莫不被泽。蠻、貊異國，重譯自至。方此之時，天下和同，君臣一德，外內相信，上下辑睦。兵設而不试，幹戈閉藏而不用。老子曰：‘兕無所用其角，螫虫無所输其毒。’故君仁莫不仁，君義莫不義。世安得跖、蹻而親之乎？”","sortOrder":26},
  {"id":"s_work_dtl_8_27","chapterId":"ch_work_dtl_8","text":"大夫曰：“布心腹，质情素，信誠內感，義形乎色。宋華元、楚司馬子反之相睹也，符契內合，誠有以相信也。今匈奴挟不信之心，懷不测之诈，見利如前，乘便而起，潛進市侧，以袭無備。是猶措重寶於道路而莫之守也。求其不亡，何可得乎？”","sortOrder":27},
  {"id":"s_work_dtl_8_28","chapterId":"ch_work_dtl_8","text":"文學曰：“誠信著乎天下，醇德流乎四海，則近者哥謳而樂之，遠者執禽而朝之。故正近者不以威，來遠者不以武，德義修而任賢良也。故民之於事也，辭佚而就勞，於财也，辭多而就寡。上下交讓，道路雁行。方此之時，賤货而貴德，重義而輕利，賞之不竊，何寶之守也！”","sortOrder":28},
  {"id":"s_work_dtl_8_29","chapterId":"ch_work_dtl_8","text":"◎和親第四十八","sortOrder":29},
  {"id":"s_work_dtl_8_30","chapterId":"ch_work_dtl_8","text":"大夫曰：“昔徐偃王行義而滅，魯哀公好儒而削。知文而不知武，知一而不知二。故君子篤仁以行，然必筑城以自守，設械以自備，為不仁者之害己也。是以古者，搜狝振旅而數軍實焉，恐民之愉佚而亡戒難。故兵革者國之用，城壘者國之固也；而欲罢之，是去表見里，示匈奴心腹也。匈奴輕舉潛進，以袭空虛，是猶不介而當矢石之蹊，禍必不振。此邊境之所懼，而有司之所忧也。”","sortOrder":30},
  {"id":"s_work_dtl_8_31","chapterId":"ch_work_dtl_8","text":"文學曰：“往者，通關梁，交有無，自单於以下，皆親漢內附，往來長城之下。其後，王恢誤謀馬邑，匈奴絕和親，攻當路塞，禍紛拏而不解，兵連而不息，邊民不解甲弛弩，行數十年，介胄而耕耘，鉏耰而候望，燧燔烽舉，丁壮弧絃而出斗，老者超越而入葆。言之足以流涕寒心，則仁者不忍也。《詩》雲：‘投我以桃，報之以李。’未聞善往而有惡來者。故君子敬而無失，與人恭而有禮，四海之內，皆為兄弟也。故內省不疚，夫何忧何懼！”","sortOrder":31},
  {"id":"s_work_dtl_8_32","chapterId":"ch_work_dtl_8","text":"大夫曰：“自春秋諸夏之君，會聚相結，三會之後，乖疑相從，伐戰不止；六國從親，冠帶相接，然未嘗有堅約。况禽獸之國乎！《春秋》存君在楚，詰鼬之會書公，绐夷、狄也。匈奴數和親，而常先犯約，貪侵盜驅，長诈之國也。反复無信，百約百叛，若朱、象之不移，商均之不化。而欲信其用兵之備，親之以德，亦難矣。”","sortOrder":32},
  {"id":"s_work_dtl_8_33","chapterId":"ch_work_dtl_8","text":"文學曰：“王者中立而聽乎天下，德施方外，絕國殊俗，臻於闕廷，鳳皇在列树，麒麟在郊藪，群生庶物，莫不被泽。非足行而仁辦之也，推其仁恩而皇之，誠也。范蠡出於越，由餘長於胡，皆為霸王賢佐。故政有不從之教，而世無不可化之民。《詩》雲：‘酌彼行潦，挹彼註茲。’故公劉處戎、狄，戎、狄化之。太王去豳，豳民隨之。周公修德，而越裳氏來。其從善如影响。為政務以德親近，何忧於彼之不改？”","sortOrder":33},
  {"id":"s_work_dtl_8_34","chapterId":"ch_work_dtl_8","text":"《鹽鐵論》　西漢桓宽","sortOrder":34},
  {"id":"s_work_dtl_9_1","chapterId":"ch_work_dtl_9","text":"卷九","sortOrder":1},
  {"id":"s_work_dtl_9_2","chapterId":"ch_work_dtl_9","text":"◎繇役第四十九","sortOrder":2},
  {"id":"s_work_dtl_9_3","chapterId":"ch_work_dtl_9","text":"大夫曰：“屠者解分中理，可橫以手而離也；至其抽筋凿骨，非行金斧不能决。聖主循性而化，有不從者，亦將舉兵而征之，是以湯誅葛伯，文王誅犬夷。及後戎、狄猾夏，中國不寧，周宣王、仲山甫式遏寇虐。《詩》雲：‘薄伐獫玁，至於太原。’‘出車彭彭，城彼朔方。’自古明王不能無征伐而服不義，不能無城壘而御強暴也。”","sortOrder":3},
  {"id":"s_work_dtl_9_4","chapterId":"ch_work_dtl_9","text":"文學曰：“舜執幹戚而有苗服，文王底德而懷四夷。《詩》雲：‘鎬京辟雍，自西自東，自南自北，無思不服。’普天之下，惟人面之倫，莫不引領而歸其義。故畫地為境，人莫之犯。子曰：‘白刃可冒，中庸不可入。’至德之謂也。故善攻不待堅甲而克，善守不待渠梁而固。武王之伐殷也，執黃鉞，誓牧之野，天下之士莫不願為之用。既而偃兵，搢笏而朝，天下之民莫不願為之臣。既以義取之，以德守之。秦以力取之，以法守之，本末不得，故亡。夫文猶可長用，而武難久行也。”","sortOrder":4},
  {"id":"s_work_dtl_9_5","chapterId":"ch_work_dtl_9","text":"大夫曰：“《詩》雲：‘獫玁孔炽，我是用戒。’‘武夫潢潢，經營四方。’故守御征伐，所由來久矣。《春秋》大戎未至而豫御之。故四支強而躬體固，華葉茂而本根據。故飭四境所以安中國也，發戍漕所以審勞佚也。主忧者臣勞，上危者下死。先帝忧百姓不贍，出禁錢，解乘舆驂，貶樂損膳，以赈窮備邊費。未見報施之義，而見沮成之理，非所聞也。”","sortOrder":5},
  {"id":"s_work_dtl_9_6","chapterId":"ch_work_dtl_9","text":"文學曰：“周道衰，王跡熄，諸侯爭強，大小相凌。是以強國務侵，弱國設備。甲士勞戰陣，役於兵革，故君勞而民困苦也。今中國為一統，而方內不安，徭役遠而外內煩也。古者，無過年之繇，無逾時之役。今近者數千里，遠者過萬里，歷二期。長子不還，父母愁忧，妻子詠叹，憤懣之恨發動於心，慕思之積痛於骨髓。此《杕杜》、《采薇》之所為作也。”","sortOrder":6},
  {"id":"s_work_dtl_9_7","chapterId":"ch_work_dtl_9","text":"◎险固第五十","sortOrder":7},
  {"id":"s_work_dtl_9_8","chapterId":"ch_work_dtl_9","text":"大夫曰：“虎兕所以能執熊羆、服群獸者，爪牙利而攫便也。秦所以超諸侯、吞天下、併敵國者，险阻固而势居然也。故龟猖有介，狐貉不能禽；蝮蛇有螫，人忌而不輕。故有備則製人，無備則製於人。故仲山甫補袞職之闕，蒙公筑長城之固，所以備寇難，而折冲萬里之外也。今不固其外，欲安其內，猶家人不堅垣牆，狗吠夜驚，而闇昧妄行也。”","sortOrder":8},
  {"id":"s_work_dtl_9_9","chapterId":"ch_work_dtl_9","text":"文學曰：“秦左殽、函，右隴阺，前蜀、漢，後山、河，四塞以為固，金城千里，良將勇士，設利器而守陉隧，墨子守雲梯之械也。以為雖湯、武复生，蚩尤复起，不輕攻也。然戍卒陳勝無將帥之任，師旅之眾，奋空拳而破百萬之師，無牆篱之難。故在德不在固。誠以仁義為阻，道德為塞，賢人為兵，聖人為守，則莫能入。如此則中國無狗吠之警，而邊境無鹿駭狼顧之忧矣。夫何妄行而之乎？”","sortOrder":9},
  {"id":"s_work_dtl_9_10","chapterId":"ch_work_dtl_9","text":"大夫曰：“古者，為國必察土地、山陵阻险、天時地利，然後可以王霸。故製地城郭，飭溝壘，以御寇固國。《春秋》曰：‘冬浚洙。’修地利也。三軍順天時，以實击虛，然困於阻险，敵於金城。楚莊之围宋，秦師败崤嵚崟，是也。故曰：‘天時不如地利。’羌、胡固，近於邊，今不取，必為四境長患。此季孫之所以忧颛臾，有句賤之变，而為強吳之所悔也。”","sortOrder":10},
  {"id":"s_work_dtl_9_11","chapterId":"ch_work_dtl_9","text":"文學曰：“地利不如人和，武力不如文德。周之致遠，不以地利，以人和也。百世不奪，非以险，以德也。吳有三江、五湖之難，而兼於越。楚有汝淵、兩堂之固，而滅於秦。秦有隴阺、崤塞，而亡於諸侯。晉有河、華、九阿，而奪於六卿。齊有泰山、巨海，而胁於田常。桀、紂有天下，兼於滈亳。秦王以六合困於陳涉。非地利不固，無術以守之也。釋邇忧遠，猶吳不內定其國，而西絕淮水與齊、晉爭強也；越因其罢，击其虛。使吳王用申胥，修德，無恃極其眾，則句踐不免為藩臣海崖，何謀之敢慮也？”","sortOrder":11},
  {"id":"s_work_dtl_9_12","chapterId":"ch_work_dtl_9","text":"大夫曰：“楚自巫山起方城，屬巫、黔中，設扞關以拒秦。秦包商、洛、崤、函，以御諸侯。韓阻宜陽、伊闕，要成皋、太行，以安周、鄭。魏濱洛筑城、阻山帶河，以保晉國。趙結飛狐、句註、孟門，以存邢代。燕塞碣石，絕邪穀，繞援遼。齊撫阿、甄，關榮、歷，倚太山，負海、河。關梁者，邦國之固，而山川者，社稷之寶也。徐人滅舒，《春秋》謂之‘取’，惡其無備，得物之易也。故恤來兵，仁傷刑。君子為國，必有不可犯之難。《易》曰：‘重門击拓，以待暴客。’言備之素修也。”","sortOrder":12},
  {"id":"s_work_dtl_9_13","chapterId":"ch_work_dtl_9","text":"文學曰：“阻险不如阻義，昔湯以七十里，為政於天下，舒以百里，亡於敵國。此其所以見惡也。使關梁足恃，六國不兼於秦；河、山足保，秦不亡於楚、漢。由此觀之：冲隆不足為強，高城不足為固。行善則昌，行惡則亡。王者博愛遠施，外內合同，四海各以其職來祭，何击拓而待？《傳》曰：‘諸侯之有關梁，庶人之有爵祿，非升平之興，蓋自戰國始也。”","sortOrder":13},
  {"id":"s_work_dtl_9_14","chapterId":"ch_work_dtl_9","text":"◎論勇第五十一","sortOrder":14},
  {"id":"s_work_dtl_9_15","chapterId":"ch_work_dtl_9","text":"大夫曰：“荆軻懷數年之謀而事不就者，尺八匕首不足恃也。秦王憚於不意，列斷贲、育者，介七尺之利也。使专諸空拳，不免於為禽；要離無水，不能遂其功。世言強楚劲鄭，有犀兕之甲，棠溪之鋌也。內據金城，外任利兵，是以威行諸夏，強服敵國。故孟贲奋臂，眾人輕之；怯夫有備，其氣自倍。况以吳、楚之士，舞利劍，蹶強弩，以與貉虜騁於中原？一人當百，不足道也！夫如此，則貉無交兵，力不支漢，其势必降。此商君之走魏，而孫臏之破梁也。”","sortOrder":15},
  {"id":"s_work_dtl_9_16","chapterId":"ch_work_dtl_9","text":"文學曰：“楚、鄭之棠溪、墨陽，非不利也，犀胄兕甲，非不堅也，然而不能存者，利不足恃也。秦兼六國之師，據崤、函而御宇內，金石之固，莫耶之利也。然陳勝無士民之資，甲兵之用，鉏耰棘橿，以破冲隆。武昭不击，乌號不發。所謂金城者，非謂筑壤而高土，凿地而深池也。所謂利兵者，非謂吳、越之鋌，幹將之劍也。言以道德為城，以仁義為郭，莫之敢攻，莫之敢入。文王是也。以道德為胄，以仁義為劍，莫之敢當，莫之敢御，湯、武是也。今不建不可攻之城，不可當之兵，而欲任匹夫之役，而行三尺之刃，亦細矣！”","sortOrder":16},
  {"id":"s_work_dtl_9_17","chapterId":"ch_work_dtl_9","text":"大夫曰：“荆軻提匕首入不测之強秦；秦王惶恐失守備，衛者皆懼。专諸手劍摩萬乘，刺吳王，尸孽立正，鎬冠千里。聂政自衛，由韓廷刺其主，功成求得，退自刑於朝，暴尸於市。今誠得勇士，乘強漢之威，凌無義之匈奴，製其死命，责以其過，若曹刿之胁齊桓公，遂其求。推鋒折銳，穹庐扰亂，上下相遁，因以輕銳隨其後。匈奴必交臂不敢格也。”","sortOrder":17},
  {"id":"s_work_dtl_9_18","chapterId":"ch_work_dtl_9","text":"文學曰：“湯得伊尹，以區區之亳兼臣海內，文王得太公，廓酆、鄗以為天下，齊桓公得管仲以霸諸侯，秦穆公得由餘，西戎八國服。聞得賢聖而蠻、貊來享，未聞劫殺人主以懷遠也。《詩》雲：‘惠此中國，以綏四方。’故‘自彼氐、羌，莫不來王。’非畏其威，畏其德也。故義之服無義，疾於原馬良弓；以之召遠，疾於馳傳重驿。”","sortOrder":18},
  {"id":"s_work_dtl_9_19","chapterId":"ch_work_dtl_9","text":"◎論功第五十二","sortOrder":19},
  {"id":"s_work_dtl_9_20","chapterId":"ch_work_dtl_9","text":"大夫曰：“匈奴無城廓之守，溝池之固，修戟強弩之用，仓廪府库之積，上無義法，下無文理，君臣嫚易，上下無禮，織柳為室，旃廗為蓋。素弧骨鏃，馬不粟食。內則備不足畏，外則禮不足稱。夫中國天下腹心，賢士之所總，禮義之所集，财用之所殖也。夫以智謀愚，以義伐不義，若因秋霜而振落葉。《春秋》曰：“桓公之與戎、狄、驅之爾。”况以天下之力乎？”","sortOrder":20},
  {"id":"s_work_dtl_9_21","chapterId":"ch_work_dtl_9","text":"文學曰：“匈奴車器無銀黃絲漆之飾，素成而務堅，絲無文采裙袆曲襟之製，都成而務完。男無刻鏤奇巧之事，宮室城郭之功。女無綺繡淫巧之貢，纖綺羅紈之作。事省而致用，易成而難弊。雖無修戟強弩，戎馬良弓；家有其備，人有其用，一旦有急，貫弓上馬而已。資糧不見案首，而支數十日之食，因山穀為城郭，因水草為仓廪。法約而易辨，求寡而易供。是以刑省而不犯，指麾而令從。嫚於禮而篤於信，略於文而敏於事。故雖無禮義之書，刻骨卷木，百官有以相記，而君臣上下有以相使。群臣為縣官計者，皆言其易，而實難，是以秦欲驅之而反更亡也。故兵者凶器，不可輕用也。其以強為弱，以存為亡，一朝爾也。”","sortOrder":21},
  {"id":"s_work_dtl_9_22","chapterId":"ch_work_dtl_9","text":"大夫曰：“魯連有言：‘秦權使其士，虜使其民。’故政急而不長。高皇帝受命平暴亂，功德巍巍，惟天同大焉。而文、景承緒润色之。及先帝征不義，攘無德，以昭仁聖之路，純至德之基，聖王累年仁義之積也。今文學引亡國失政之治，而况之於今，其謂匈奴難圖，宜矣！”","sortOrder":22},
  {"id":"s_work_dtl_9_23","chapterId":"ch_work_dtl_9","text":"文學曰：“有虞氏之時，三苗不服，禹欲伐之，舜曰：‘是吾德未喻也。’退而修政，而三苗服。不牧之地，不羁之民，聖王不加兵，不事力焉，以為不足煩百姓而勞中國也。今明主修聖緒，宣德化，而朝有權使之謀，尚首功之事，臣固怪之。夫人臣席天下之势，奋國家之用，身享其利而不顧其主，此尉佗、章邯所以成王，秦失其政也。孫子曰：‘今夫國家之事，一日更百变，然而不亡者，可得而革也。逮出兵乎平原廣牧，鼓鳴矢流，雖有尧、舜之知，不能更也。’戰而勝之，退修禮義，繼三代之跡，仁義附矣。戰勝而不休，身死國亡者，吳王是也。”","sortOrder":23},
  {"id":"s_work_dtl_9_24","chapterId":"ch_work_dtl_9","text":"大夫曰：“順風而呼者易為氣，因時而行者易為力。文、武懷餘力，不為後嗣計，故三世而德衰，昭王南征，死而不還。凡伯囚執，而使不通，晉取郊、沛，王師败於茅戎。今西南諸夷，楚莊之後；朝鮮之王，燕之亡民也。南越尉佗起中國，自立為王，德至薄，然皆亡天下之大，各自以為一州，倔強倨敖，自稱老夫。先帝為萬世度，恐有冀州之累，南荆之患，於是遣左將軍樓船平之，兵不血刃，鹹為縣官也。七國之時，皆據萬乘，南面稱王，提珩為敵國累世，然終不免俯首系虜於秦。今匈奴不當漢家之巨郡，非有六國之用，賢士之謀。由此觀難易，察然可見也。”","sortOrder":24},
  {"id":"s_work_dtl_9_25","chapterId":"ch_work_dtl_9","text":"文學曰：“秦滅六國，虜七王，沛然有餘力，自以為蚩尤不能害，黃帝不能斥。及二世弒死望夷，子婴系頸降楚，曾不得七王之俯首。使六國併存，秦尚為戰國，固未亡也。何以明之？自孝公以至於始皇，世世為諸侯雄，百有餘年。及兼天下，十四歲而亡。何則？外無敵國之忧，而內自縱恣也。自非聖人，得志而不驕佚者，未之有也。”","sortOrder":25},
  {"id":"s_work_dtl_9_26","chapterId":"ch_work_dtl_9","text":"◎論邹第五十三","sortOrder":26},
  {"id":"s_work_dtl_9_27","chapterId":"ch_work_dtl_9","text":"大夫曰：“邹子疾晚世之儒墨，不知天地之弘，昭曠之道，將一曲而欲道九折，守一隅而欲知萬方，猶無准平而欲知高下，無規矩而欲知方圓也。於是推大聖終始之運，以喻王公，先列中國名山通穀，以至海外。所謂中國者，天下八十一分之一，名曰赤縣神州，而分為九州。絕陵陆不通，乃為一州，有大瀛海圜其外。此所謂八極，而天地际焉。《禹貢》亦著山川高下原隰，而不知大道之径。故秦欲達九州而方瀛海，牧胡而朝萬國。諸生守畦畝之慮，闾巷之固，未知天下之義也。”","sortOrder":27},
  {"id":"s_work_dtl_9_28","chapterId":"ch_work_dtl_9","text":"文學曰：“尧使禹為司空，平水土，隨山刊木，定高下而序九州。邹衍非聖人，作怪誤，熒惑六國之君，以納其說。此《春秋》所謂‘匹夫熒惑諸侯’者也。孔子曰：‘未能事人，焉能事鬼神？’近者不達，焉能知瀛海？故無補於用者，君子不為；無益於治者，君子不由。三王信經道，而德光於四海；戰國信嘉言，而破亡如丘山。昔秦始皇已吞天下，欲併萬國，亡其三十六郡；欲達瀛海，而失其州縣。知大義如斯，不如守小計也。”","sortOrder":28},
  {"id":"s_work_dtl_9_29","chapterId":"ch_work_dtl_9","text":"◎論菑第五十四","sortOrder":29},
  {"id":"s_work_dtl_9_30","chapterId":"ch_work_dtl_9","text":"大夫曰：“巫祝不可與併祀，諸生不可與逐語，信往疑今，非人自是。夫道古者稽之今，言遠者合之近。日月在天，其征在人，菑異之变，夭寿之期，陰陽之化，四時之叙，水火金木，妖祥之應，鬼神之靈，祭祀之福，日月之行，星辰之紀，曲言之故，何所本始？不知則默，無苟亂耳。”","sortOrder":30},
  {"id":"s_work_dtl_9_31","chapterId":"ch_work_dtl_9","text":"文學曰：“始江都相董生推言陰陽，四時相繼，父生之，子養之，母成之，子藏之。故春生，仁；夏長，德；秋成，義；冬藏，禮。此四時之序，聖人之所則也。刑不可任以成化，故廣德教。言遠必考之邇，故內恕以行，是以刑罰若加於己，勤勞若施於身。又安能忍殺其赤子，以事無用，罢弊所恃，而達瀛海乎？蓋越人美蠃蚌而簡太牢，鄙夫樂咋唶而怪韶濩。故不知味者，以芬香為臭，不知道者，以美言為亂耳。人無夭寿，各以其好惡為命。羿、敖以巧力不得其死，智伯以貪狠亡其身。天菑之證，禎祥之應，猶施與之望報，各以其類及。故好行善者，天助以福，符瑞是也。《易》曰：‘自天佑之，吉無不利。’好行惡者，天報以禍，妖菑是也。《春秋》曰：‘應是而有天菑。’周文、武尊賢受諫，敬戒不殆，純德上休，神只相况。《詩》雲：‘降福穰穰，降福簡簡。’日者陽，陽道明；月者陰，陰道冥；君尊臣卑之義。故陽光盛於上，眾陰之類消於下；月望於天，蚌蛤盛於淵。故臣不臣，則陰陽不調，日月有变；政教不均，則水旱不時，螟螣生。此灾異之應也。四時代叙，而人則其功，星列於天，而人象其行。常星猶公卿也，眾星猶萬民也。列星正則眾星齊，常星亂則眾星墜矣。”","sortOrder":31},
  {"id":"s_work_dtl_9_32","chapterId":"ch_work_dtl_9","text":"大夫曰：“文學言刚柔之類，五勝相代生。《易》明於陰陽，《書》長於五行。春生夏長，故火生於寅木，陽類也；秋生冬死，故水生於申金，陰物也。四時五行，迭废迭興，陰陽異類，水火不同器。金得土而成，得火而死，金生於巳，何說何言然乎？”","sortOrder":32},
  {"id":"s_work_dtl_9_33","chapterId":"ch_work_dtl_9","text":"文學曰：“兵者，凶器也。甲堅兵利，為天下殃。以母製子，故能久長。聖人法之，厭而不陽。《詩》雲：‘載戢幹戈，載橐弓矢，我求懿德，肆於時夏。’衰世不然。逆天道以快暴心，僵尸血流，以爭壤土。牢人之君，滅人之祀，殺人之子，若絕草木，刑者肩靡於道。以己之所惡而施於人。是以國家破滅，身受其殃，秦王是也。”","sortOrder":33},
  {"id":"s_work_dtl_9_34","chapterId":"ch_work_dtl_9","text":"大夫曰：“金生於巳，刑罰小加，故荠麥夏死。《易》曰：‘履霜，堅冰至。’秋始降霜，草木陨零，合冬行誅，萬物畢藏。春夏生長，利以行仁。秋冬殺藏，利以施刑。故非其時而树，雖生不成。秋冬行德，是謂逆天道。《月令》：‘涼風至，殺氣動，蜻蛚鳴，衣裘成。天子行微刑，始貙蒌，以順天令。’文學同四時，合陰陽，尚德而除刑。如此，則鷹隼不鷙，猛獸不攫，秋不搜狝，冬不田狩者也。”","sortOrder":34},
  {"id":"s_work_dtl_9_35","chapterId":"ch_work_dtl_9","text":"文學曰：“天道好生惡殺，好賞惡罪。故使陽居於實而宣德施，陰藏於虛而為陽佐辅。陽刚陰柔，季不能加孟。此天賤冬而貴春，申陽屈陰。故王者南面而聽天下，背陰向陽，前德而後刑也。霜雪晚至，五穀猶成。雹霧夏陨，萬物皆傷。由此觀之：嚴刑以治國，猶任秋冬以成穀也。故法令者，治惡之具也，而非至治之風也。是以古者，明王茂其德教，而缓其刑罰也。網漏吞舟之魚，而刑審於繩墨之外，及臻其末，而民莫犯禁也。”","sortOrder":35},
  {"id":"s_work_dtl_9_36","chapterId":"ch_work_dtl_9","text":"《鹽鐵論》　西漢桓宽","sortOrder":36},
  {"id":"s_work_dtl_10_1","chapterId":"ch_work_dtl_10","text":"卷十","sortOrder":1},
  {"id":"s_work_dtl_10_2","chapterId":"ch_work_dtl_10","text":"◎刑德第五十五","sortOrder":2},
  {"id":"s_work_dtl_10_3","chapterId":"ch_work_dtl_10","text":"大夫曰：“令者所以教民也，法者所以督奸也。令嚴而民慎，法設而奸禁。罔疏則獸失，法疏則罪漏。罪漏則民放佚而輕犯禁。故禁不必，怯夫徼幸；誅誠，跖、蹻不犯。是以古者作五刑，刻肌膚而民不逾矩。”","sortOrder":3},
  {"id":"s_work_dtl_10_4","chapterId":"ch_work_dtl_10","text":"文學曰：“道径眾，人不知所由；法令眾，民不知所辟。故王者之製法，昭乎如日月，故民不迷；曠乎若大路，故民不惑。幽隱遠方，折乎知之，室女童婦，鹹知所避。是以法令不犯，而獄犴不用也。昔秦法繁於秋荼，而網密於凝脂。然而上下相遁，奸伪萌生，有司治之，若救烂扑焦，而不能禁；非網疏而罪漏，禮義废而刑罰任也。方今律令百有餘篇，文章繁，罪名重，郡國用之疑惑，或淺或深，自吏明習者，不知所處，而况愚民！律令尘蠹於栈閣，吏不能遍睹，而况於愚民乎！此斷獄所以滋眾，而民犯禁滋多也。‘宜犴宜獄，握粟出卜，自何能穀？’刺刑法繁也。親服之屬甚眾，上殺下殺，而服不過五。五刑之屬三千，上附下附，而罪不過五。故治民之道，務篤其教而已。”","sortOrder":4},
  {"id":"s_work_dtl_10_5","chapterId":"ch_work_dtl_10","text":"大夫曰：“文學言王者立法，曠若大路。今馳道不小也，而民公犯之，以其罰罪之輕也。千仞之高，人不輕凌，千鈞之重，人不輕舉。商君刑弃灰於道，而秦民治。故盜馬者死，盜牛者加，所以重本而絕輕疾之資也。武兵名食，所以佐邊而重武備也。盜傷與殺同罪，所以累其心而责其意也。猶魯以楚師伐齊，而《春秋》惡之。故輕之為重，淺之為深，有緣而然。法之微者，固非眾人之所知也。”","sortOrder":5},
  {"id":"s_work_dtl_10_6","chapterId":"ch_work_dtl_10","text":"文學曰：“《詩》雲：‘周道如砥，其直如矢。’言其易也。‘君子所履，小人所视。’言其明也。故德明而易從，法約而易行今馳道經營陵陆，紆周天下，是以萬里為民阱也。罻羅張而縣其穀，辟陷設而當其蹊，矰弋飾而加其上，能勿離乎？聚其所欲，开其所利，仁義陵遲，能勿逾乎？故其末途，至於攻城入邑，損府库之金，盜宗廟之器，豈特千仞之高、千鈞之重哉！管子曰：‘四維不張，雖皋陶不能為士。’故德教废而诈伪行，禮義坏而奸邪興，言無仁義也。仁者，愛之效也；義者，事之宜也。故君子愛仁以及物，治近以及遠。《傳》曰：‘凡生之物，莫貴於人；人主之所貴，莫重於人。’故天之生萬物以奉人也，主愛人以順天也。聞以六畜禽獸養人，未聞以所養害人者也。魯廄焚，孔子罢朝，問人不問馬，賤畜而重人也。今盜馬者罪死，盜牛者加。乘騎車馬行馳道中，吏舉苛而不止，以為盜馬，而罪亦死。今傷人持其刀劍而亡，亦可謂盜武库兵而殺之乎？人主立法而民犯之，亦可以為逆而輕主約乎？深之可以死，輕之可以免，非法禁之意也。法者，緣人情而製，非設罪以陷人也。故《春秋》之治獄，論心定罪。志善而违於法者免，志惡而合於法者誅。今傷人未有所害，志不甚惡而合於法者，謂盜而傷人者耶？將執法者過耶？何於人心不厭也！古者，傷人有創者刑，盜有臧者罰，殺人者死。今取人兵刃以傷人，罪與殺人同，得無非其至意與？”","sortOrder":6},
  {"id":"s_work_dtl_10_7","chapterId":"ch_work_dtl_10","text":"大夫俯仰未應對。","sortOrder":7},
  {"id":"s_work_dtl_10_8","chapterId":"ch_work_dtl_10","text":"御史曰：“執法者國之辔衔，刑罰者國之維楫也。故辔衔不飭，雖王良不能以致遠；維楫不設，雖良工不能以絕水。韓子疾有國者不能明其法势，御其臣下，富國強兵，以製敵御難，惑於愚儒之文詞，以疑賢士之謀，舉浮淫之蠹，加之功實之上，而欲國之治，猶釋階而欲登高，無衔橛而御捍馬也。今刑法設備，而民猶犯之，况無法乎？其亂必也！”","sortOrder":8},
  {"id":"s_work_dtl_10_9","chapterId":"ch_work_dtl_10","text":"文學曰：“辔衔者，御之具也，得良工而調。法势者，治之具也，得賢人而化。執辔非其人，則馬奔馳。執軸非其人，則船覆傷。昔吳使宰嚭持軸而破其船，秦使趙高執辔而覆其車。今废仁義之術，而任刑名之徒，則复吳、秦之事也。夫為君者法三王，為相者法周公，為術者法孔子，此百世不易之道也。韓非非先王而不遵，舍正令而不從，卒蹈陷阱，身幽囚，客死於秦。夫不通大道而小辯，斯足以害其身而已。”","sortOrder":9},
  {"id":"s_work_dtl_10_10","chapterId":"ch_work_dtl_10","text":"◎申韓第五十六","sortOrder":10},
  {"id":"s_work_dtl_10_11","chapterId":"ch_work_dtl_10","text":"御史曰：“待周公而為相，則世無列國。待孔子而後學，則世無儒、墨。夫衣小缺，〈巾祭〉裂可以補，而必待全匹而易之；政小缺，法令可以防，而必待《雅》、《頌》乃治之；是猶舍鄰之医，而求俞跗而後治病，废污池之水，待江、海而後救火也。迂而不径，闕而無務，是以教令不從而治煩亂。夫善為政者，弊則補之，决則塞之，故吳子以法治楚、魏，申、商以法強秦、韓也。”","sortOrder":11},
  {"id":"s_work_dtl_10_12","chapterId":"ch_work_dtl_10","text":"文學曰：“有國者選眾而任賢，學者博覽而就善，何必是周公、孔子！故曰法之而已。今商鞅反聖人之道，变亂秦俗，其後政耗亂而不能治，流失而不可复，愚人縱火於沛泽，不能复振；蜂蠆螫人，放死不能息其毒也。煩而止之，躁而靜之，上下勞扰，而亂益滋。故聖人教化，上與日月俱照，下與天地同流，豈曰小補之哉！”","sortOrder":12},
  {"id":"s_work_dtl_10_13","chapterId":"ch_work_dtl_10","text":"御史曰：“衣缺不補，則日以甚，防漏不塞，則日益滋。大河之始决於瓠子也，涓涓爾，及其卒，泛濫為中國害，菑梁、楚，破曹、衛，城郭坏沮，蓄積漂流，百姓木栖，千里無庐，令孤寡無所依，老弱無所歸。故先帝闵悼其菑，親省河堤，舉禹之功，河流以复，曹、衛以寧。百姓戴其功，詠其德，歌‘宣房塞，萬福來’焉，亦猶是也，如何勿小補哉！”","sortOrder":13},
  {"id":"s_work_dtl_10_14","chapterId":"ch_work_dtl_10","text":"文學曰：“河决若瓮口，而破千里，况禮决乎？其所害亦多矣！今斷獄歲以萬計，犯法茲多，其為菑豈特曹、衛哉！夫知塞宣房而福來，不知塞亂原而天下治也。周國用之，刑错不用，黎民若，四時各終其序，而天下不孤。《頌》曰：‘綏我眉寿，介以繁祉。’此夫為福，亦不小矣！誠信禮義如宣房，功業已立，垂拱無為，有司何補，法令何塞也？”","sortOrder":14},
  {"id":"s_work_dtl_10_15","chapterId":"ch_work_dtl_10","text":"御史曰：“犀铫利鉏，五穀之利而間草之害也。明理正法，奸邪之所惡而良民之福也。故曲木惡直繩，奸邪惡正法。是以聖人審於是非，察於治亂，故設明法，陳嚴刑，防非矯邪，若隱括辅檠之正弧刺也。故水者火之備，法者止奸之禁也。無法势，雖賢人不能以為治；無甲兵，雖孫、吳不能以製敵。是以孔子倡以仁義而民從風，伯夷遁首陽而民不可化。”","sortOrder":15},
  {"id":"s_work_dtl_10_16","chapterId":"ch_work_dtl_10","text":"文學曰：“法能刑人而不能使人廉，能殺人而不能使人仁。所貴良医者，貴其審消息而退邪氣也，非貴其下針石而鑽肌膚也。所貴良吏者，貴其絕惡於未萌，使之不為，非貴其拘之囹圄而刑殺之也。今之所謂良吏者，文察則以禍其民，強力則以厲其下，不本法之所由生，而专己之殘心，文誅假法，以陷不辜，累無罪，以子及父，以弟及兄，一人有罪，州里驚駭，十家奔亡，若痈疽之相濘，色淫之相連，一節動而百枝搖。《詩》雲：‘舍彼有罪，淪胥以鋪。’痛傷無罪而累也。非患铫耨之不利，患其舍草而芸苗也。非患無准平，患其舍枉而繩直也。故親近為過不必誅，是鋤不用也；疏遠有功不必賞，是苗不養也。故世不患無法，而患無必行之法也。”","sortOrder":16},
  {"id":"s_work_dtl_10_17","chapterId":"ch_work_dtl_10","text":"◎周秦第五十七","sortOrder":17},
  {"id":"s_work_dtl_10_18","chapterId":"ch_work_dtl_10","text":"御史曰：“《春秋》無名號，謂之雲盜，所以賤刑人而絕之人倫也。故君不臣，士不友，於闾里無所容。故民恥犯之。今不軌之民，犯公法以相寵，舉弃其親，不能伏節死理，遁逃相連，自陷於罪，其被刑戮，不亦宜乎？一室之中，父兄之际，若身體相屬，一節動而知於心。故今自闕內侯以下，比地於伍，居家相察，出入相司，父不教子，兄不正弟，舍是誰责乎？”","sortOrder":18},
  {"id":"s_work_dtl_10_19","chapterId":"ch_work_dtl_10","text":"文學曰：“古者，周其禮而明其教，禮周教明，不從者然後等之以刑，刑罰中，民不怨。故舜施四罪而天下鹹服，誅不仁也。輕重各服其誅，刑必加而無赦，赦惟疑者。若此，則世安得不軌之人而罪之？今殺人者生，剽攻竊盜者富。故良民內解怠，輟耕而陨心。古者，君子不近刑人，刑人非人也，身放殛而辱後世，故無賢不肖，莫不恥也。今無行之人，貪利以陷其身，蒙戮辱而損禮義，恒於苟生。何者？一日下蠶室，創未瘳，宿衛人主，出入宮殿，由得受奉祿，食大官享賜，身以尊榮，妻子獲其饒。故或載卿相之列，就刀鋸而不見闵，况眾庶乎？夫何恥之有！今废其德教，而责之以禮義，是虐民也。《春秋傳》曰：‘子有罪，執其父。臣有罪，執其君，聽失之大者也。’今以子誅父，以弟誅兄，親戚相坐，什伍相連，若引根本之及華葉，傷小指之累四體也。如此，則以有罪反誅無罪，無罪者寡矣。臧文仲治魯，勝其盜而自矜。子貢曰：‘民將欺，而况盜乎！’故吏不以多斷為良，医不以多刺為工。子產刑二人，殺一人，道不拾遺，而民無誣心。故為民父母，以養疾子，長恩厚而已。自首匿相坐之法立，骨肉之恩废，而刑罪多矣。父母之於子，雖有罪猶匿之，其不欲服罪爾。聞子為父隱，父為子隱，未聞父子之相坐也。聞兄弟缓追以免賊，未聞兄弟之相坐也。聞惡惡止其人，疾始而誅首惡，未聞什伍而相坐也。《老子》曰：‘上無欲而民朴，上無事而民自富。’君君臣臣，父父子子。比地何伍，而執政何责也？”","sortOrder":19},
  {"id":"s_work_dtl_10_20","chapterId":"ch_work_dtl_10","text":"御史曰：“夫負千鈞之重，以登無極之高，垂峻崖之峭穀，下臨不测之淵，雖有慶忌之捷，贲、育之勇，莫不震慑悼栗者，知墜則身首肝腦涂山石也。故未嘗灼而不敢握火者，見其有灼也。未嘗傷而不敢握刃者，見其有傷也。彼以知為非，罪之必加，而戮及父兄，必懼而為善。故立法製辟，若臨百仞之壑，握火蹈刃，則民畏忌，而無敢犯禁矣。慈母有败子，小不忍也。嚴家無悍虜，篤责急也。今不立嚴家之所以製下，而修慈母之所以败子，則惑矣。”","sortOrder":20},
  {"id":"s_work_dtl_10_21","chapterId":"ch_work_dtl_10","text":"文學曰：“紂為炮烙之刑，而秦有收帑之法，趙高以峻文决罪於內，百官以峭法斷割於外，死者相枕席，刑者相望，百姓侧目重足，不寒而栗。《詩》雲：‘謂天蓋高，不敢不局。謂地蓋厚，不敢不蹐。哀今之人，胡為虺蜥！’方此之時，豈特冒蹈刃哉？然父子相背，兄弟相嫚，至於骨肉相殘，上下相殺。非刑輕而罰不必，令太嚴而仁恩不施也。故政宽則下親其上，政嚴則民謀其主，晉厲以幽，二世見殺，惡在峻法之不犯，嚴家之無悍虜也？聖人知之，是以務和而不務威。故高皇帝約秦苛法，以慰怨毒之民，而長和睦之心，唯恐刑之重而德之薄也。是以恩施無窮，泽流後世。商鞅、吳起以秦、楚之法為輕而累之，上危其主，下没其身，或非特慈母乎！”","sortOrder":21},
  {"id":"s_work_dtl_10_22","chapterId":"ch_work_dtl_10","text":"◎詔聖第五十八","sortOrder":22},
  {"id":"s_work_dtl_10_23","chapterId":"ch_work_dtl_10","text":"御史曰：“夏後氏不倍言，殷誓，周盟，德信弥衰。無文、武之人，欲修其法，此殷、周之所以失势，而見奪於諸侯也。故衣弊而革才，法弊而更製。高皇帝時，天下初定，發德音，行一切之令，權也，非拨亂反正之常也。其後，法稍犯，不正於理。故奸萌而《甫刑》作，王道衰而《詩》刺彰，諸侯暴而《春秋》譏。夫少目之網不可以得魚，三章之法不可以為治。故令不得不加，法不得不多。唐、虞畫衣冠非阿，湯、武刻肌膚非故，時世不同，輕重之務異也。”","sortOrder":23},
  {"id":"s_work_dtl_10_24","chapterId":"ch_work_dtl_10","text":"文學曰：“民之仰法，猶魚之仰水，水清則靜，濁則扰；扰則不安其居，靜則樂其業；樂其業則富，富則仁生，贍則爭止。是以成、康之世，賞無所施，法無所加。非可刑而不刑，民莫犯禁也；非可賞而不賞，民莫不仁也。若斯，則吏何事而理？今之治民者，若拙御之御馬也，行則頓之，止則击之。身創於棰，吻傷於衔，求其無失，何可得乎？幹溪之役土崩，梁氏內潰，嚴刑不能禁，峻法不能止。故罢馬不畏鞭棰，罢民不畏刑法。雖曾而累之，其亡益乎？”","sortOrder":24},
  {"id":"s_work_dtl_10_25","chapterId":"ch_work_dtl_10","text":"御史曰：“嚴牆三刃，樓季難之；山高幹雲，牧竖登之。故峻則樓季難三刃，陵夷則牧竖易山巔。夫烁金在爐，莊蹻不顧；錢刀在路，匹婦掇之；非匹婦貪而莊蹻廉也，輕重之製異，而利害之分明也。故法令可仰而不可逾，可臨而不可入。《詩》雲：‘不可暴虎，不敢冯河。’為其無益也。魯好禮而有季、孟之難，燕哙好讓而有子之之亂。禮讓不足禁邪，而刑法可以止暴。明君據法，故能長製群下，而久守其國也。”","sortOrder":25},
  {"id":"s_work_dtl_10_26","chapterId":"ch_work_dtl_10","text":"文學曰：“古者，明其仁義之誓，使民不逾；不教而殺，是虐民也。與其刑不可逾，不若義之不可逾也。聞禮義行而刑罰中，未聞刑罰行而孝悌興也。高牆狹基，不可立也。嚴刑峻法，不可久也。二世信趙高之計，渫篤责而任誅斷，刑者半道，死者日積。殺民多者為忠，厲民悉者為能。百姓不勝其求，黔首不勝其刑，海內同忧而俱不聊生。故過任之事，父不得於子；無已之求，君不得於臣。死不再生，窮鼠嚙狸，匹夫奔萬乘，舍人折弓，陳勝、吳廣是也。當此之時，天下俱起，四面而攻秦，聞不一期而社稷為墟，惡在其能長製群下，而久守其國也？”","sortOrder":26},
  {"id":"s_work_dtl_10_27","chapterId":"ch_work_dtl_10","text":"御史默然不對。","sortOrder":27},
  {"id":"s_work_dtl_10_28","chapterId":"ch_work_dtl_10","text":"大夫曰：“瞽師不知白黑而善聞言，儒者不知治世而善訾議。夫善言天者合之人，善言古者考之今。令何為施？法何為加？湯、武全肌骨而殷、周治，秦國用之，法弊而犯。二尺四寸之律，古今一也，或以治，或以亂。春秋原罪，甫刑製獄。今願聞治亂之本，周、秦所以然乎？”","sortOrder":28},
  {"id":"s_work_dtl_10_29","chapterId":"ch_work_dtl_10","text":"文學曰：“春夏生長，聖人象而為令。秋冬殺藏，聖人則而為法。故令者教也，所以导民人；法者刑罰也，所以禁強暴也。二者，治亂之具，存亡之效也，在上所任。湯、武經禮義，明好惡，以道其民，刑罪未有所加，而民自行義，殷、周所以治也。上無德教，下無法則，任刑必誅，劓鼻盈蔂，斷足盈車，舉河以西，不足以受天下之徒，終而以亡者，秦王也。非二尺四寸之律異，所行反古而悖民心也。”","sortOrder":29},
  {"id":"s_work_dtl_10_30","chapterId":"ch_work_dtl_10","text":"◎大論第五十九","sortOrder":30},
  {"id":"s_work_dtl_10_31","chapterId":"ch_work_dtl_10","text":"大夫曰：“呻S吟Y槁簡，誦死人之語，則有司不以文學。文學知獄之在廷後而不知其事，聞其事而不知其務。夫治民者，若大匠之斫，斧斤而行之，中繩則止。杜大夫、王中尉之等，繩之以法，斷之以刑，然後寇止奸禁。故射者因槷，治者因法。虞、夏以文，殷、周以武，異時各有所施。今欲以敦朴之時，治抏弊之民，是猶遷延而拯溺，揖讓而救火也。”","sortOrder":31},
  {"id":"s_work_dtl_10_32","chapterId":"ch_work_dtl_10","text":"文學曰：“文王興而民好善，幽、厲興而民好暴，非性之殊，風俗使然也。故商、周之所以昌，桀、紂之所以亡也，湯、武非得伯夷之民以治，桀、紂非得跖、蹻之民以亂也，故治亂不在於民。孔子曰：‘聽訟吾猶人也，必也使無訟乎！’無訟者難，訟而聽之易。夫不治其本而事其末，古之所謂愚，今之所謂智。以棰楚正亂，以刀筆正文，古之所謂賊，今之所謂賢也。”","sortOrder":32},
  {"id":"s_work_dtl_10_33","chapterId":"ch_work_dtl_10","text":"大夫曰：“俗非唐、虞之時，而世非許由之民，而欲废法以治，是猶不用隱括斧斤，欲撓曲直枉也。故為治者不待自善之民，為輪者不待自曲之木。往者，應少、伯正之屬潰梁、楚，崑盧、徐穀之徒亂齊、趙，山東、關內暴徒，保人阻险。當此之時，不任斤斧，折之以武，而乃始設禮修文，有似窮医，欲以短針而攻疽，孔丘以禮說跖也。”","sortOrder":33},
  {"id":"s_work_dtl_10_34","chapterId":"ch_work_dtl_10","text":"文學曰：“殘材木以成室屋者，非良匠也。殘賊民人而欲治者，非良吏也。故公输子因木之宜，聖人不費民之性。是以斧斤簡用，刑罰不任，政立而化成。扁鵲攻於凑理，絕邪氣，故痈疽不得成形。聖人從事於未然，故亂原無由生。是以砭石藏而不施，法令設而不用。斷已然，凿已發者，凡人也。治未形，睹未萌者，君子也。”","sortOrder":34},
  {"id":"s_work_dtl_10_35","chapterId":"ch_work_dtl_10","text":"大夫曰：“文學所稱聖知者，孔子也，治魯不遂，見逐於齊，不用於衛，遇围於匡，困於陳、蔡。夫知時不用猶說，強也；知困而不能已，貪也；不知見欺而往，愚也；困辱不能死，恥也。若此四者，庸民之所不為也，而况君子乎！商君以景監見，應侯以王稽進。故士因士，女因媒。至其親顯，非媒士之力。孔子不以因進見而能往者，非賢士才女也。”","sortOrder":35},
  {"id":"s_work_dtl_10_36","chapterId":"ch_work_dtl_10","text":"文學曰：“孔子生於亂世，思尧、舜之道，東西南北，灼頭濡足，庶幾世主之悟。悠悠者皆是，君闇，大夫妒，孰合有媒？是以嫫母飾姿而矜夸，西子彷徨而無家。非不知窮厄而不見用，悼痛天下之禍，猶慈母之伏死子也，知其不可如何，然惡已。故適齊，景公欺之，適衛，靈公围，陽虎謗之，桓魋害之。夫欺害聖人者，愚惑也；傷毀聖人者，狂狡也。狡惑之人，非人也。夫何恥之有！孟子曰：‘觀近臣者以所為主，觀遠臣者以其所主。’使聖人伪容苟合，不論行擇友，則何以為孔子也！”","sortOrder":36},
  {"id":"s_work_dtl_10_37","chapterId":"ch_work_dtl_10","text":"大夫撫然內慚，四據而不言。","sortOrder":37},
  {"id":"s_work_dtl_10_38","chapterId":"ch_work_dtl_10","text":"當此之時，順風承意之士如編，口張而不歙，舌舉而不下，闇然而懷重負而見责。","sortOrder":38},
  {"id":"s_work_dtl_10_39","chapterId":"ch_work_dtl_10","text":"大夫曰：“诺，膠車倏逢雨，請與諸生解。”","sortOrder":39},
  {"id":"s_work_dtl_10_40","chapterId":"ch_work_dtl_10","text":"◎雜論第六十","sortOrder":40},
  {"id":"s_work_dtl_10_41","chapterId":"ch_work_dtl_10","text":"客曰：“餘睹鹽、鐵之義，觀乎公卿、文學、賢良之論，意指殊路，各有所出，或上仁義，或務權利。”","sortOrder":41},
  {"id":"s_work_dtl_10_42","chapterId":"ch_work_dtl_10","text":"“異哉吾所聞。周、秦粲然，皆有天下而南面焉，然安危長久殊世。始汝南朱子伯為予言：當此之時，豪俊併進，四方輻凑。賢良茂陵唐生、文學魯國萬生之倫，六十餘人，鹹聚闕庭，舒《六藝》之風，論太平之原。智者贊其慮，仁者明其施，勇者見其斷，辯者陳其詞。訚訚焉，侃侃焉，雖未能詳備，斯可略觀矣。然蔽於雲霧，終废而不行，悲夫！公卿知任武可以辟地，而不知廣德可以附遠；知權利可以廣用，而不知稼穡可以富國也。近者親附，遠者說德，則何為而不成，何求而不得？不出於斯路，而務畜利長威，豈不谬哉！中山劉子雍言王道，矯當世，复諸正，務在乎反本。直而不徼，切而不〈火索〉，斌斌然斯可謂弘博君子矣。九江祝生奋由、路之意，推史魚之節，發憤懣，刺譏公卿，介然直而不撓，可謂不畏強御矣。桑大夫據當世，合時变，推道術，尚權利，辟略小辯，雖非正法，然巨儒宿學恧然，不能自解，可謂博物通士矣。然攝卿相之位，不引准繩，以道化下，放於利末，不師始古。《易》曰：‘焚如弃如。’處非其位，行非其道，果陨其性，以及厥宗。車丞相即周、呂之列，當軸處中，括囊不言，容身而去，彼哉！彼哉！若夫群丞相、御史，不能正議，以辅宰相，成同類，長同行，阿意苟合，以說其上，斗筲之人，道諛之徒，何足算哉。","sortOrder":42},
];

